// ExamPro PMP Exam Bank — PMBOK 8 / PMP Sims source
// 180 full-length mock questions used by both the PMP Sims tab and Exam generator.
const PMP_MOCK_RAW=[{"n":1,"opts":{"A":"The risk register","B":"The change log","C":"The issue log","D":"The lessons learned register"},"caseTitle":"Case Study 1: Governance Overreach","caseText":"A project manager is leading an 18-month enterprise resource planning (ERP) implementation for a mid-sized manufacturing company. The project sponsor, the company’s Chief Operating Officer (COO), is under pressure from the board of directors to demonstrate measurable operational improvements before the fiscal year closes. The approved project scope includes system configuration, data migration, and user training across three departments.\n\nMidway through execution, the COO requests that the project team integrate a financial reporting module that was explicitly excluded from the approved scope, describing it as a minor addition that does not require formal review. The project manager estimates the addition would require three additional weeks and $40,000 in unbudgeted costs.\n\nThe COO has since begun attending weekly project status meetings and issuing direct task assignments to team members without the project manager’s involvement. When the project manager raised concerns, the COO dismissed them, stating the delivery date is non-negotiable and the team should “do whatever it takes.”\n\nThe project manager has documented the COO’s informal requests in meeting notes but has not yet taken further action. With the fiscal year deadline approaching and the team showing signs of confusion over conflicting direction, the project manager must decide how to proceed.","q":"The project manager has documented the COO’s ongoing interference in meeting notes but has not recorded it in any formal project document. What is the appropriate project document to formally capture this situation?","exp":"C. The COO’s interference is already occurring, making it an issue rather than a risk. Issues are active problems requiring resolution and belong in the issue log, which tracks the problem, assigns ownership, and monitors resolution progress.\n\nWhy other options are incorrect:\n\nThe risk register captures uncertain future events that may or may not occur. Since the COO’s interference is already happening, it does not qualify as a risk.\n\nThe change log tracks approved and rejected changes to project baselines. The COO’s behavior is not a change to a scope, schedule, or cost baseline.\n\nThe lessons learned register captures knowledge to inform future projects. It is not the appropriate tool for managing an active problem during execution.","ans":"C","hint":""},{"n":2,"opts":{"A":"Agile","B":"Hybrid","C":"Incremental","D":"Predictive"},"caseTitle":"Case Study 1: Governance Overreach","caseText":"A project manager is leading an 18-month enterprise resource planning (ERP) implementation for a mid-sized manufacturing company. The project sponsor, the company’s Chief Operating Officer (COO), is under pressure from the board of directors to demonstrate measurable operational improvements before the fiscal year closes. The approved project scope includes system configuration, data migration, and user training across three departments.\n\nMidway through execution, the COO requests that the project team integrate a financial reporting module that was explicitly excluded from the approved scope, describing it as a minor addition that does not require formal review. The project manager estimates the addition would require three additional weeks and $40,000 in unbudgeted costs.\n\nThe COO has since begun attending weekly project status meetings and issuing direct task assignments to team members without the project manager’s involvement. When the project manager raised concerns, the COO dismissed them, stating the delivery date is non-negotiable and the team should “do whatever it takes.”\n\nThe project manager has documented the COO’s informal requests in meeting notes but has not yet taken further action. With the fiscal year deadline approaching and the team showing signs of confusion over conflicting direction, the project manager must decide how to proceed.","q":"Based on the details provided, which development approach is the project using?","exp":"D. The scenario suggests a predictive approach because the project has an approved scope baseline, the requested module was explicitly excluded from scope, and the impact of adding it is assessed against schedule and cost constraints. These are signs of a plan-driven environment where work is managed against established baselines and changes require formal review.\n\nWhy other options are incorrect:\n\nThe scenario contains no agile indicators such as iterative delivery cycles, a product backlog, or self-organizing team structures.\n\nA hybrid approach combines predictive and agile elements. Since no agile elements are present, hybrid does not apply.\n\nIncremental delivery describes how outputs are released, not how a project is managed. There is no evidence of phased or incremental releases in the scenario, and incremental delivery alone does not define a development approach.","ans":"D","hint":""},{"n":3,"opts":{"A":"Comply with the COO’s request since the sponsor has the authority to approve change requests.","B":"Submit a change request to formally evaluate the addition through the integrated change control process.","C":"Refuse the addition and remind the COO that the reporting module was explicitly excluded from the approved scope.","D":"Negotiate with the COO to reduce other scope items to accommodate the addition without a formal change request."},"caseTitle":"Case Study 1: Governance Overreach","caseText":"A project manager is leading an 18-month enterprise resource planning (ERP) implementation for a mid-sized manufacturing company. The project sponsor, the company’s Chief Operating Officer (COO), is under pressure from the board of directors to demonstrate measurable operational improvements before the fiscal year closes. The approved project scope includes system configuration, data migration, and user training across three departments.\n\nMidway through execution, the COO requests that the project team integrate a financial reporting module that was explicitly excluded from the approved scope, describing it as a minor addition that does not require formal review. The project manager estimates the addition would require three additional weeks and $40,000 in unbudgeted costs.\n\nThe COO has since begun attending weekly project status meetings and issuing direct task assignments to team members without the project manager’s involvement. When the project manager raised concerns, the COO dismissed them, stating the delivery date is non-negotiable and the team should “do whatever it takes.”\n\nThe project manager has documented the COO’s informal requests in meeting notes but has not yet taken further action. With the fiscal year deadline approaching and the team showing signs of confusion over conflicting direction, the project manager must decide how to proceed.","q":"The COO has requested the addition of a financial reporting module, claiming it does not require formal review. What should the project manager do?","exp":"B. All changes to the approved scope baseline must go through the integrated change control process regardless of their perceived size or the requester’s authority. Submitting a change request ensures the addition is formally evaluated for its impact on scope, schedule, and cost, and routed to the appropriate decision-makers for approval or rejection.\n\nWhy other options are incorrect:\n\nComplying informally bypasses the integrated change control process. The sponsor’s authority to approve changes does not eliminate the requirement to submit a formal change request through the proper process.\n\nRefusing the request misrepresents the project manager’s role. The responsibility is not to block changes but to ensure they are evaluated through the proper process. The decision to approve or reject belongs to the appropriate authority.\n\nInformally negotiating a scope swap still modifies the approved baseline without a formal change request. Any adjustment to the scope baseline, whether adding or removing deliverables, requires formal change control.","ans":"B","hint":""},{"n":4,"opts":{"A":"Escalate the matter to the project steering committee or equivalent governing body responsible for project oversight.","B":"Escalate the concern directly to the board of directors because only the board has sufficient authority to override the COO.","C":"Document the behavior in the issue log and raise it at the next scheduled project status meeting for formal stakeholder discussion.","D":"Report the COO to the functional manager of the affected team members for corrective action."},"caseTitle":"Case Study 1: Governance Overreach","caseText":"A project manager is leading an 18-month enterprise resource planning (ERP) implementation for a mid-sized manufacturing company. The project sponsor, the company’s Chief Operating Officer (COO), is under pressure from the board of directors to demonstrate measurable operational improvements before the fiscal year closes. The approved project scope includes system configuration, data migration, and user training across three departments.\n\nMidway through execution, the COO requests that the project team integrate a financial reporting module that was explicitly excluded from the approved scope, describing it as a minor addition that does not require formal review. The project manager estimates the addition would require three additional weeks and $40,000 in unbudgeted costs.\n\nThe COO has since begun attending weekly project status meetings and issuing direct task assignments to team members without the project manager’s involvement. When the project manager raised concerns, the COO dismissed them, stating the delivery date is non-negotiable and the team should “do whatever it takes.”\n\nThe project manager has documented the COO’s informal requests in meeting notes but has not yet taken further action. With the fiscal year deadline approaching and the team showing signs of confusion over conflicting direction, the project manager must decide how to proceed.","q":"The COO has dismissed the project manager’s concerns and continues to direct team members without the project manager’s involvement. What should the project manager do?","exp":"A. When a sponsor or senior executive undermines the project manager’s authority and bypasses agreed governance, the project manager should escalate the matter to the appropriate project governance body, such as the steering committee, project board, or equivalent oversight authority. This is the correct path for resolving a governance issue involving sponsor interference.\n\nWhy other options are incorrect:\n\nGoing directly to the board bypasses the established governance structure and skips intermediate escalation channels. The board is not typically the first escalation point for a project-level governance issue.\n\nThe situation has already been documented and concerns have already been raised. With unauthorized work underway and the team experiencing confusion, waiting for the next scheduled meeting is too passive and allows the problem to compound.\n\nThe functional manager may manage team assignments, but is not the right authority to address a COO or sponsor who is violating project governance.","ans":"A","hint":""},{"n":5,"opts":{"A":"Scheduled regular status meetings with the COO to maintain ongoing alignment.","B":"Identified sponsor interference as a risk and developed a mitigation strategy during planning.","C":"Established a stakeholder engagement plan that defined the COO’s role and formal decision-making process.","D":"Ensured the COO reviewed and signed off on the change control process."},"caseTitle":"Case Study 1: Governance Overreach","caseText":"A project manager is leading an 18-month enterprise resource planning (ERP) implementation for a mid-sized manufacturing company. The project sponsor, the company’s Chief Operating Officer (COO), is under pressure from the board of directors to demonstrate measurable operational improvements before the fiscal year closes. The approved project scope includes system configuration, data migration, and user training across three departments.\n\nMidway through execution, the COO requests that the project team integrate a financial reporting module that was explicitly excluded from the approved scope, describing it as a minor addition that does not require formal review. The project manager estimates the addition would require three additional weeks and $40,000 in unbudgeted costs.\n\nThe COO has since begun attending weekly project status meetings and issuing direct task assignments to team members without the project manager’s involvement. When the project manager raised concerns, the COO dismissed them, stating the delivery date is non-negotiable and the team should “do whatever it takes.”\n\nThe project manager has documented the COO’s informal requests in meeting notes but has not yet taken further action. With the fiscal year deadline approaching and the team showing signs of confusion over conflicting direction, the project manager must decide how to proceed.","q":"What should the project manager have done at the start of the project to prevent the situation described in the case study?","exp":"C. Proactive stakeholder engagement at the project’s outset would have established clear boundaries around the sponsor’s role, communication expectations, and formal decision-making authority. This reduces the ambiguity that allows sponsor overreach to develop and gives the project manager a documented agreement to reference when boundaries are crossed.\n\nWhy other options are incorrect:\n\nRegular meetings maintain contact but may not establish actual project governance. Without defined roles and decision-making protocols, frequent interaction does not prevent overstepping.\n\nIdentifying sponsor interference as a risk acknowledges the possibility but remains reactive. Proactive engagement prevents the problem rather than preparing to respond to it.\n\nEnsuring sign-off on the change control process addresses one dimension of the relationship but does not establish the broader communication and decision-making framework needed to prevent the situation described.","ans":"C","hint":""},{"n":6,"opts":{"A":"Notify the team of the approval and begin assigning tasks for the reporting module.","B":"Schedule a meeting with the COO to align on implementation priorities for the new module.","C":"Update the project’s scope, schedule, and cost baselines to reflect the approved change.","D":"Submit a revised project charter to document the expanded scope."},"caseTitle":"Case Study 1: Governance Overreach","caseText":"A project manager is leading an 18-month enterprise resource planning (ERP) implementation for a mid-sized manufacturing company. The project sponsor, the company’s Chief Operating Officer (COO), is under pressure from the board of directors to demonstrate measurable operational improvements before the fiscal year closes. The approved project scope includes system configuration, data migration, and user training across three departments.\n\nMidway through execution, the COO requests that the project team integrate a financial reporting module that was explicitly excluded from the approved scope, describing it as a minor addition that does not require formal review. The project manager estimates the addition would require three additional weeks and $40,000 in unbudgeted costs.\n\nThe COO has since begun attending weekly project status meetings and issuing direct task assignments to team members without the project manager’s involvement. When the project manager raised concerns, the COO dismissed them, stating the delivery date is non-negotiable and the team should “do whatever it takes.”\n\nThe project manager has documented the COO’s informal requests in meeting notes but has not yet taken further action. With the fiscal year deadline approaching and the team showing signs of confusion over conflicting direction, the project manager must decide how to proceed.","q":"The change request for the financial reporting module has been approved. What should the project manager do next?","exp":"C. An approved change request must be reflected in the project’s baselines before work proceeds. Updating the scope, schedule, and cost baselines ensures the project is measured against the correct targets going forward and that the approved change is formally incorporated into the project management plan.\n\nWhy other options are incorrect:\n\nAssigning tasks before updating the baselines skips the formal step that makes the change official. Work should not begin until the baselines reflect the approved change.\n\nA meeting with the COO is unnecessary at this stage. The change has already been approved through the proper process and does not require further alignment.\n\nThe project charter is established at project initiation and is not updated to reflect scope changes. Scope changes are captured in the scope baseline, not the charter.","ans":"C","hint":""},{"n":7,"opts":{"A":"Predictive","B":"Incremental","C":"Hybrid","D":"Agile"},"caseTitle":"Case Study 2: Agile Adoption","caseText":"","q":"Based on the details provided, which development approach is the project using?","exp":"D. The scenario describes evolving requirements, a Product Owner managing a product backlog, and a team operating in two-week sprints. These characteristics are consistent with an agile approach.\n\nWhy other options are incorrect:\n\nA predictive approach defines scope, schedule, and cost upfront and manages against fixed baselines. The above characteristics do not match the predictive approach described in the scenario.\n\nIncremental delivery describes how outputs are released in stages, not a development approach in itself. No evidence of phased releases appears in the scenario.\n\nA hybrid approach is a deliberate combination of predictive and agile elements designed to meet a project’s specific needs. The scenario describes an organization piloting new delivery practices with an agile project structure - a Product Owner, a managed backlog, and two-week sprints. The PM’s task assignments are inconsistent with that structure, suggesting old habits rather than intentional hybrid design.","ans":"D","hint":""},{"n":8,"opts":{"A":"Directing team members and assigning tasks to ensure sprint goals are met.","B":"Managing the product backlog and making prioritization decisions as needed.","C":"Facilitating the team’s work by removing impediments and supporting self-organization.","D":"Reporting sprint progress to the sponsor and adjusting the delivery schedule accordingly."},"caseTitle":"Case Study 2: Agile Adoption","caseText":"","q":"Based on the project approach, what should be the project manager’s primary role?","exp":"C. In an agile project structured around a Product Owner, a managed backlog, and iterative sprints, the project manager’s role is to serve the team rather than direct it. This means removing obstacles, protecting the team from disruptions, and supporting their ability to self-organize rather than assigning work or making backlog decisions.\n\nWhy other options are incorrect:\n\nDirecting team members and assigning tasks contradicts the nature of agile, where teams self-organize and pull work from the backlog.\n\nManaging the backlog and making prioritization decisions belongs to the Product Owner in an agile environment.\n\nReporting to the sponsor and adjusting the schedule applies predictive thinking to an agile structure built around iterative planning and sprint-based delivery.","ans":"C","hint":""},{"n":9,"opts":{"A":"The team became dependent on the project manager for direction rather than developing self-organization skills.","B":"The Product Owner’s ability to manage the backlog effectively was undermined by the project manager’s involvement in sprint planning.","C":"The team’s failure to meet a delivery deadline was a direct result of the uneven task distribution across sprints.","D":"The pilot program lost credibility with senior leadership due to the team’s continued struggle with sprint planning."},"caseTitle":"Case Study 2: Agile Adoption","caseText":"","q":"The project manager responded to the team’s struggle to self-organize during sprint planning by assigning specific tasks to team members at the start of each sprint. What was the consequence of this approach?","exp":"A. By assigning tasks directly, the project manager replaced self-organization with a directive approach. Rather than developing the ability to coordinate independently, the team adapted to waiting for assignments, which the scenario confirms. This undermines one of agile’s core principles and prevents the team from building the capability the pilot program was designed to develop.\n\nWhy other options are incorrect:\n\nThe Product Owner is responsible for the backlog, not sprint task assignments. The project manager’s task assignments operate at the sprint level and do not directly affect the Product Owner’s backlog authority.\n\nThe scenario describes a delivery deadline but does not confirm it was missed or that uneven task distribution was a contributing factor.\n\nSenior leadership’s reaction to the pilot program is not described in the scenario. The team’s struggle with self-organization is an internal adoption challenge, not a reported credibility issue.","ans":"A","hint":""},{"n":10,"opts":{"A":"Yes, because the project manager is responsible for ensuring the project meets its delivery deadline.","B":"No, because backlog reprioritization requires approval from senior leadership before implementation.","C":"No, because the product backlog is the Product Owner’s responsibility and reprioritization decisions belong exclusively to them.","D":"No, because reducing scope mid-project violates the agile principle of responding to change over following a plan."},"caseTitle":"Case Study 2: Agile Adoption","caseText":"","q":"The project manager reprioritized several backlog items to reduce near-term scope and meet a delivery deadline. Was this action appropriate?","exp":"C. The product backlog is owned and managed exclusively by the Product Owner. Regardless of the motivation, reprioritizing backlog items is a Product Owner decision. The project manager bypassed the appropriate authority by making a unilateral scope decision.\n\nWhy other options are incorrect:\n\nThe project manager is responsible for delivery but not through actions that bypass established role boundaries. Delivery pressure does not override the Product Owner’s authority over the backlog.\n\nSenior leadership approval is not the correct channel for backlog decisions. That authority belongs to the Product Owner, not the organizational hierarchy.\n\nAgile embraces responding to change, including scope adjustments. The issue is not that scope was reduced but that the decision was made by the wrong person.","ans":"C","hint":""},{"n":11,"opts":{"A":"Requested the Product Owner to take a more active role in sprint planning until the team gained confidence.","B":"Escalated the team’s struggles to senior leadership given the importance of the pilot program’s success.","C":"Coached the team on agile sprint planning practices to build their self-organization capability over time.","D":"Reduced the number of backlog items assigned to each sprint to give the team a more manageable workload."},"caseTitle":"Case Study 2: Agile Adoption","caseText":"","q":"The project manager assigned tasks to team members when the team struggled to self-organize during sprint planning. What should the project manager have done instead?","exp":"C. In agile, the project manager’s role is to build the team’s capability, not resolve their struggles by taking over. Coaching the team on sprint planning practices addresses the root cause by developing self-organization skills rather than replacing them with a directive approach.\n\nWhy other options are incorrect:\n\nThe Product Owner’s role is to manage the backlog, not facilitate sprint planning or direct the team’s work. Shifting that responsibility to the PO misrepresents their role.\n\nEscalating to senior leadership is premature. A team new to agile struggling with self-organization is an adoption challenge the project manager can address directly.\n\nReducing backlog items addresses workload but not the team’s inability to self-organize. It treats the symptom rather than building the capability the pilot program requires.","ans":"C","hint":""},{"n":12,"opts":{"A":"Work with the Product Owner to share the full product backlog with the team to provide visibility into upcoming work.","B":"Reintroduce a high-level delivery plan to give the team greater confidence in the project’s direction.","C":"Escalate the concern to senior leadership since the team’s discomfort threatens the pilot program’s success.","D":"Coach the team on how the product backlog and iterative planning provide visibility into future work."},"caseTitle":"Case Study 2: Agile Adoption","caseText":"","q":"Several team members have expressed discomfort with the lack of visibility into work beyond the current sprint. What should the project manager do?","exp":"D. The team’s discomfort stems from unfamiliarity with agile planning, not a genuine gap in visibility. The product backlog already contains the team’s upcoming work. The project manager’s role is to help the team understand how agile planning tools replace traditional long-term plans rather than reintroducing predictive artifacts.\n\nWhy other options are incorrect:\n\nSharing the backlog addresses visibility but not the team’s misunderstanding of how agile planning works. Without coaching, the team may still not understand how the backlog replaces a traditional plan.\n\nReintroducing a delivery plan reverts to predictive thinking and undermines the agile approach the pilot program is designed to establish.\n\nEscalating to senior leadership is premature. The team’s discomfort is an adoption challenge the project manager can and should address directly through coaching and facilitation.","ans":"D","hint":""},{"n":13,"opts":{"A":"The issue log","B":"The risk register","C":"The risk management plan","D":"The assumption log"},"caseTitle":"Case Study 3: Office Building Construction","caseText":"","q":"What document should the project manager use to record and track the identified risks on this project?","exp":"B. The risk register is the document used to record identified risks, their probability and impact assessments, and the planned risk responses. It serves as the central tracking tool for all risk-related information throughout the project lifecycle.\n\nWhy other options are incorrect:\n\nThe issue log captures active problems that are currently affecting the project, not potential future risks. Risk becomes an issue only when it occurs.\n\nThe risk management plan defines how risk management activities will be conducted on the project. It establishes the approach, roles, and processes but does not record individual risks.\n\nThe assumption log captures assumptions and constraints identified during planning. While some assumptions may carry risk implications, it is not the appropriate document for recording and tracking risks.","ans":"B","hint":""},{"n":14,"opts":{"A":"Quantitative risk analysis","B":"Probability and impact matrix","C":"Monte Carlo simulation","D":"Risk urgency assessment","E":"Sensitivity analysis"},"caseTitle":"Case Study 3: Office Building Construction","caseText":"","q":"Which three options best describe the risk analysis techniques the project manager performed during planning? (Choose 3)","exp":"A, C, E. The scenario describes two specific quantitative techniques. Running thousands of iterative calculations using probability distributions to forecast a range of possible outcomes describes Monte Carlo simulation. Examining which risk variables had the greatest potential effect by varying each factor independently describes sensitivity analysis. Both are quantitative risk analysis techniques, making all three correct answers consistent with what the scenario describes.\n\nWhy other options are incorrect:\n\nThe probability and impact matrix is a qualitative risk analysis tool used to prioritize risks based on estimated probability and impact. The scenario does not describe this technique.\n\nRisk urgency assessment is a qualitative technique used to identify risks requiring near-term responses. The scenario does not describe this technique.","ans":["A","C","E"],"multi":true,"pick":3,"hint":""},{"n":15,"opts":{"A":"The project manager’s follow-up risk analysis failed to accurately capture the severity of the soil degradation.","B":"The project manager did not escalate the safety risk when it exceeded their ability to manage it independently.","C":"Several team members did not attend the scheduled safety meetings that were part of the risk response plan.","D":"A scheduling conflict resulted in excessive personnel and equipment operating in the same area at the time of the incident."},"caseTitle":"Case Study 3: Office Building Construction","caseText":"","q":"A worker has been injured on the construction site, prompting a regulatory investigation and potential litigation. What was the most likely root cause of the project manager’s failure to prevent this outcome?","exp":"B. The scenario establishes that the project manager identified the risk, documented it, developed a response plan, and even enhanced monitoring after receiving updated assessment data. However when the site supervisor flagged a potential safety concern, the project manager responded with visual inspections rather than engaging someone with the expertise to interpret the geotechnical data correctly. The risk exceeded the project manager’s ability to manage it independently and was not escalated to the appropriate authority.\n\nWhy other options are incorrect:\n\nThe project manager did perform follow-up analysis through the updated geotechnical assessment. The failure was not in capturing the data but in recognizing its significance and responding appropriately.\n\nInconsistent safety meeting attendance is a detail present in the scenario but not causally connected to the injury. The sinkhole resulted from unaddressed soil degradation, not from missed safety briefings.\n\nThe scheduling conflict contributed to the concentration of crews and equipment in the affected area but was not the root cause. The soil degradation would have posed a risk to ongoing construction regardless of crew scheduling.","ans":"B","hint":""},{"n":16,"opts":{"A":"A known known, because the project manager had already documented the soil degradation in the risk register.","B":"A known unknown, because the full extent of the soil degradation had not yet been determined at the time of the assessment.","C":"An unknown unknown, because soil degradation of this nature could not have been anticipated during risk planning.","D":"An unknown known, because the safety significance of the findings was knowable but the project manager lacked the expertise to recognize it without consulting a subject matter expert."},"caseTitle":"Case Study 3: Office Building Construction","caseText":"","q":"How should the soil degradation findings have been classified in terms of their significance to worker safety?","exp":"D. The soil degradation data was in the project manager’s hands, but its significance as a serious safety risk was not something the project manager could interpret without specialized expertise. A geotechnical expert would have recognized the danger immediately. That knowledge existed and was accessible, making this an unknown known - the project manager didn’t know what they didn’t know, but the information was available had they consulted the right expert.\n\nWhy other options are incorrect:\n\nA known known requires both awareness and understanding of the information. The project manager had the data but not the expertise to interpret its safety significance correctly.\n\nA known unknown implies the information is not yet available. The safety significance of the soil findings was accessible through expert consultation, making this classification incorrect.\n\nAn unknown unknown refers to risks that could not have been anticipated at all. Soil degradation on a construction site is a foreseeable category of risk, and the significance of the findings was determinable through available expertise.","ans":"D","hint":""},{"n":17,"opts":{"A":"Scheduled an additional safety meeting to brief the construction crew on the updated findings.","B":"Consulted a subject matter expert to interpret the soil assessment findings and determine the appropriate course of action.","C":"Assigned a team member to monitor site safety conditions and report any changes in soil stability.","D":"Updated the risk register with the new findings and continued monitoring the situation."},"caseTitle":"Case Study 3: Office Building Construction","caseText":"","q":"What could the project manager have done to prevent the worker injury described in the case study?","exp":"B. When technical assessment data falls outside the project manager’s area of expertise, the correct response is to engage a subject matter expert who can interpret the findings accurately. The soil assessment results carried safety implications that required specialized geotechnical knowledge to evaluate. Consulting an expert would have revealed the severity of the risk and informed whether escalation was warranted, potentially preventing the injury that followed.\n\nWhy other options are incorrect:\n\nScheduling a safety meeting addresses crew awareness but not the underlying question of what the soil findings actually mean for site safety. Awareness of a risk is not the same as understanding its severity.\n\nAssigning a team member to monitor soil stability delegates observation to someone without the expertise to interpret what they are observing. Monitoring is not a substitute for expert analysis of technical assessment data.\n\nUpdating the risk register documents the new information but takes no action on it. When assessment results suggest elevated risk, documentation alone is insufficient. The PM’s obligation is to understand what the data means and respond accordingly.","ans":"B","hint":""},{"n":18,"opts":{"A":"A comprehensive risk register capturing all potential safety risks associated with the construction project.","B":"A risk threshold framework defining the conditions under which risks must be escalated beyond the project manager’s authority.","C":"A detailed safety management plan outlining inspection procedures and compliance requirements.","D":"A stakeholder communication plan ensuring all parties were informed of safety risks throughout the project."},"caseTitle":"Case Study 3: Office Building Construction","caseText":"","q":"What should the project manager have established at the outset of the project to prevent the situation described in the case study?","exp":"B. Establishing a risk threshold framework at the outset would have defined in advance the conditions under which a risk requires escalation beyond the project manager’s authority. With clear thresholds in place, the project manager would have had a predefined trigger for recognizing that the updated soil assessment warranted escalation to someone with the expertise and authority to act on it decisively.\n\nWhy other options are incorrect:\n\nA comprehensive risk register captures identified risks but does not define the conditions that require escalation. The project manager already maintained a risk register throughout the project.\n\nA safety management plan outlines inspection procedures and compliance requirements but does not address the judgment call of when a risk exceeds the project manager’s capacity to manage it independently.\n\nA stakeholder communication plan ensures stakeholders are informed but does not establish the decision framework needed to recognize and act on an escalation threshold.","ans":"B","hint":""},{"n":19,"opts":{"A":"Defer the new items to the next sprint to preserve the team’s preparation work.","B":"Present the new items during sprint planning and allow the team to select the work they commit to completing.","C":"Remove the lowest-priority items from the backlog to accommodate the new high-priority additions.","D":"Escalate the conflict to the scrum master to determine which items should be included in the sprint."},"q":"A software development team using Scrum is preparing for sprint planning. The product owner has added several new high-priority items to the backlog just before sprint planning, replacing items the team had already refined and estimated as likely candidates for the sprint. The development team is concerned the last-minute changes will disrupt the sprint.\nWhat should the product owner do?","exp":"B. Present the new items during sprint planning and allow the team to select the work they commit to completing.\n\nExplanation: The product owner maintains and prioritizes the product backlog and may introduce new items at any time, including before sprint planning. The development team determines how much work they commit to in the sprint. Sprint planning is the appropriate forum for both responsibilities to be exercised collaboratively.\n\nWhy the other options are incorrect:\n\nDeferring the new items automatically would ignore the product owner’s responsibility to reorder the backlog based on current priorities before sprint planning.\n\nRemoving lower-priority items from the backlog is unnecessary. In Scrum, the product owner can reprioritize the backlog so the new items are considered first, while lower-priority items remain on the backlog for future consideration.\n\nEscalating to the scrum master misidentifies that role. Sprint commitment decisions belong to the product owner and development team, not the scrum master.","ans":"B","hint":""},{"n":20,"opts":{"A":"Prioritize engagement with stakeholders who hold direct decision-making authority, since their approval is required for project success.","B":"Categorize stakeholders by their level of power and interest, and tailor engagement strategies to each group’s position.","C":"Implement a consistent communication strategy across all stakeholder groups to ensure equitable access to project information.","D":"Concentrate engagement efforts on stakeholders with high operational impact, since their day-to-day involvement most directly determines delivery success."},"q":"A project manager has been assigned to lead a large infrastructure project with over 30 identified stakeholders. The stakeholder group includes senior leaders, operational teams, and community representatives with differing levels of influence, interest, and project impact. The project manager needs to develop an engagement strategy.\nWhat should the project manager do?","exp":"B. Categorize stakeholders by their level of power and interest, and tailor engagement strategies to each group’s position.\n\nExplanation: The project manager should analyze stakeholders using a stakeholder mapping tool such as a power/interest grid and tailor engagement strategies accordingly. In a large project with diverse stakeholders, not all stakeholders require the same level or type of engagement. This approach helps the project manager focus effort where it is most needed while maintaining appropriate communication and support across the stakeholder group.\n\nWhy the other options are incorrect:\n\nPrioritizing decision-making authority alone ignores highly engaged, low-authority stakeholders who can still mobilize opposition or surface issues that affect delivery.\n\nA consistent strategy conflates equal treatment with appropriate treatment. Stakeholders have different information needs and influence levels that a uniform approach fails to address.\n\nOperational impact is one valid dimension but overlooks stakeholders with latent political influence who become critical when issues escalate.","ans":"B","hint":""},{"n":21,"opts":{"A":"Authorize the team member to implement the feature since the project manager has already approved it.","B":"Evaluate the feature’s impact and implement it if it falls within the existing contingency budget.","C":"Submit a formal change request and route it through the change control process before any work begins.","D":"Document the feature as a future enhancement and address it in the next project phase."},"q":"During the execution of a large IT infrastructure project, a department head requests that the project team add a new feature to the deliverable. The project manager agrees the feature would add value. A team member suggests implementing it immediately since it is relatively small and the project manager supports it.\nWhat should the project manager do?","exp":"C. Submit a formal change request and route it through the change control process before any work begins.\n\nExplanation: Any change to baselined project scope, regardless of size, must go through integrated change control. The project manager’s personal support for the change does not bypass the requirement for formal evaluation and approval. A change request ensures impacts on schedule, cost, and other elements are assessed before work begins.\n\nWhy the other options are incorrect:\n\nThe project manager’s informal approval does not substitute for formal change control and opens the door to scope creep.\n\nUsing contingency budget to absorb an unapproved scope addition misuses reserves that are intended for identified risks, not new features.\n\nDocumenting as a future enhancement may be appropriate if the request is deferred, but that decision should follow formal processing, not precede it.","ans":"C","hint":""},{"n":22,"opts":{"A":"Inform the team member that the risk identification phase has been completed and the risk register is closed.","B":"Add the risk to the risk register and conduct a collaborative risk assessment with the team and relevant stakeholders.","C":"Escalate the regulatory concern to the project sponsor and request guidance before taking any action.","D":"Update the project schedule to account for the potential regulatory delay before evaluating the risk further."},"q":"A project manager for a pharmaceutical company completed the initial risk identification process and created a risk register three months ago. During execution, a team member raises a concern about a new regulatory requirement that could affect the project timeline. The project manager notes this risk was not captured during initial planning.\nWhat should the project manager do?","exp":"B. Add the risk to the risk register and conduct a collaborative risk assessment with the team and relevant stakeholders.\n\nExplanation: Risk management is continuous throughout the project lifecycle. Newly identified risks must be logged and assessed with the team and relevant stakeholders to determine probability, impact, and appropriate response before any action is taken.\n\nWhy the other options are incorrect:\n\nTreating the risk register as closed after initial planning contradicts the ongoing nature of risk management. New risks can emerge at any phase.\n\nEscalating before evaluating skips the project manager’s responsibility to analyze the issue. The sponsor should be engaged after an initial assessment, not before.\n\nUpdating the schedule before assessing the risk assumes impact without proper analysis. Response planning must follow assessment.","ans":"B","hint":""},{"n":23,"opts":{"A":"Ask the team to revise the deliverable to match the client’s expectations and submit a change request afterward.","B":"Escalate the disagreement to the project sponsor to resolve the conflict with the client.","C":"Review the documented acceptance criteria with the client to determine whether the deliverable meets the agreed-upon standards.","D":"Document the client’s concerns and proceed with deliverable sign-off because the work matches the approved scope baseline."},"q":"A construction project team has completed a major deliverable according to approved project plans and specifications. During formal review, the client raises concerns that certain elements do not meet their expectations.\nWhat should the project manager do first?","exp":"C. Review the documented acceptance criteria with the client to determine whether the deliverable meets the agreed-upon standards.\n\nExplanation: When a deliverable dispute arises, the project manager should refer to the formally documented acceptance criteria. Scope validation involves reviewing completed work against those criteria with the client, providing objective resolution grounded in formal agreements rather than subjective expectations.\n\nWhy the other options are incorrect:\n\nRevising the deliverable before reviewing acceptance criteria assumes the client is correct without verification and risks unnecessary rework.\n\nEscalating to the sponsor before referencing the documentation is premature and bypasses the established resolution mechanism.\n\nProceeding with sign-off based only on internal project validation bypasses formal customer acceptance and ignores the client’s concerns.","ans":"C","hint":""},{"n":24,"opts":{"A":"CPI = 0.83; the project is over budget, receiving less value than the amount being spent.","B":"CPI = 1.20; the project is under budget, completing more work than planned for the cost incurred.","C":"CPI = 0.80; the project is over budget, as earned value falls short of planned value.","D":"CPI = 1.04; the project is under budget, with costs running slightly below planned value."},"q":"A project manager receives the following status update: Budget at Completion (BAC) = $500,000; Planned Value (PV) = $250,000; Earned Value (EV) = $200,000; Actual Cost (AC) = $240,000.\nWhat is the Cost Performance Index (CPI) and what does it indicate?","exp":"A. CPI = 0.83; the project is over budget, receiving less value than the amount being spent.\n\nExplanation: CPI = EV / AC = $200,000 / $240,000 = 0.83. A CPI below 1.0 indicates over-budget performance. For every $1.00 spent, only $0.83 of value is being produced.\n\nWhy the other options are incorrect:\n\n1. 20 results from inverting the formula (AC / EV instead of EV / AC), the most common EVM calculation error.\n\n0. 80 results from dividing EV by PV ($200,000 / $250,000), which is the SPI formula, not CPI.\n\n1. 04 results from dividing PV by AC, which does not measure cost efficiency. CPI compares earned value to actual cost, not planned work to actual spending.","ans":"A","hint":""},{"n":25,"opts":{"A":"Make a final decision on the architecture to end the impasse and allow the team to move forward.","B":"Bring both engineers together in a problem-solving session to work toward an acceptable solution.","C":"Separate the two engineers’ responsibilities to minimize their interaction for the remainder of the project.","D":"Allow the conflict to resolve naturally, as technical disagreements typically self-correct once work resumes."},"q":"Two senior engineers on a hybrid project have reached an impasse over the technical architecture for a critical system component. The disagreement has begun affecting sprint velocity and team morale. The project manager has attempted informal discussion but both engineers remain entrenched in their positions.\nWhat should the project manager do?","exp":"B. Bring both engineers together in a problem-solving session to work toward an acceptable solution.\n\nExplanation: The confronting/problem-solving approach is the most effective conflict resolution method for achieving durable outcomes. A structured session allows both perspectives to be heard, root causes to be explored, and a mutually acceptable solution to emerge, preserving the working relationship and leveraging the expertise of both parties.\n\nWhy the other options are incorrect:\n\nA unilateral project manager decision bypasses the engineers’ technical expertise and risks low commitment to a solution neither party helped create.\n\nSeparating the engineers avoids rather than resolves the conflict, leaving the underlying issue intact and potentially creating coordination problems later.\n\nWaiting for natural resolution ignores the project manager’s responsibility to intervene when conflict is measurably affecting sprint velocity and morale.","ans":"B","hint":""},{"n":26,"opts":{"A":"Adaptive, because the project involves complex technology and could benefit from iterative development.","B":"Hybrid, because the regulatory environment justifies structured governance while development could proceed iteratively.","C":"Predictive, because the requirements are fixed, documentation is required, and the team is experienced with structured delivery.","D":"Adaptive, because frequent stakeholder feedback will help ensure the platform meets regulatory expectations."},"q":"A project manager is assigned to develop a new regulatory compliance platform for a financial institution. Senior leadership requires detailed documentation and formal sign-offs at each phase. The compliance requirements are fully defined by regulation and are not expected to change.\nWhat development approach should the project manager recommend?","exp":"C. Predictive, because the requirements are fixed, documentation is required, and the team is experienced with structured delivery.\n\nExplanation: Approach selection should be based on project characteristics. Fixed, legally mandated requirements, mandatory phase documentation, and a team experienced with structured delivery all point to a predictive approach. Introducing adaptive elements where requirements are fixed adds overhead without adding value.\n\nWhy the other options are incorrect:\n\nTechnical complexity does not justify adaptive when requirements are fully defined and legally non-negotiable; iterative development adds value only when requirements are expected to evolve.\n\nA hybrid approach introduces adaptive components without a clear benefit given stable requirements and mandatory documentation at each phase.\n\nStakeholder feedback loops do not change legally mandated compliance obligations that are already fully defined.","ans":"C","hint":""},{"n":27,"opts":{"A":"Increase the frequency of final testing cycles to catch more defects before release.","B":"Implement quality assurance activities earlier in the development process to prevent defects from occurring.","C":"Assign a dedicated quality control specialist to review all code before it proceeds to testing.","D":"Accept the current defect rate as a normal part of software development and track it as a project metric."},"q":"A project manager for a software company notices the team consistently finds defects during final testing but rarely catches them earlier. A quality audit reveals robust testing procedures but no defined review checkpoints during design or coding phases.\nWhat should the project manager do?","exp":"B. Implement quality assurance activities earlier in the development process to prevent defects from occurring.\n\nExplanation: Quality assurance focuses on auditing processes to prevent defects, while quality control focuses on inspecting outputs to detect them. The audit identifies a QA gap: no process checkpoints during design or coding. Shifting to prevention is more cost-effective than continued reliance on detection.\n\nWhy the other options are incorrect:\n\nIncreasing final testing is a detection-focused quality control activity that does not address the root cause identified in the audit.\n\nAssigning a code reviewer adds an inspection step, but it does not by itself establish the broader quality assurance processes and defined review checkpoints the audit found missing. It’s a step in the right direction, but insufficient on its own.\n\nAccepting the defect rate normalizes a correctable process gap rather than acting on clear audit findings.","ans":"B","hint":""},{"n":28,"opts":{"A":"Convene a meeting with the affected departments to establish shared understanding and align on how the change should be implemented.","B":"Send a revised status report with clarifying language to the full stakeholder group emphasizing the correct interpretation.","C":"Update the project portal with the revised scope documentation and notify stakeholders by email that the updated version is available.","D":"Escalate the conflicting interpretations to the project sponsor and request that they communicate the correct approach to the departments."},"q":"A project manager has been distributing weekly status reports by email to a 30-person stakeholder group. Midway through the project, a significant scope change is approved that generates conflicting interpretations across departments. Two departments have already begun acting on the change in contradictory ways, creating rework. The project manager needs to address the misalignment quickly.\nWhat should the project manager do?","exp":"A. Convene a meeting with the affected departments to establish shared understanding and align on how the change should be implemented.\n\nExplanation: When stakeholders have already diverged in their interpretation and are acting in contradictory ways, push or pull communication cannot resolve the misalignment because they are one-directional. Interactive communication creates the conditions for real-time two-way exchange needed to establish shared understanding and prevent further rework.\n\nWhy the other options are incorrect:\n\nA revised status report repeats the same one-directional mechanism that produced the misalignment in the first place. Without two-way exchange, stakeholders can still walk away with different interpretations.\n\nUpdating the portal and notifying stakeholders is passive. It does not create conditions for alignment when departments have already diverged and are actively generating rework.\n\nEscalation is unnecessary at this point because the PM still has a direct, appropriate way to resolve the misunderstanding among the affected stakeholders. Sponsor involvement may be warranted later if alignment cannot be achieved or if authority is needed.","ans":"A","hint":""},{"n":29,"opts":{"A":"Fast-track selected critical path activities by overlapping successor work wherever possible to recover time.","B":"Crash the longest-duration activities on the schedule first to recover the maximum amount of time overall.","C":"Crash the critical path activities where additional equipment and crews can be mobilized.","D":"Re-baseline the project schedule to reflect the current projected completion date."},"q":"A project manager is six weeks behind schedule on a construction project with a fixed completion deadline the sponsor has confirmed cannot be moved. A schedule review shows that additional equipment and crews can be mobilized for certain critical path activities to reduce their duration. However, several other critical path activities involve specialized inspections and technical handoffs that must be fully completed before successor work can begin.\nWhat schedule compression technique should the project manager apply first?","exp":"C. Crash the critical path activities where additional equipment and crews can be mobilized.\n\nExplanation: Because the deadline is fixed, the project manager must apply the compression technique that is both feasible and effective on the critical path. The schedule review shows that additional resources can shorten specific critical path activities, while technical handoffs rule out overlapping others.\n\nWhy the other options are incorrect:\n\nFast-tracking requires activities to be safely overlapped. Where critical path work involves specialized inspections and technical handoffs that must be fully completed before successor work begins, overlapping is not feasible without introducing rework risk or quality failures.\n\nCrashing the longest-duration activities regardless of their path ignores critical path logic. Duration reduction on non-critical activities does not move the project end date, making this an inefficient use of additional resources and cost.\n\nRe-baselining accepts the delay without exhausting available recovery options and should only be considered after compression strategies have been evaluated and exhausted.","ans":"C","hint":""},{"n":30,"opts":{"A":"Continue the current approach to establish authority and ensure consistent oversight of the team.","B":"Delegate the project manager role to the scrum master since self-organizing teams do not require project manager involvement.","C":"Schedule a team workshop to redefine roles and responsibilities to incorporate the project manager’s oversight functions.","D":"Shift to a servant leadership approach that removes obstacles, supports team autonomy, and avoids micromanagement."},"q":"A newly hired project manager is taking over a mature Scrum team that has been self-organizing successfully for two years. During the first sprint, the project manager begins assigning tasks to individual team members, approving all team decisions before implementation, and conducting one-on-one check-ins to monitor individual progress.\nWhat should the project manager do instead?","exp":"D. Shift to a servant leadership approach that removes obstacles, supports team autonomy, and avoids micromanagement.\n\nExplanation: Because the team is already mature and self-organizing, the project manager should adapt to that operating model rather than impose directive control. The appropriate shift is to servant leadership: support the team, remove obstacles, and enable delivery without assigning tasks, approving routine team decisions, or monitoring individuals in a micromanaging way.\n\nWhy the other options are incorrect:\n\nContinuing the directive approach damages morale and reduces velocity on a team that has already demonstrated its self-organizing capability.\n\nStepping back completely avoids micromanagement, but it is not the best response. The project manager should remain engaged in a supportive role.\n\nFormalizing approval gatekeeping into the team’s operating model institutionalizes the exact behavior that undermines agile performance.","ans":"D","hint":""},{"n":31,"opts":{"A":"Transfer the risk by arranging insurance coverage for storm-related equipment and material damage.","B":"Mitigate the risk by implementing storm-preparation procedures, protective storage, and site hardening measures to reduce potential damage.","C":"Avoid the risk by rescheduling construction activities outside the hurricane season window.","D":"Accept the risk and establish a weather monitoring protocol for the construction period."},"q":"A construction project is underway at a fixed coastal site during hurricane season. The work depends on installed heavy equipment and staged materials that cannot be relocated without major disruption. A major storm could cause up to $2 million in damage. The sponsor is primarily concerned about the financial exposure from potential storm damage.\nWhat risk response strategy is most appropriate?","exp":"A. Transfer the risk by arranging insurance coverage for storm-related equipment and material damage.\n\nExplanation: The project is already underway at a fixed site with immovable equipment, which limits both avoidance and the effectiveness of physical mitigation. Even with preparation measures in place, significant financial exposure remains. Transfer directly addresses the $2 million consequence by shifting financial liability to a third party, making it the most appropriate primary response given the constraints.\n\nWhy the other options are incorrect:\n\nMitigation through site hardening and storm preparation is a sound supplementary measure but does not eliminate the financial exposure on a fixed site with equipment that cannot be relocated. It reduces impact at the margins rather than addressing the scale of the risk.\n\nRescheduling would avoid the hurricane season exposure, but the project is already underway at a fixed location, making this option operationally unavailable.\n\nAccepting a $2 million exposure and monitoring weather is passive at a scale that clearly warrants an active financial response.","ans":"A","hint":""},{"n":32,"opts":{"A":"Ask the team to simplify stories where possible to reduce estimates and fit more items into each sprint.","B":"Accept the higher commitment since delivery deadlines represent a business priority the team must accommodate.","C":"Reduce story point estimates across the backlog so the 55-point target appears achievable within current capacity.","D":"Explain that velocity reflects historical capacity and that inflating sprint commitments typically degrades quality and increases technical debt rather than accelerating delivery."},"q":"A Scrum team has been averaging 40 story points per sprint over the last four sprints. The project manager informs the scrum master that the delivery deadline requires the team to commit to 55 story points per sprint going forward.\nWhat should the scrum master do?","exp":"D. Explain that velocity reflects historical capacity and that inflating sprint commitments typically degrades quality and increases technical debt rather than accelerating delivery.\n\nExplanation: Velocity is a planning tool derived from what the team has actually delivered, not a performance lever that can be adjusted to meet external targets. Committing to more than demonstrated capacity does not increase throughput; it produces incomplete work, quality shortcuts, and unreliable forecasts.\n\nWhy the other options are incorrect:\n\nSimplifying stories to compress estimates produces artificially inflated velocity numbers without delivering more value. It manipulates the planning data rather than addressing actual capacity.\n\nAccepting the higher commitment treats sprint capacity as flexible when it is grounded in demonstrated performance. Business deadlines create pressure but do not change what the team can realistically deliver in a timebox.\n\nReducing backlog estimates to match an arbitrary target corrupts the velocity baseline and produces unreliable sprint planning data for every future sprint.","ans":"D","hint":""},{"n":33,"opts":{"A":"Contingency reserves are controlled by the project manager and used for identified risks; management reserves are controlled by the sponsor and require formal approval to access.","B":"The project manager controls all reserves and can access either type when actual costs exceed the cost baseline.","C":"Both reserve types are controlled by the sponsor and require a formal change request to be used.","D":"Management reserves are part of the cost baseline while contingency reserves sit outside it and require sponsor approval to use."},"q":"A project manager is presenting the project budget to the sponsor. The budget includes $80,000 in contingency reserves, and $40,000 in management reserves. The sponsor asks who controls each reserve and under what conditions they can be accessed.\nWhat should the project manager explain?","exp":"A. Contingency reserves are controlled by the project manager and used for identified risks; management reserves are controlled by the sponsor and require formal approval to access.\n\nExplanation: Contingency reserves address identified risks, are included in the cost baseline, and are available to the project manager when those risks materialize. Management reserves sit above the cost baseline for unknown unknowns and require a formal change request and sponsor approval, since accessing them represents a change to the authorized budget.\n\nWhy the other options are incorrect:\n\nGiving the project manager control over both types removes the governance distinction between planned risk responses and unforeseen circumstances requiring senior authorization.\n\nRequiring sponsor approval for contingency access would slow responses to risks already anticipated and planned for, defeating the purpose of contingency reserves.\n\nManagement reserves are not part of the cost baseline; contingency reserves are.","ans":"A","hint":""},{"n":34,"opts":{"A":"Develop tailored engagement strategies for each group based on their specific positions, interests, and influence on the project.","B":"Prioritize engagement with the city planning committee to secure their preliminary support before addressing community opposition.","C":"Schedule initial meetings with the neighborhood association to understand the source of their opposition before developing a broader engagement approach.","D":"Organize a joint stakeholder session where all three groups can hear the project proposal and raise concerns together."},"q":"A large urban development project has three distinct stakeholder groups: a neighborhood association actively organizing against the project, a business council that supports it but wants construction minimized during peak business hours, and a city planning committee that holds formal approval authority but has not yet taken a position. The project manager must develop an engagement approach.\nWhat should the project manager do?","exp":"A. Develop tailored engagement strategies for each group based on their specific positions, interests, and influence on the project.\n\nExplanation: Each stakeholder group has a distinct position, level of influence, and set of interests that require a different engagement strategy. A good stakeholder engagement plan addresses all groups systematically rather than reactively or sequentially.\n\nWhy the other options are incorrect:\n\nSecuring the planning committee’s support first before addressing community opposition ignores the influence organized opposition can have on that committee’s eventual decision. Stakeholder engagement should be holistic rather than sequenced by approval hierarchy.\n\nMeeting with the neighborhood association before developing a plan puts tactics ahead of strategy. Without first analyzing all stakeholder positions together, the project manager lacks the context to conduct those meetings effectively.\n\nA joint session with groups holding opposing positions risks public confrontation between the neighborhood association and business council rather than productive dialogue. Stakeholders with conflicting interests typically require separate engagement before any shared forum.","ans":"A","hint":""},{"n":35,"opts":{"A":"Add the feature to the current sprint backlog immediately","B":"Reject the request because the backlog has been finalized","C":"Schedule an emergency sprint planning session to accommodate the new feature","D":"Evaluate the feature and add it to the product backlog if appropriate"},"q":"A product owner on an agile project receives a request from a key business stakeholder to add a significant new feature that was not in the original product backlog. The stakeholder insists the feature is critical and wants it included in the current sprint.\nWhat should the product owner do?","exp":"D. Evaluate the feature and add it to the product backlog if appropriate\n\nExplanation: Agile projects manage new requirements through the product backlog. The product owner evaluates requests, determines backlog eligibility, and prioritizes relative to existing items. Adding features directly to an active sprint disrupts the team’s commitment; the appropriate path is backlog addition, prioritization, and scheduling in a future sprint.\n\nWhy the other options are incorrect:\n\nAdding the feature to the current sprint bypasses sprint planning and disrupts the team’s committed work for the iteration.\n\nRejecting a change request because the backlog is ‘finalized’ is inappropriate and misunderstands how a backlog works on an Agile project.\n\nAn emergency sprint planning session is not a standard Scrum practice and mid-sprint changes should be team-aligned and must not endanger the sprint goal. The scenario gives no indication that this is the case.","ans":"D","hint":""},{"n":36,"opts":{"A":"The WBS provides a visual summary of the scope document and is created primarily for stakeholder communication purposes.","B":"The WBS is required by organizational process assets and must be completed regardless of whether scope is already well-defined.","C":"The WBS replaces the scope document once approved and serves as the single reference for all project work during the execution phase.","D":"The WBS decomposes deliverables into work packages that can be reliably estimated, assigned, and tracked, making scope manageable and measurable."},"q":"A project manager is planning a large event management project. After defining project scope, the team begins decomposing the work. A junior team member questions why they are breaking deliverables into smaller components when the scope document already describes the work in detail.\nHow should the project manager respond?","exp":"D. The WBS decomposes deliverables into work packages that can be reliably estimated, assigned, and tracked, making scope manageable and measurable.\n\nExplanation: The WBS breaks total project scope into work packages at a level where work can be estimated, assigned, scheduled, and monitored. Even when scope is well-described in a scope document, the WBS makes it actionable. Without this decomposition, managing a complex project becomes impractical.\n\nWhy the other options are incorrect:\n\nDescribing the WBS primarily as a communication artifact understates its functional role in enabling estimation, scheduling, and cost aggregation at the work package level.\n\nCiting OPA requirements as the sole justification misses the substantive planning value the WBS provides and does not actually answer the team member’s question.\n\nThe WBS does not replace the scope document; they serve complementary but distinct purposes and are both maintained throughout the project.","ans":"D","hint":""},{"n":37,"opts":{"A":"Pair each departing team member with a knowledge partner from the remaining staff.","B":"Record video walkthroughs with each departing team member before their last day.","C":"Have departing team members write detailed handover notes before they leave.","D":"Conduct structured lessons learned sessions with the full team before any members depart."},"q":"A software development team is completing the final phase of a two-year project. Several senior team members who were involved throughout are scheduled to leave the organization after closure. The project manager wants to capture as much institutional knowledge as possible before the team disperses.\nWhat should the project manager prioritize?","exp":"D. Conduct structured lessons learned sessions with the full team before any members depart.\n\nExplanation: Knowledge that exists only in experienced practitioners’ heads cannot be fully captured through individual documentation or observation. Facilitated group sessions surface collective insights through discussion and questioning in ways that individual efforts cannot replicate, and they must happen while the full team is still available.\n\nWhy the other options are incorrect:\n\nA knowledge partner can observe what someone does but not the reasoning and judgment behind it. Observable behavior is only part of what needs to be transferred.\n\nVideo walkthroughs are more expressive than written notes but remain one-directional. They capture what the individual chooses to share rather than what structured group discussion draws out.\n\nHandover notes reflect only what departing members think to document. Knowledge practitioners consider obvious often goes unrecorded entirely without facilitated prompting.","ans":"D","hint":""},{"n":38,"opts":{"A":"Update the project management plan directly to reflect current reality so the team has accurate guidance going forward.","B":"Notify the project sponsor of the variances and request permission to modify the project management plan.","C":"Analyze the root causes of the variances and submit formal change requests for any updates that require baseline modifications.","D":"Issue corrective action directives to bring performance back within thresholds before making any plan updates."},"q":"A project is six months into a 12-month timeline when the project manager receives a performance report showing cost and schedule variances that exceed established thresholds.\nWhat should the project manager do first?","exp":"C. Analyze the root causes of the variances and submit formal change requests for any updates that require baseline modifications.\n\nExplanation: Variances exceeding thresholds require root cause analysis before any action is taken. Understanding why the variances occurred determines whether corrective actions, preventive actions, or baseline changes are needed. Any baseline modifications must then go through integrated change control via formal change requests.\n\nWhy the other options are incorrect:\n\nUpdating the plan directly bypasses integrated change control. Baselined components require formal review and approval regardless of the project manager’s intent.\n\nRequesting informal sponsor permission does not fulfill the formal change control requirement. The proper mechanism is a change request, not a conversation.\n\nIssuing corrective actions before understanding root causes risks applying the wrong fix and potentially compounding the underlying problem.","ans":"C","hint":""},{"n":39,"opts":{"A":"Firm Fixed Price","B":"Cost Plus Incentive Fee","C":"Time and Materials","D":"Cost Plus Fixed Fee"},"q":"A project manager is procuring cybersecurity services for an upcoming system migration. The organization’s procurement policy prefers fixed-price contracts to minimize financial exposure. However, the exact vulnerabilities that will be discovered and addressed cannot be determined until the assessment begins.\nWhat contract type should the project manager recommend?","exp":"C. Time and Materials, to accommodate the evolving scope while maintaining visibility into costs.\n\nExplanation: T&M contracts are designed for engagements where scope cannot be fully defined upfront. They provide flexibility as work evolves while keeping cost visible through agreed hourly rates. A firm fixed price contract is inappropriate here because binding the vendor to a fixed deliverable before the scope is known shifts unfair risk and may produce inadequate work.\n\nWhy the other options are incorrect:\n\nFirm Fixed Price aligns with organizational policy but is unsuitable when scope is undefined.\n\nCost Plus Incentive Fee requires defined performance targets to structure the incentive. With scope unknown at the outset, there is no meaningful basis for setting those targets.\n\nCost Plus Fixed Fee reimburses all costs plus a fixed fee and is appropriate for larger, longer engagements with undefined scope. For a targeted assessment, it introduces more financial exposure than T&M without additional benefit.","ans":"C","hint":""},{"n":40,"opts":{"A":"Apply a predictive approach to the entire project.","B":"Apply an adaptive approach to the entire project.","C":"Separate the project into two independent projects with distinct methodologies.","D":"Use a predictive approach for the infrastructure component and an adaptive approach for the dashboards and reporting tools."},"q":"A project manager is leading an enterprise technology modernization initiative. The server infrastructure and network cabling must meet data center compliance standards that were defined before the project began. The employee-facing dashboards and reporting tools, however, have generated conflicting input from department heads who cannot agree on what information they need or how it should be displayed.\nWhat should the project manager do?","exp":"D. Use a predictive approach for the infrastructure component and an adaptive approach for the dashboards and reporting tools.\n\nExplanation: A hybrid approach is appropriate when a project contains components with fundamentally different characteristics. The infrastructure work has pre-defined compliance standards, making it suitable for predictive planning. The dashboards and reporting tools have unresolved, conflicting requirements, making iterative development the more appropriate path.\n\nWhy the other options are incorrect:\n\nApplying predictive to the entire project forces the dashboard and reporting work into a fixed scope before stakeholder requirements are resolved, which is precisely the condition that adaptive approaches are designed to handle.\n\nApplying adaptive to the entire project is inappropriate for the infrastructure component, where compliance standards are already defined and formal documentation is required.\n\nSplitting into two independent projects is not warranted when a hybrid framework can manage both components under a single project structure, avoiding the integration and coordination risks that separation would introduce.","ans":"D","hint":""},{"n":41,"opts":{"A":"Implement the team’s simplified format.","B":"Apply the FDA format as required.","C":"Submit a change request to the change control board.","D":"Ask the project sponsor to request a regulatory waiver."},"q":"A project manager overseeing a pharmaceutical development project believes the FDA submission reporting format required for the project adds significant administrative overhead. The team proposes simplifying it to save time.\nWhat should the project manager do?","exp":"B. Apply the FDA format as required.\n\nExplanation: The FDA reporting format is a mandatory external regulatory requirement, not something the team can simplify on its own for convenience. The project manager must ensure the project complies with required regulatory standards even when they add overhead.\n\nWhy the other options are incorrect:\n\nImplementing a simplified format unilaterally ignores the project’s compliance obligations and exposes the organization to regulatory risk.\n\nRouting a regulatory requirement through the change control board misapplies that process. Change control does not override external compliance obligations.\n\nRequesting a waiver through the sponsor may be theoretically possible in some contexts, the scenario gives no basis to pursue a waiver, and compliance should be followed unless an official exception already exists.","ans":"B","hint":""},{"n":42,"opts":{"A":"Focus recovery efforts on Activity B.","B":"Focus recovery efforts on Activity A.","C":"Reallocate resources from Activity B to Activity A.","D":"Escalate to the project sponsor."},"q":"A project manager is reviewing a schedule update and finds that two activities have been delayed. Activity A is on the critical path and is one day behind its planned start. Activity B has eight days of total float and is seven days behind its planned start. The project deadline cannot be moved.\nWhat should the project manager do first?","exp":"B. Focus recovery efforts on Activity A.\n\nExplanation: Activity A is on the critical path with zero float. Any further slippage directly extends the project end date. Activity B has consumed seven of its eight days of float and warrants close monitoring, but it has not yet threatened the deadline. When the deadline is fixed, the critical path activity is the immediate priority regardless of how much further the other activity has slipped.\n\nWhy the other options are incorrect:\n\nActivity B has slipped far more in absolute terms and is now nearly critical, but it still has one day of float remaining. Absolute slippage does not determine priority; remaining float and critical path status do.\n\nReallocating resources could be appropriate, but the question does not establish that moving resources from Activity B is the right or necessary corrective action. In exam terms, you should choose the broader and always valid answer rather than a specific action that may or may not be appropriate based on the information given.\n\nEscalation is premature before the project manager has attempted to address the delay through standard schedule management.","ans":"B","hint":""},{"n":43,"opts":{"A":"$480,000","B":"$600,000","C":"$660,000","D":"$750,000"},"q":"Topic: EVM calculations\nA project manager receives the following status update at the end of the third month of a sixmonth project:\nBudget at Completion (BAC): $600,000\nEarned Value (EV): $240,000\nActual Cost (AC): $300,000\nAssuming current cost performance continues for the remainder of the project, what is the Estimate at Completion (EAC)?","exp":"D. $750,000\n\nExplanation: When current cost performance is expected to continue, EAC = BAC / CPI. CPI = EV / AC = $240,000 / $300,000 = 0.80. EAC = $600,000 / 0.80 = $750,000. The project is over budget and will cost $150,000 more than planned if performance does not improve.\n\nWhy the other options are incorrect:\n\n$480,000 results from multiplying BAC by CPI rather than dividing, reversing the formula.\n\n$600,000 is the original BAC and assumes the project will return to planned performance for the remaining work, which contradicts the premise that current performance continues.\n\n$660,000 results from AC + (BAC - EV) = $300,000 + $360,000, which is the EAC formula that assumes remaining work will be performed at the originally planned rate rather than the current rate.","ans":"D","hint":""},{"n":44,"opts":{"A":"Ask the sponsor to send a clarifying memo to the team leads describing the project’s primary objective.","B":"Update the project scope document to reflect both objectives so neither group feels excluded.","C":"Develop or revisit the project’s vision statement to establish a single shared definition of the project’s purpose.","D":"Allow both interpretations to continue since cost reduction and quality improvement are complementary goals."},"q":"A project manager notices that the project sponsor recently approved a vendor switch to reduce material costs, while the team leads have been adding inspection checkpoints and quality review cycles throughout the schedule. Neither group has consulted the other, and both believe they are acting in the project’s best interest.\nWhat should the project manager do?","exp":"C. Develop or revisit the project’s vision statement to establish a single shared definition of the project’s purpose.\n\nExplanation: The sponsor and team leads are pulling the project in opposite directions because they are operating from different understandings of what it is trying to achieve. Cost reduction and quality improvement can directly conflict when tradeoffs arise. A shared vision statement gives both groups a single authoritative reference point for decisions going forward.\n\nWhy the other options are incorrect:\n\nA sponsor memo positions one interpretation as correct without creating shared ownership across both groups. The team leads had no input and may not accept a direction handed down to them.\n\nReflecting both objectives in the scope document embeds the conflict rather than resolving it. When cost and quality come into tension on a specific decision, the scope document offers no basis for choosing.\n\nAllowing both to continue assumes the two goals will remain compatible, but the vendor switch and the added inspection cycles are already working at cross purposes.","ans":"C","hint":""},{"n":45,"opts":{"A":"Begin the phase with the part-time developer and request additional support if the workload becomes unmanageable.","B":"Escalate the resource conflict to the project sponsor to resolve with the functional manager.","C":"Revise the project schedule to accommodate part-time resource availability.","D":"Document the resource constraint as a risk and continue negotiating with the functional manager."},"q":"A project manager in a balanced matrix organization needs a senior developer full-time for a critical six-week delivery phase. The functional manager has agreed to provide the developer only part-time, citing departmental commitments. Direct negotiations have continued for two weeks without resolution, and the phase start date is one week away.\nWhat should the project manager do?","exp":"B. Escalate the resource conflict to the project sponsor to resolve with the functional manager.\n\nExplanation: In a matrix organization the PM shares authority with functional managers and cannot unilaterally resolve resource disputes. Direct negotiation is the correct first step, but two weeks of failed negotiation with one week remaining before the phase starts establishes that the PM has exhausted reasonable direct options. The sponsor has the organizational authority to resolve cross-functional conflicts the PM cannot.\n\nWhy the other options are incorrect:\n\nBeginning the phase without the required resource accepts a known critical constraint and sets the team up for a predictable failure rather than resolving it before work begins.\n\nRevising the schedule treats the functional manager’s position as final when it has not been resolved through appropriate channels. The PM has not yet used all available escalation options.\n\nContinuing to negotiate after two weeks without progress repeats an approach that has already failed. With one week remaining, the same negotiation is unlikely to produce a different result.","ans":"B","hint":""},{"n":46,"opts":{"A":"Invest in earlier defect prevention activities such as design reviews and developer training.","B":"Add more testing cycles at the end of development to catch defects before they reach customers.","C":"Increase the post-release support budget to handle the expected volume of customer issues.","D":"Implement a defect tracking system to better categorize and prioritize customer-reported issues."},"q":"A software company’s recent product release has generated a high volume of customer support tickets and emergency patches. A review reveals that internal testing during development caught very few defects before release. The project manager is now planning the quality approach for the next release.\nWhat should the project manager do?","exp":"A. Invest in earlier defect prevention activities such as design reviews and developer training.\n\nExplanation: The pattern shows defects consistently escaping to customers, which represents the most expensive category in the cost of quality framework. Prevention activities catch defects at the lowest possible cost, earlier in the process than appraisal, internal failure, or external failure. When defects are already reaching customers at volume, shifting effort to the front of the process is the highest-value response.\n\nWhy the other options are incorrect:\n\nAdding end-of-development testing improves appraisal but still positions quality effort late in the process, where defects are more expensive to find and fix than if caught during design.\n\nIncreasing the support budget accepts and funds the most expensive quality category rather than addressing its root cause.\n\nA defect tracking system improves visibility into failures that have already occurred but does nothing to prevent them from occurring in the first place.","ans":"A","hint":""},{"n":47,"opts":{"A":"Close the original risk since the approved mitigation response has already been documented and approved during planning.","B":"Update the risk register to reflect the secondary supplier’s capacity limitation and continue monitoring.","C":"Update the risk register to reflect the remaining exposure and facilitate development of an additional risk response.","D":"Escalate to the project sponsor since the documented mitigation strategy has proven insufficient."},"q":"A project team identified a risk of a key supplier failing to deliver critical components on time and secured a secondary supplier as the approved mitigation response. The risk register reflects this arrangement as the current response plan. During a subsequent risk review, the team discovers the secondary supplier has limited capacity and could only partially fulfill the order if the primary supplier fails, leaving a significant materials gap.\nWhat should the project manager do?","exp":"C. Update the risk register to reflect the remaining exposure and facilitate development of an additional risk response.\n\nExplanation: The risk register currently shows the secondary supplier arrangement as the complete response, but that is no longer accurate. Significant exposure remains that the existing documentation does not capture. The register must reflect current reality, and because the remaining exposure is significant, it requires an additional response rather than passive monitoring.\n\nWhy the other options are incorrect:\n\nClosing the risk conflates planning completion with risk resolution. A documented and approved response does not mean the risk has been adequately addressed, only that a response was agreed upon at a point in time.\n\nUpdating the register without planning an additional response treats documentation as a substitute for action. When residual exposure is significant, recording it accurately is necessary but not sufficient.\n\nEscalating to the sponsor is premature when the project manager has not yet developed additional response options. Escalation is appropriate after available paths have been exhausted, not as a first response to new risk information.","ans":"C","hint":""},{"n":48,"opts":{"A":"Ask the team member to remove all unauthorized additions and return the deliverable to its baselined state.","B":"Submit retroactive change requests for the additions to bring them into the formal record.","C":"Inform the end users that all future requests must go through the change request process.","D":"Stop the informal additions, assess their impact on schedule and cost, and determine whether formal change requests should be submitted."},"q":"During a status review, a project manager discovers that a team member has been adding features to a software deliverable based on informal conversations with end users. None of the additions were submitted as change requests or reflected in the approved scope baseline.\nWhat should the project manager do first?","exp":"D. Stop the informal additions, assess their impact on schedule and cost, and determine whether formal change requests should be submitted.\n\nExplanation: Unauthorized scope additions must be stopped immediately, but removal without analysis is premature. Some additions may have legitimate value worth formalizing through change control; others may need to be removed. Impact assessment determines which path is appropriate and ensures any retained changes are properly authorized.\n\nWhy the other options are incorrect:\n\nRemoving the additions immediately skips impact assessment and assumes removal is the correct outcome without understanding what was changed or what reversing it would cost.\n\nSubmitting retroactive change requests assumes the additions should be kept without first evaluating their impact on schedule, cost, and the overall baseline.\n\nInforming end users about the process addresses future behavior but does nothing about the unauthorized additions already in the deliverable.","ans":"D","hint":""},{"n":49,"opts":{"A":"Tell the customer that agile projects cannot provide forecasts.","B":"Provide a fixed completion date to reassure the customer.","C":"Use the team’s velocity and remaining backlog to project a likely range.","D":"Ask the customer to wait until the features are actually delivered."},"q":"A project manager is leading an agile project where the team has been delivering steadily. The customer asks for a forecast of when a specific set of features will be completed.\nWhat should the project manager do?","exp":"C. Use the team’s velocity and remaining backlog to project a likely range.\n\nExplanation: Velocity combined with the size of the remaining backlog allows the project manager to forecast a realistic completion range for the requested features. This gives the customer useful, evidence-based information while honestly reflecting the inherent uncertainty.\n\nWhy the other options are incorrect:\n\nClaiming agile cannot forecast is inaccurate; empirical data like velocity is precisely what enables forecasting.\n\nProviding a single fixed date overstates certainty and sets up the team to miss a falsely precise commitment.\n\nAsking the customer to wait withholds information the project manager can reasonably provide.","ans":"C","hint":""},{"n":50,"opts":{"A":"Use a hybrid approach, applying predictive planning to the core features and adaptive iterations for the remaining features.","B":"Use a predictive approach to maintain tight control over schedule and budget given the fixed deadline.","C":"Use an adaptive approach to incorporate user feedback as the product evolves beyond its core functionality.","D":"Use an adaptive approach since the startup environment and uncertain user preferences make flexibility more valuable than upfront planning."},"q":"A project manager is leading development of a new mobile app for a startup. The startup has clear specifications for the app’s core features. Beyond that core, users’ preferences for additional features are unknown and will need to be discovered through early user feedback. The app has a fixed launch date in eight months.\nWhat development approach should the project manager recommend?","exp":"A. Use a hybrid approach, applying predictive planning to the core features and adaptive iterations for the remaining features.\n\nExplanation: The core transaction and account management features have defined specifications that suit predictive planning. The remaining features have genuinely unknown requirements that will only emerge through user feedback, which is precisely the condition adaptive approaches are designed for. A hybrid approach applies each methodology where it fits rather than forcing one approach onto requirements with different characteristics.\n\nWhy the other options are incorrect:\n\nA fully predictive approach applies the right discipline to the known core but forces the evolving features into a fixed-scope model before user preferences are understood, likely producing features that miss the mark.\n\nA fully adaptive approach handles the evolving features well but applies unnecessary flexibility to the core, which has stable defined specifications that would benefit from upfront planning and a clear baseline.\n\nThe startup context and uncertain user preferences are real factors, but they apply only to part of the project. The defined core and fixed deadline still warrant predictive discipline for that component, making a wholesale adaptive approach insufficient.","ans":"A","hint":""},{"n":51,"opts":{"A":"Follow each new priority immediately as the sponsor directs.","B":"Ignore the sponsor’s changes and stick to the original plan.","C":"Ask the team to work on all priorities simultaneously.","D":"Discuss the impact of shifting priorities with the sponsor."},"q":"A project manager is leading a project where the sponsor frequently changes the project’s priorities, leaving the team uncertain about what to focus on from week to week.\nWhat should the project manager do?","exp":"D. Discuss the impact of shifting priorities with the sponsor.\n\nExplanation: Constantly shifting priorities disrupt the team and waste effort. Discussing the impact with the sponsor helps them understand the cost of frequent changes and supports establishing a more stable, agreed set of priorities the team can execute against.\n\nWhy the other options are incorrect:\n\nFollowing every change immediately perpetuates the churn and the team’s uncertainty.\n\nIgnoring the sponsor’s changes disregards legitimate authority and may take the project off course.\n\nWorking on all priorities at once spreads the team thin and ensures little gets finished.","ans":"D","hint":""},{"n":52,"opts":{"A":"Wait for the change control board to formally evaluate and approve the change before work begins.","B":"Begin work immediately since the sponsor has approved the change and any delay adds unnecessary cost.","C":"Begin preliminary planning for the change while waiting for the change control board to meet.","D":"Ask the sponsor to issue a written authorization so work can begin without waiting for the board."},"q":"A project manager receives a scope change request that the project sponsor has reviewed and personally approved. The change control board is scheduled to meet in three days. The sponsor asks the project manager to begin work on the change immediately to avoid losing time.\nWhat should the project manager do?","exp":"A. Wait for the change control board to formally evaluate and approve the change before work begins.\n\nExplanation: The sponsor’s approval is one input to the change control process, not a substitute for it. The CCB exists to evaluate the change’s impact on scope, schedule, cost, and risk across the full project baseline. Work on any change may only begin after the CCB has formally reviewed and approved it, regardless of who has already endorsed it.\n\nWhy the other options are incorrect:\n\nSponsor approval carries authority over project direction but does not replace the CCB’s role in evaluating cross-constraint impact. Beginning work before that evaluation creates baseline changes without formal authorization.\n\nPreliminary planning is a reasonable-sounding middle ground, but the change control process governs all work on a proposed change, not just execution. Starting any work before CCB approval bypasses the intent of the process.\n\nA written sponsor authorization is still sponsor authorization. It does not constitute CCB approval or replicate the impact assessment the CCB is responsible for conducting.","ans":"A","hint":""},{"n":53,"opts":{"A":"Release the team members to their new assignments since the client has verbally confirmed satisfaction.","B":"Release the team and ask the client to complete the formal acceptance document remotely at their convenience.","C":"Escalate to the project sponsor to negotiate with the client to expedite the formal sign-off.","D":"Retain the team until the client formally documents acceptance, then proceed with resource release."},"q":"A project manager is preparing to close a project. The final deliverable has been completed and the client has verbally indicated satisfaction with the results. Several team members have been offered positions on high-priority projects starting next week. The client has not yet signed the formal acceptance document.\nWhat should the project manager do?","exp":"D. Retain the team until the client formally documents acceptance, then proceed with resource release.\n\nExplanation: Formal documented acceptance is a required project closure activity. Verbal satisfaction indicates the client is unlikely to raise objections, but it does not constitute sign-off. Releasing the team before acceptance is complete removes the PM’s ability to respond to any issues identified during the formal review and leaves the project without documented closure.\n\nWhy the other options are incorrect:\n\nVerbal satisfaction is not a closure document. Releasing resources based on it treats informal communication as equivalent to a formal record, which creates risk if disputes arise after the team has moved on.\n\nReleasing the team and pursuing the signature remotely still removes the team before closure is complete. The logistics of where the signature happens do not change the sequencing requirement.\n\nEscalating to the sponsor is premature. The PM can pursue formal acceptance directly with the client and should do so before involving executive stakeholders.","ans":"D","hint":""},{"n":54,"opts":{"A":"Reject the request to protect the approved schedule.","B":"Evaluate the request based on long-term stakeholder value.","C":"Delay the request until construction is complete.","D":"Ask the community to submit the request after project closure."},"q":"A project manager is leading a highway expansion project. Local residents request additional landscaping and sound barriers to reduce the project’s long-term impact on nearby neighborhoods. The changes are affordable but require additional planning.\nWhat should the project manager do?","exp":"B. Evaluate the request based on long-term stakeholder value.\n\nExplanation: Sustainable projects consider long-term environmental and social impacts while balancing stakeholder needs and project objectives.\n\nWhy the other options are incorrect:\n\nProtecting the schedule alone ignores sustainability.\n\nWaiting until construction is complete removes opportunities to improve outcomes.\n\nAddressing the concern after project closure is too late.","ans":"B","hint":""},{"n":55,"opts":{"A":"Document the lessons learned immediately to preserve the details while they are still fresh.","B":"Defer documentation until after the delivery commitment is met as the sponsor has requested.","C":"Ask team members to keep personal notes and compile them formally at project closure.","D":"Capture the lessons learned at the upcoming sprint retrospective."},"q":"A project manager is leading an agile project six months into a 12-month delivery. The team recently navigated a vendor failure and a scope misalignment and took informal notes on the resolution. The project is in an active sprint with a delivery commitment in two weeks, after which a retrospective is scheduled. The project sponsor has asked the team to stay focused on delivery and avoid administrative activities until the sprint is complete.\nWhat should the project manager do?","exp":"D. Capture the lessons learned at the upcoming sprint retrospective.\n\nExplanation: The team is in an active sprint with a delivery commitment in two weeks, and a retrospective is already scheduled right after. So the PM should use the established agile ceremony to capture lessons learned rather than interrupt the sprint with separate documentation activity.\n\nWhy the other options are incorrect:\n\nDocumenting immediately disrupts sprint focus. Since the team already captured informal notes, immediate formal documentation is no longer as necessary to preserve memory.\n\nDeferring until after the delivery commitment without specifying the retrospective implies a longer, unstructured delay that skips the agile ceremony designed for exactly this purpose.\n\nPersonal notes compiled at closure defer lessons learned to the end of the project entirely, which misses both the retrospective mechanism and the opportunity to apply insights to remaining sprints.","ans":"D","hint":""},{"n":56,"opts":{"A":"Return to planning to identify additional improvements that could reduce defect rates further.","B":"Continue collecting data for another four weeks before drawing conclusions about the protocol’s effectiveness.","C":"Standardize the new testing protocol as the permanent process and update the organizational process assets.","D":"Introduce additional testing procedures to build on the improvement already achieved."},"q":"A project manager introduced a new testing protocol four weeks ago after defect rates exceeded acceptable thresholds. The team has since collected data showing defect rates have dropped by 30%. The protocol appears to be working as intended.\nWhat should the project manager do next?","exp":"C. Standardize the new testing protocol as the permanent process and update the organizational process assets.\n\nExplanation: The data collected confirms the protocol achieved its intended outcome. The next step is to standardize the successful change as the new permanent process and record it in the organizational process assets so the improvement is preserved and available to future projects.\n\nWhy the other options are incorrect:\n\nReturning to planning before standardizing the current improvement skips the step that locks in the gain. Planning for additional improvements is appropriate after the current one has been formalized.\n\nFour weeks of data showing a 30% reduction is conclusive. Extending the data collection phase delays a decision that the existing data already supports.\n\nIntroducing additional procedures before standardizing the current protocol risks undermining the baseline that produced the improvement. The current change should be formalized before layering on new interventions.","ans":"C","hint":""},{"n":57,"opts":{"A":"A. Select the supplier with the lowest purchase price.","B":"B. Evaluate both suppliers using sustainability and long-term value.","C":"C. Choose the supplier with the shortest delivery schedule.","D":"D. Allow the procurement manager to make the selection."},"q":"A project manager is selecting a supplier for a large infrastructure project. One supplier has the lowest price, while another follows responsible sourcing practices and has a stronger environmental record. Both suppliers satisfy the technical requirements.\nWhat should the project manager do?","exp":"B. Evaluate both suppliers using sustainability and long-term value.\n\nExplanation: Sustainable procurement balances environmental, social, and economic considerations instead of focusing on cost alone.\n\nWhy the other options are incorrect:\n\nLowest cost ignores the triple bottom line.\n\nDelivery speed alone is not a sustainability decision.\n\nThe project manager remains responsible for evaluating project impacts.","ans":"B","hint":""},{"n":58,"opts":{"A":"A. Purchase carbon credits after production is complete.","B":"B. Restore the affected area after production ends.","C":"C. Reduce the amount of waste produced during manufacturing.","D":"D. Redesign the process to prevent the waste from being generated."},"q":"A project manager is planning a manufacturing project that will generate chemical waste. Engineers identify several approaches to reduce the environmental impact before production begins.\nWhich approach best follows PMI’s sustainability mindset?","exp":"D. Redesign the process to prevent the waste from being generated.\n\nExplanation: The Sustainability Pyramid prioritizes avoiding negative impacts whenever possible before minimizing, restoring, or offsetting them.\n\nWhy the other options are incorrect:\n\nOffsetting is the least desirable approach.\n\nRestoring occurs after the impact has happened.\n\nMinimizing is appropriate only when avoidance is not possible.","ans":"D","hint":""},{"n":59,"opts":{"A":"A. Select the alternative that AI ranks highest because it evaluated more data than the project team.","B":"B. Delay the decision until AI identifies a single optimal solution.","C":"C. Ask the steering committee to select the preferred alternative using the AI-generated comparison.","D":"D. Use AI to analyze the alternatives, then apply professional judgment before making a recommendation."},"q":"A project manager is leading a large infrastructure project. The organization is considering several design alternatives that differ in cost, schedule, quality, and long-term maintenance requirements. The project manager plans to use AI to compare the available options before presenting a recommendation to the steering committee.\nWhat should the project manager do?","exp":"D. Use AI to analyze the alternatives, then apply professional judgment before making a recommendation.\n\nExplanation: AI augmentation supports complex decision making by comparing alternatives and evaluating trade-offs. The project manager remains responsible for applying professional judgment and making the final recommendation.\n\nWhy the other options are incorrect:\n\nAI should not make final project decisions independently.\n\nWaiting for AI to determine one correct answer ignores the need for human judgment.\n\nThe steering committee should receive the project manager’s informed recommendation rathe","ans":"D","hint":""},{"n":60,"opts":{"A":"Request that the resource manager assign dedicated engineers to the new project.","B":"Assess the impact on both projects and identify tasks that can be sequenced or deferred to reduce contention.","C":"Escalate the conflict to the PMO before continuing project planning.","D":"Notify the other project manager and suggest coordinating schedules informally."},"q":"A project manager is in the early planning phase of a new product development initiative. A review of the resource pool reveals that three specialized engineers needed for the project are also assigned to a high-priority legacy system upgrade running in parallel. Both projects share the same resource pool.\nWhat should the project manager do first?","exp":"B. Assess the impact on both projects and identify tasks that can be sequenced or deferred to reduce contention.\n\nExplanation: Identifying a resource conflict is the first step, not the last. Before escalating or requesting dedicated resources, the PM needs to understand the actual impact on both projects and determine what planning options exist. That analysis determines whether escalation is necessary and what to ask for.\n\nWhy the other options are incorrect:\n\nRequesting dedicated engineers before understanding the full impact may be premature. The analysis may reveal that sequencing or deferral eliminates the conflict without requiring resource reassignment.\n\nEscalating to the PMO before conducting an initial assessment puts the problem in others’ hands before the PM has done the work needed to inform a useful conversation.\n\nInformal coordination with the other project manager may be a useful tactic, but it should follow an impact assessment, not replace one.","ans":"B","hint":""},{"n":61,"opts":{"A":"Allow the AI system to distribute the reports because the information comes directly from approved project data.","B":"Continue reviewing AI-generated reports before they are distributed to stakeholders.","C":"Ask the sponsor to approve each AI-generated report before distribution.","D":"Configure the AI tool to distribute reports only when no project issues are identified."},"q":"A project manager is leading a software implementation project. The organization recently introduced an AI tool that automatically prepares weekly project status reports using schedule performance, issue logs, and cost data. After several successful reports, the sponsor asks the project manager to allow the AI system to distribute future reports directly to stakeholders without manual review so the team can spend more time on project execution.\nWhat should the project manager do?","exp":"B. Continue reviewing AI-generated reports before they are distributed to stakeholders.\n\nExplanation: AI can automate routine reporting activities, but the project manager remains responsible for project communications. AI-generated outputs should always be reviewed and validated before they are shared with stakeholders.\n\nWhy the other options are incorrect:\n\nThe information originates from project data, but AI can still misinterpret or summarize information incorrectly. Human validation is still required.\n\nSponsor approval does not replace the project manager’s responsibility for validating project communications.\n\nRestricting distribution based on project issues changes when reports are sent but does not address the need to validate AI-generated information.","ans":"B","hint":""},{"n":62,"opts":{"A":"Draw on the contingency budget to absorb the cost increase as the sponsor suggests.","B":"Renegotiate supplier contracts to fix pricing in the project’s home currency.","C":"Suspend international procurement until exchange rates stabilize.","D":"Work with the finance team to evaluate and implement hedging instruments to limit further exposure."},"q":"A construction project sources specialized components from vendors in Europe and Asia. Midway through execution, currency fluctuations cause projected procurement costs to increase by 15%. The project sponsor suggests drawing on the contingency budget to cover the difference and continuing with the current plan. The finance team has identified forward contracts as a potential hedge against further exposure.\nWhat should the project manager do?","exp":"D. Work with the finance team to evaluate and implement hedging instruments to limit further exposure.\n\nExplanation: Currency exposure is a financial risk that requires a financial risk response. The finance team has already identified a viable strategy. Using the contingency budget absorbs the current impact but leaves the project exposed to further losses if rates continue to shift. Implementing hedging instruments addresses the underlying risk rather than its symptoms.\n\nWhy the other options are incorrect:\n\nDrawing on the contingency budget follows the sponsor’s direction but treats the cost increase as a one-time hit rather than an ongoing exposure. If rates continue to move, reserves will be depleted without the risk being managed.\n\nRenegotiating supplier contracts to fix home currency pricing may not be feasible mid-project and depends entirely on supplier agreement. It also bypasses the finance expertise already available.\n\nSuspending procurement avoids further exposure but introduces schedule delays that the project cannot absorb and does not constitute a risk management strategy.","ans":"D","hint":""},{"n":63,"opts":{"A":"Evaluate the project’s specific characteristics to determine the most suitable delivery approach.","B":"Adopt the delivery approach recommended by the PMO to ensure alignment with the organization’s portfolio priorities.","C":"Review delivery approaches used on similar regulatory initiatives to identify which has performed best.","D":"Consult with the project sponsor to determine which approach best aligns with the organization’s strategic priorities."},"q":"A project manager has been assigned to lead a new regulatory reporting initiative for a financial services firm. Before planning begins, the project manager must determine the appropriate delivery approach.\nWhat should the project manager do first?","exp":"A. Evaluate the project’s specific characteristics to determine the most suitable delivery approach.\n\nExplanation: The project manager should first evaluate the project’s characteristics to determine the most appropriate delivery approach. Defaulting to a methodology based on PMO preference or precedent skips the assessment that determines what actually fits this project.\n\nWhy the other options are incorrect:\n\nThe PMO’s recommended approach reflects organizational standards and portfolio priorities, but those considerations do not determine what delivery approach fits a specific project’s characteristics. The same organization may run projects that suit very different approaches.\n\nReviewing similar projects provides useful benchmarks but historical performance on other initiatives does not determine what approach fits this project’s particular circumstances.\n\nSponsor input on strategic alignment is valuable for overall direction but does not substitute for the characteristic-based assessment that drives methodology selection.","ans":"A","hint":""},{"n":64,"opts":{"A":"Research and propose an automated testing tool that balances delivery speed with compliance capabilities.","B":"Facilitate a discussion with stakeholders to clarify the intended outcomes and evaluate solutions.","C":"Implement the IT Director’s recommended tool.","D":"Decline the IT Director’s suggestion and ask stakeholders to propose alternatives."},"q":"A project manager is leading a software development project for a healthcare organization. The IT Director proposes adopting a new automated testing tool that will speed up delivery. The project sponsor notes that the project’s primary objective is regulatory compliance and is concerned the tool may not address compliance testing specifically.\nWhat should the project manager do?","exp":"B. Facilitate a discussion with stakeholders to clarify the intended outcomes and evaluate solutions.\n\nExplanation: When stakeholders are proposing solutions from different priorities, the PM’s role is to surface the underlying outcomes and ensure any solution is evaluated against what the project is actually trying to achieve. Implementing or denying the suggestion before that examination risks optimizing for the wrong objective.\n\nWhy the other options are incorrect:\n\nResearching alternative tools assumes the problem is the tool choice rather than the unresolved question of what outcome the project needs to optimize for. A better tool still may not address the compliance objective if that hasn’t been examined first.\n\nImplementing the tool before examining intended outcomes assumes the solution is correct before understanding what the project needs to optimize for.\n\nDeclining the suggestion and asking for alternatives is unnecessarily dismissive and skips the outcome examination that would determine whether the original suggestion, a variation, or something else entirely is most appropriate.","ans":"B","hint":""},{"n":65,"opts":{"A":"Store all technical documentation and process guides in a centralized repository accessible to the incoming team.","B":"Schedule a formal handover meeting where the current team presents the documentation to the incoming team.","C":"Organize structured sessions with the current team to surface and document the judgment calls, workarounds, and informal practices developed during the project.","D":"Arrange for key members of the current team to remain available for questions during the first month of the next phase."},"q":"A project manager is closing a complex infrastructure upgrade. The team produced detailed technical documentation and process guides throughout the project. A new team will handle the next phase, beginning in three months. The project manager is concerned that the documentation alone does not capture the judgment calls, workarounds, and informal practices the current team developed.\nWhat should the project manager do?","exp":"C. Organize structured sessions with the current team to surface and document the judgment calls, workarounds, and informal practices developed during the project.\n\nExplanation: The project manager has already identified that the documentation does not capture everything. Structured sessions create the conditions for tacit knowledge to surface through active discussion and prompting.\n\nWhy the other options are incorrect:\n\nA centralized repository makes existing documentation accessible but does not address what has not been documented. The gap the project manager identified remains.\n\nA handover meeting presenting existing documentation has the same limitation. Transferring the documentation to another audience does not surface what the documentation omits.\n\nMaking team members available for questions is a passive approach that depends on the incoming team knowing what they do not know. Tacit knowledge that has never been articulated cannot be retrieved this way.","ans":"C","hint":""},{"n":66,"opts":{"A":"A. Select the lower-cost system to protect the project budget.","B":"B. Evaluate both systems using sustainability objectives and long-term value.","C":"C. Ask the sponsor to choose the preferred heating system.","D":"D. Delay the decision until construction begins."},"q":"A project manager is leading the design of a new office building. Two heating systems meet the technical requirements. One has a lower purchase price but higher operating costs and energy consumption. The other costs more initially but reduces energy use over the building’s life.\nWhat should the project manager do?","exp":"B. Evaluate both systems using sustainability objectives and long-term value.\n\nExplanation: Sustainability requires balancing environmental, social, and financial impacts while considering long-term value rather than only initial cost.\n\nWhy the other options are incorrect:\n\nLowest cost ignores long-term sustainability.\n\nThe project manager should evaluate the options before escalating.\n\nDelaying the decision provides no additional benefit.","ans":"B","hint":""},{"n":67,"opts":{"A":"Ask the development team to add the disputed functionality to satisfy both business units before closing.","B":"Review the requirements documentation and acceptance criteria established during the planning phase.","C":"Escalate the dispute to the project sponsor to make a final determination.","D":"Meet with both business units to review the documented acceptance criteria and reach a shared understanding.","E":"Request formal project closure and address the feature dispute as an enhancement in the next release."},"q":"A project team has completed development of a new customer portal for a financial services company. During final review, two business units disagree about whether a reporting feature meets requirements. One unit considers it unacceptable; the other finds it sufficient. The project manager needs to resolve the dispute to obtain final sign-off and close the project.\nWhich should the project manager do? (Choose 2)","exp":"B and D. Explanation: When stakeholders disagree about whether a deliverable meets requirements, the documented acceptance criteria are the objective reference point. Reviewing those criteria first establishes the factual basis, and meeting with both parties to walk through them together creates the conditions for shared understanding and resolution.\n\nWhy the other options are incorrect:\n\nAdding functionality to satisfy both units treats a disputed requirement as an opportunity for scope addition rather than a question of whether agreed standards were met.\n\nEscalating to the sponsor is premature before the PM has reviewed what was documented and engaged both parties. The sponsor should be involved if that process fails, not instead of it.\n\nClosing the project and deferring the dispute as an enhancement bypasses the acceptance requirement entirely. The project cannot be formally closed while a stakeholder dispute about deliverable acceptance is unresolved.","ans":["B","D"],"multi":true,"pick":2,"hint":""},{"n":68,"opts":{"A":"Review the backlog to confirm all user stories assigned to this release have been marked complete.","B":"Compare the completed deliverables against the team’s definition of done.","C":"Schedule a review with stakeholders to evaluate whether the release meets their expectations.","D":"Assess whether the release has achieved its intended business value against the original business case."},"q":"A project manager is overseeing the development of an enterprise reporting tool. The first of three planned releases is nearly complete. Before transitioning to the next release cycle, the project manager needs to verify that all deliverables meet the established completion standard.\nWhat should the project manager do?","exp":"B. Compare the completed deliverables against the team’s definition of done.\n\nExplanation: The Definition of Done is the team’s pre-established, objective standard for what complete means. Comparing deliverables against it provides a consistent, agreed-upon basis for determining whether the phase is genuinely finished before transitioning.\n\nWhy the other options are incorrect:\n\nA backlog review confirms which tasks have been marked done but does not verify whether each item met the quality and completion criteria defined by the team.\n\nA stakeholder review provides valuable feedback but is a subjective evaluation. It does not replace the objective standard the team established at the outset.\n\nBusiness value assessment measures whether the release achieved its intended outcomes. That is a separate and worthwhile activity but is not the same as verifying that deliverables met completion criteria.","ans":"B","hint":""},{"n":69,"opts":{"A":"Analyze each stakeholder group’s concerns and rank expectations according to organizational authority.","B":"Present a detailed business case to all stakeholders demonstrating the initiative’s benefits to secure their alignment.","C":"Schedule structured sessions with the project sponsor and key stakeholder groups to discuss the initiative’s objectives.","D":"Identify expectations shared across most stakeholder groups and focus communication efforts on reinforcing those priorities."},"q":"A project manager is leading a digital transformation initiative that will significantly change workflows across multiple departments. The initiative has strong executive support but has encountered varying levels of enthusiasm from departmental managers. The project manager needs to align expectations across all stakeholder groups before detailed planning begins.\nWhat should the project manager do?","exp":"C. Schedule structured sessions with the project sponsor and key stakeholder groups to discuss the initiative’s objectives and align expectations collaboratively.\n\nExplanation: Expectation alignment requires bringing stakeholders into structured dialogue, not analyzing them from a distance or persuading them toward a predetermined position. Structured sessions with the sponsor create the conditions for shared understanding across groups with different levels of enthusiasm and different concerns.\n\nWhy the other options are incorrect:\n\nStakeholder expectations should be analyzed, but not simply ranked by organizational power and then prioritized that way.\n\nPresenting a business case to secure alignment frames the process as persuasion. Alignment means reaching shared understanding through discussion, not convincing stakeholders to accept the project team’s position.\n\nFocusing only on shared expectations leaves divergent concerns unaddressed. Groups with different levels of enthusiasm likely have specific concerns that require direct engagement, not just reinforcement of what everyone already agrees on.","ans":"C","hint":""},{"n":70,"opts":{"A":"Assess the impact of the incompatibility on the project baseline and submit a formal change request if updates are required.","B":"Continue the installation as planned and document the electrical incompatibility as a lessons learned item.","C":"Apply rolling wave planning to progressively refine the installation approach as more information becomes available.","D":"Increase the project’s contingency reserves to cover potential rework costs from the incompatibility."},"q":"A project manager is overseeing the installation of a new manufacturing control system. The project management plan has been approved and baselined. Three weeks into execution, the installation team discovers that the facility’s existing electrical infrastructure is incompatible with the new system’s power requirements, a condition not identified during planning.\nWhat should the project manager do first?","exp":"A. Assess the impact of the incompatibility on the project baseline and submit a formal change request if updates are required.\n\nExplanation: When an unforeseen factor is discovered during execution, the first step is to understand its impact on scope, schedule, and cost before taking any action. If the assessment reveals the baseline needs to change, a formal change request is the appropriate mechanism. Acting on the project without that analysis risks compounding the problem.\n\nWhy the other options are incorrect:\n\nContinuing as planned ignores a discovered condition that could directly affect the installation. Documenting it as lessons learned defers a problem that is active and present.\n\nRolling wave planning is a technique for progressively elaborating scope that was always known to be uncertain. It does not apply to a specific, identifiable technical constraint discovered during execution.\n\nIncreasing contingency reserves treats a financial symptom without understanding what the incompatibility actually means for the project. Reserves cannot resolve a technical constraint.","ans":"A","hint":""},{"n":71,"opts":{"A":"Calculate the cost savings from avoiding potential privacy violations and share the analysis with the team.","B":"Implement automated compliance tracking tools to minimize the time the team spends on documentation.","C":"Educate the team and contractors on the purpose of the privacy requirements to build understanding and alignment.","D":"Identify ways to integrate the compliance activities into existing workflows to reduce perceived disruption."},"q":"A project manager is leading a healthcare facility construction project. The organization recently adopted a new data privacy framework that adds documentation and approval steps to several project processes. The lead contractor approaches the project manager and argues that the new requirements are unnecessary overhead that will delay delivery and asks whether they can be reduced or skipped for lower-risk activities.\nWhat should the project manager do?","exp":"C. Educate the team and contractors on the purpose of the privacy requirements to build understanding and alignment.\n\nExplanation: When mandatory requirements face pushback, the root cause is typically a lack of understanding of why they exist. Education addresses that directly. Without shared understanding, tools and workflow adjustments reduce friction but leave the underlying misalignment intact, which tends to surface as resistance and shortcuts later in the project.\n\nWhy the other options are incorrect:\n\nA cost savings analysis provides a financial argument but does not build genuine understanding of why the requirements exist. Teams that comply for financial reasons rather than understanding tend to look for workarounds.\n\nCompliance tracking tools may help later, but it assumes a solution before stakeholder buy-in and understanding are established. The contractor may still resist while using the tools.\n\nIntegrating compliance activities into existing workflows is also useful, but it comes after alignment. You do not start by streamlining a requirement people are still challenging as unnecessary.","ans":"C","hint":""},{"n":72,"opts":{"A":"Build additional buffer time into the project schedule to account for the complexity and potential rework.","B":"Engage cybersecurity and systems integration subject matter experts to help surface unknowns and define interdependencies.","C":"Bring in an external project management consultant to provide oversight and keep the planning process on track.","D":"Conduct a stakeholder survey to gather requirements input before attempting to map system interdependencies."},"q":"A project manager has been assigned to lead a first-of-its-kind cybersecurity infrastructure upgrade for a government agency. The project involves integrating multiple legacy systems with new cloud-based security protocols. The team is in early planning and struggling to define the full scope due to technical complexity and unclear interdependencies between systems.\nWhat should the project manager do?","exp":"B. Engage cybersecurity and systems integration subject matter experts to help surface unknowns and define interdependencies.\n\nExplanation: When complexity creates knowledge gaps during planning, SMEs are the appropriate resource. They bring domain knowledge the team lacks, help identify what is not yet understood, and inform scope and dependency definition from a position of technical expertise that the project team alone does not have.\n\nWhy the other options are incorrect:\n\nAdding schedule buffer is a reactive planning adjustment that treats uncertainty as inevitable without attempting to reduce it. Understanding the interdependencies first would produce a more accurate schedule than padding an uncertain one.\n\nAn external PM consultant helps with process and governance but does not bring the technical domain knowledge needed to resolve questions about legacy system integration and security protocols.\n\nA stakeholder survey captures requirements input from a user perspective but does not address the technical complexity the team is facing. Stakeholders typically cannot define system interdependencies at the level of detail the planning effort requires.","ans":"B","hint":""},{"n":73,"opts":{"A":"Prioritize compliance efforts based on each area’s regulatory significance and potential impact on trial approval.","B":"Categorize all compliance requirements by the specific fines and penalties associated with each violation.","C":"Hold a compliance workshop with the regulatory affairs team and external auditors to share knowledge about past violations.","D":"Direct the majority of the compliance budget toward patient safety protocols since they carry the highest penalties."},"q":"A pharmaceutical company is conducting a clinical trial spanning multiple regulatory domains including patient safety protocols, data integrity standards, and environmental disposal requirements. The project manager must allocate the compliance budget across all areas. The regulatory affairs team warns that any single compliance failure could jeopardize trial approval.\nWhat should the project manager do?","exp":"A. Prioritize compliance efforts based on each area’s regulatory significance and potential impact on trial approval.\n\nExplanation: Effective compliance resource allocation requires evaluating each area’s significance and its potential consequences for the project as a whole. Penalty amounts are one signal but do not capture operational risk, reputational impact, or cascading effects on approval. A proportional, impact-based prioritization ensures all compliance domains receive appropriate attention.\n\nWhy the other options are incorrect:\n\nCategorizing by penalties alone provides a narrow financial lens. A requirement with lower penalties may carry higher operational risk or approval implications that make it equally critical to resource adequately.\n\nA compliance workshop builds shared knowledge and is a useful input, but it does not constitute a resource allocation strategy. Knowledge gathering informs prioritization; it does not replace it.\n\nDirecting the majority of the budget toward the highest-penalty area ignores the regulatory affairs team’s warning that any single failure could jeopardize approval applies across all domains, not just the one with the largest fines.","ans":"A","hint":""},{"n":74,"opts":{"A":"Develop the comprehensive risk management plan as requested to demonstrate governance discipline.","B":"Create a detailed risk register documenting all possible risks regardless of the project’s scale.","C":"Request additional time and resources to properly prepare the documentation the department head has requested.","D":"Explain to the department head that the project’s scale does not warrant a formal risk plan and propose a simplified approach."},"q":"A project manager is leading a two-week internal process documentation effort for a department of six employees. The initiative has no external dependencies, no budget, and no identifiable risks beyond minor scheduling conflicts. The department head requests a full risk management plan with probability matrices, risk owners, and formal response strategies.\nWhat should the project manager do?","exp":"D. Explain to the department head that the project’s scale does not warrant a formal risk plan and propose a simplified approach.\n\nExplanation: Risk management should be tailored to the project’s size, complexity, and risk profile A two-week internal effort with minimal risk does not justify a fully formal risk management plan. The right response is not to ignore risk, but to use a proportionate, lightweight approach.\n\nWhy the other options are incorrect:\n\nDeveloping the plan as requested treats compliance as more important than project efficiency. Applying comprehensive governance to a minimal-risk initiative consumes resources without producing proportional value.\n\nCreating a detailed risk register regardless of scale has the same problem. Documentation should match the project’s actual risk exposure, not a universal standard applied uniformly.\n\nRequesting additional time and resources compounds the issue by seeking to expand the project’s footprint to accommodate an unnecessary requirement rather than addressing whether the requirement is appropriate in the first place.","ans":"D","hint":""},{"n":75,"opts":{"A":"Ask the project sponsor to reinforce the organization’s sustainability commitments to the resistant department heads.","B":"Present data showing reduced operating costs, regulatory risk reduction, and long-term return on investment for the energy-efficient systems.","C":"Schedule a mandatory sustainability workshop for all department heads to build awareness of the organization’s environmental goals.","D":"Review the project charter and business case to identify the sustainability requirements that have already been formally approved."},"q":"A project manager is overseeing the development of a new office facility. The design team proposes incorporating energy-efficient systems including solar panels, smart climate controls, and sustainable building materials. Several department heads are pushing back, arguing the upfront costs are too high and the budget should be allocated elsewhere.\nWhat should the project manager do?","exp":"B. Present data showing reduced operating costs, regulatory risk reduction, and long-term return on investment for the energy-efficient systems.\n\nExplanation: The department heads’ concern is financial. The most direct and effective response is to address that concern on its own terms by demonstrating that the upfront cost is offset by measurable long-term value. This engages with the actual objection rather than asserting authority, mandating attendance, or retreating to documentation.\n\nWhy the other options are incorrect:\n\nAsking the sponsor to reinforce sustainability commitments escalates a stakeholder alignment issue the project manager can address directly. Involving the sponsor before attempting direct engagement bypasses the PM’s own responsibility to align stakeholder expectations.\n\nA mandatory workshop addresses awareness broadly but does not engage with the specific financial objection the department heads raised. Awareness of environmental goals does not resolve a concern about budget allocation.\n\nReviewing the charter and business case, while useful for validation, does not address why the department heads are resistant. Confirming the requirement exists does not persuade skeptical stakeholders to support it.","ans":"B","hint":""},{"n":76,"opts":{"A":"Conduct daily stand-up meetings to keep all team members aligned","B":"Create informal group communication channels to enable rapid information sharing across all teams.","C":"Use AI translation tools to automatically convert all project communications into each team member’s primary language.","D":"Provide project updates in multiple languages and schedule structured virtual sessions that accommodate different time zones to collect input from all teams."},"q":"A project manager is leading an international research partnership involving teams from six countries across four time zones. Team members speak five different primary languages, and varying levels of English proficiency have caused miscommunication in early project meetings.\nWhat should the project manager do?","exp":"D. Provide project updates in multiple languages and schedule structured virtual sessions that accommodate different time zones to collect input from all teams.\n\nExplanation: Inclusive communication for a global team requires addressing both barriers the scenario identifies: language and geography. Multilingual updates ensure content is accessible to all participants. Structured virtual sessions scheduled around time zone differences ensure every team has a meaningful opportunity to engage and provide input rather than being systematically excluded by scheduling or language.\n\nWhy the other options are incorrect:\n\nDaily synchronous meetings across four time zones force some participants into unreasonable hours and are not a sustainable or inclusive approach. Consistent real-time collaboration is not achievable across significant time zone gaps.\n\nInformal channels supplement communication but do not constitute an inclusive strategy. Group chats do not address language barriers, do not ensure structured input collection, and favor participants who are more comfortable with informal written communication.\n\nAI translation addresses language accessibility partially but replaces structured human engagement with automation. Translation quality varies across languages and does not guarantee accurate communication of nuanced project content, nor does it create the structured forums needed for genuine input collection.","ans":"D","hint":""},{"n":77,"opts":{"A":"Hold weekly status meetings with contractors to communicate brand standards and collect feedback on progress.","B":"Schedule regular check-ins with the hotel’s CEO to ensure executive alignment and facilitate high-level decision-making.","C":"Regularly compare design decisions, contractor outputs, and deliverables against the brand vision and standards documented during project initiation.","D":"Update the project charter whenever design preferences evolve to ensure documentation reflects the current brand direction."},"q":"A luxury hospitality brand is renovating its flagship hotel to reinforce its identity as a premium, heritage-focused destination. The renovation involves design decisions, contractor selections, and material choices across an 18-month project. The project manager must ensure all decisions and deliverables consistently reflect the brand identity throughout delivery.\nWhat should the project manager do?","exp":"C. Regularly compare design decisions, contractor outputs, and deliverables against the brand vision and standards documented during project initiation.\n\nExplanation: The vision statement and standards established during initiation are the authoritative reference for what the project is trying to achieve. Systematically comparing progress and deliverables against those documents is the mechanism that ensures ongoing alignment throughout delivery, not ad hoc communication or executive governance alone.\n\nWhy the other options are incorrect:\n\nWeekly meetings with contractors communicate expectations but do not constitute a systematic check against the documented vision. Communication can drift from the standard without a structured comparison process in place.\n\nCEO check-ins support executive governance and high-level decision-making but are not designed to evaluate individual design decisions and deliverables against the documented brand vision at a working level.\n\nThe project charter is created during initiation to authorize the project. Updating it whenever preferences shift misuses the document and undermines the stable baseline it is meant to provide.","ans":"C","hint":""},{"n":78,"opts":{"A":"Grant all stakeholders access to the raw defect logs and cost data so each can analyze what they need independently.","B":"Simplify all reports to high-level summaries and provide raw data only upon formal request.","C":"Develop separate reports tailored to each stakeholder’s stated information needs.","D":"Explain that raw project data is processed into analyzed information and formatted into reports tailored to each stakeholder’s role and information needs."},"q":"During a monthly status review, a project manager faces three conflicting stakeholder requests. The technical lead wants access to raw defect logs and test results to conduct their own analysis. The project sponsor finds the current reports too dense and asks for simpler executive summaries. The procurement lead needs detailed cost breakdown data.\nWhat should the project manager do?","exp":"C. Develop separate reports tailored to each stakeholder’s stated information needs.\n\nExplanation: Each stakeholder has clearly expressed a different information requirement. The appropriate response is to act on those stated needs by producing tailored outputs for each audience. Effective communication management means delivering the right information in the right format to the right person, not applying a uniform approach across a group with demonstrably different needs.\n\nWhy the other options are incorrect:\n\nProviding raw data to all stakeholders bypasses the PM’s responsibility to process and present information appropriately. Raw logs and figures without context are not suitable for the sponsor or procurement lead.\n\nSimplifying everything to high-level summaries addresses the sponsor’s concern while failing the technical lead and procurement lead who require more detailed information.\n\nExplaining the data processing hierarchy is educational but does not address the immediate problem. The stakeholders have not asked how data is managed; they have stated what they need, and the PM should act on that.","ans":"C","hint":""},{"n":79,"opts":{"A":"Engage subject matter experts to analyze the inconsistent outputs and help identify their source.","B":"Verify that the team followed proper configuration management procedures during development.","C":"Commission a rebuild of the affected components using a more experienced development team.","D":"Survey end users to gather their observations about the inconsistent outputs."},"q":"A project manager is overseeing the deployment of a new customer data platform. During user acceptance testing, the system produces inconsistent outputs that do not match expected results. The development team confirms they followed the technical specifications throughout the build. The project deadline is approaching and the sponsor is asking for answers.\nWhat should the project manager do?","exp":"A. Engage subject matter experts to analyze the inconsistent outputs and help identify their source.\n\nExplanation: The team has confirmed they followed the specifications, which means the root cause is not a process compliance failure. When the source of a technical problem is unknown and internal expertise has been exhausted, SMEs bring the specialized knowledge needed to diagnose what the team cannot. Deadline pressure does not change the diagnostic approach required.\n\nWhy the other options are incorrect:\n\nVerifying configuration management is a reasonable general practice but does not move the investigation forward when the team has already confirmed they followed the technical specifications.\n\nRebuilding with a more experienced team is a disproportionate response to an undiagnosed problem. Replacing people before understanding the cause does not guarantee the same error will not occur again.\n\nEnd users can describe what they observe but cannot diagnose the technical root cause of inconsistent system outputs. The investigation requires technical domain expertise, not stakeholder symptom reporting.","ans":"A","hint":""},{"n":80,"opts":{"A":"Wait until project execution before discussing sustainability requirements.","B":"Exclude sustainability because it was not specifically requested by the sponsor.","C":"Recommend incorporating sustainability objectives into the project’s planning documents and discussing them with stakeholders.","D":"Focus only on delivering the approved scope because sustainability is outside the project manager’s responsibility."},"q":"A project manager is developing the charter for a municipal park renovation. The sponsor has not mentioned sustainability requirements, but the organization has a strong environmental policy that applies to all capital projects.\nWhat should the project manager do?","exp":"C. Recommend incorporating sustainability objectives into the project’s planning documents and discussing them with stakeholders.\n\nExplanation: Sustainability should be considered from initiation through project closure and incorporated into key project documents whenever appropriate.\n\nWhy the other options are incorrect:\n\nWaiting until execution makes sustainability more difficult to integrate.\n\nSponsor omission does not eliminate organizational sustainability expectations.\n\nSustainability is part of responsible project management.","ans":"C","hint":""},{"n":81,"opts":{"A":"Review the final deliverables from the earlier phases to understand what was built.","B":"Review the program’s documentation repository including phase reports, decision logs, and retrospectives.","C":"Arrange meetings with team members who worked on the earlier phases to discuss their experiences directly.","D":"Analyze the differences between the original program plan and what was actually delivered in each phase."},"q":"A project manager is leading the third phase of a long-running infrastructure modernization program. Most of the current team joined recently and was not involved in the first two phases. Several significant architectural decisions were made during earlier phases that will affect current planning.\nWhat should the project team do first?","exp":"B. Review the program’s documentation repository including phase reports, decision logs, and retrospectives.\n\nExplanation: The organization’s documented knowledge assets are the primary resource for understanding what happened in earlier phases and why. Phase reports, decision logs, and retrospectives capture the reasoning behind architectural decisions in a form that is structured, complete, and accessible without depending on the availability of previous team members.\n\nWhy the other options are incorrect:\n\nReviewing final deliverables shows what was built but not the reasoning, trade-offs, or lessons that shaped those decisions. The documentation provides that context.\n\nArranging meetings with previous team members is a useful supplement but should come after reviewing the available documentation. Previous members may not be available, and their recollections are secondary to formal records.\n\nAnalyzing plan versus actuals is a narrow comparison that does not access the full range of decisions, process improvements, and lessons captured in the program’s knowledge base.","ans":"B","hint":""},{"n":82,"opts":{"A":"Assign experienced technical writers who can produce the same reports in fewer hours.","B":"Assign additional technical writers to distribute the work across a larger team.","C":"Break the reports into smaller sections to produce a more accurate estimate.","D":"Implement document automation tools to handle formatting and templating tasks."},"q":"A project manager is estimating the effort required to develop a series of technical reports for a regulatory submission. Using a parametric model based on report complexity and resource hours per page, the initial estimate exceeds the available budget. The scope cannot be reduced and the deadline is fixed.\nWhat should the project manager do to reduce the effort estimate?","exp":"A. Assign more experienced technical writers who can produce the same reports in fewer hours.\n\nExplanation: In parametric estimation, effort equals work volume divided by productivity rate. Because the stem says the parametric model is based on report complexity and resource hours per page, the adjustable driver named in the estimate is essentially labor productivity. More experienced writers producing the same reports in fewer hours directly changes the hours-perpage parameter.\n\nWhy the other options are incorrect:\n\nAdding more technical writers distributes the workload but does not reduce the total hours required. Coordination overhead may actually increase the estimate.\n\nBreaking the reports into smaller sections improves the precision of the estimate but does not change the total hours the work requires.\n\nDocument automation tools could reduce certain tasks but introduce their own implementation effort and are a broader solution than adjusting a resource parameter in an existing model.","ans":"A","hint":""},{"n":83,"opts":{"A":"The project has well-defined technical specifications the team can implement in a structured sequence.","B":"The project deliverables will be consistent and repeatable, making iteration straightforward to plan.","C":"Customer preferences are unknown and will only emerge through continuous testing and feedback, requiring the team to adapt based on what is learned.","D":"The project requires strict cost and schedule controls that an adaptive framework is designed to enforce."},"q":"A project manager is leading a product innovation initiative at a consumer electronics company. The project involves developing a new product category where customer preferences are unclear and will only emerge through user testing and market feedback. The project manager recommends an adaptive approach. A senior executive challenges the recommendation and asks for justification.\nWhat should the project manager emphasize?","exp":"C. Customer preferences are unknown and will only emerge through continuous testing and feedback, requiring the team to adapt based on what is learned.\n\nExplanation: Adaptive approaches are designed for contexts where requirements cannot be fully defined upfront and must emerge through iteration and feedback. When what the customer actually wants is unknown at the outset, building and testing incrementally is more effective than committing to a fixed plan based on assumptions.\n\nWhy the other options are incorrect:\n\nWell-defined technical specifications that can be implemented in a structured sequence describe a predictive context, not a justification for adaptive.\n\nConsistent and repeatable deliverables are also a characteristic of predictive work, where the output is well-understood enough to plan in detail upfront.\n\nStrict cost and schedule controls are features of predictive project management. Framing adaptive as a tool for tight financial control misrepresents what the approach is designed to do.","ans":"C","hint":""},{"n":84,"opts":{"A":"Begin rework immediately as the sponsor requests to maintain the client relationship and avoid the penalty.","B":"Facilitate a session with the client and development team to clarify the undocumented calculation rules and formally update the scope documentation.","C":"Escalate the dispute to the program manager since the disagreement between the client and development team is beyond the project manager’s authority.","D":"Ask the project sponsor to negotiate directly with the client on the disputed calculation rules to resolve the issue at the executive level."},"q":"A software development team completes a billing module that passes all defined functional tests. The client refuses to accept it, stating that several calculation rules specific to their industry were never documented but were assumed to be standard practice. The project sponsor urges the project manager to begin rework immediately to avoid a contract penalty. The development team argues the module was built exactly as specified.\nWhat should the project manager do?","exp":"B. Facilitate a session with the client and development team to clarify the undocumented calculation rules and formally update the scope documentation.\n\nExplanation: The root issue is that requirements were never documented, creating a gap between what the client expected and what was specified. Before any rework begins, the PM must facilitate clarification of what the actual requirements are and formally update the scope documentation. Acting without that clarification risks performing rework that still does not satisfy the client and leaves the governance gap the PMO warned about.\n\nWhy the other options are incorrect:\n\nBeginning rework without first clarifying the requirements means the team may fix the wrong things. It also bypasses the formal change control process, compounding rather than resolving the governance gap.\n\nEscalating to the program manager is premature. Facilitating a clarification session between the client and development team is squarely within the project manager’s role and authority.\n\nSending the sponsor to negotiate bypasses the PM’s facilitation responsibility and does not address the documentation issue that caused the rejection in the first place.","ans":"B","hint":""},{"n":85,"opts":{"A":"Continue tracking trade publications and news sources for further developments on the proposed restrictions.","B":"Contact the supplier directly to request advance warning if the export restrictions are approved.","C":"Monitor container inventory levels and alert stakeholders if stock falls below safety thresholds.","D":"Review the risk management plan for this risk and report to stakeholders if conditions indicate the risk is escalating."},"q":"A pharmaceutical logistics company relies on cold-chain containers imported from a single foreign supplier. A recent industry report indicates the supplier’s government is reviewing a proposal to restrict certain exports. The project manager has been assigned to monitor this situation as a potential risk to the supply chain.\nWhat should the project manager do?","exp":"D. Review the risk management plan for this risk and report to stakeholders if conditions indicate the risk is escalating.\n\nExplanation: The industry report represents a trigger worth tracking. When a risk has been formally identified and a PM has been assigned to monitor it, the correct response is to follow the risk management plan, which defines escalation thresholds and what conditions require stakeholder notification.\n\nWhy the other options are incorrect:\n\nFollowing trade publications is how the PM learned of the development, but it is an informal supplement to structured monitoring. The risk management plan defines what to watch for and when to act.\n\nContacting the supplier directly goes beyond the monitoring role the PM was assigned. Initiating supplier conversations is a response action that may be appropriate later but is not what monitoring requires at this stage.\n\nMonitoring inventory levels tracks the downstream impact of a potential supply disruption rather than the risk triggers defined in the plan. The assigned task is to monitor whether the external restriction is escalating, not to manage stock levels.","ans":"D","hint":""},{"n":86,"opts":{"A":"Follow the project sponsor’s direction and classify the costs in the way that secures the fastest budget approval.","B":"Work with the IT director, operations director, and controller to classify costs according to applicable accounting standards.","C":"Divide the costs between capital and operational categories to give each director partial satisfaction.","D":"Defer the classification decision until later in the project when actual costs are more clearly defined."},"q":"A technology company is implementing a new enterprise software system. The IT director argues the implementation costs should be capitalized as a long-term asset. The operations director wants them treated as operational expenses for an immediate tax deduction. The project sponsor asks the project manager to classify the costs however will secure budget approval most quickly. The company’s controller warns that improper classification could trigger a regulatory audit.\nWhat should the project manager do?","exp":"B. Work with the IT director, operations director, and controller to classify costs according to applicable accounting standards.\n\nExplanation: Cost classification is governed by accounting standards, not stakeholder preferences or approval timelines. The controller has identified a genuine compliance risk. The PM’s role is to bring the right people together and ensure the decision is grounded in the applicable standards, not to find a politically convenient resolution.\n\nWhy the other options are incorrect:\n\nFollowing the sponsor’s direction to prioritize speed treats classification as a stakeholder preference rather than a compliance requirement. Improper classification for administrative convenience is an ethical and regulatory violation regardless of who directs it.\n\nSplitting costs arbitrarily between categories to satisfy both directors produces the same misclassification risk the controller warned about. The correct classification is not a negotiated compromise.\n\nDeferring the decision avoids the conflict without resolving it and delays financial reporting that other project planning depends on.","ans":"B","hint":""},{"n":87,"opts":{"A":"Revise the project budget baseline to accommodate the higher material costs for this component.","B":"Reduce the scope of the component to bring material consumption back within the original allocation.","C":"Schedule a meeting with the component team to ask why material costs are higher than planned.","D":"Analyze the situation to identify the root cause of the overconsumption before deciding on corrective action."},"q":"A manufacturing project has been consistently meeting its weekly milestones. During a status review, the project manager discovers that one production component is consuming twice its allocated materials. The project is otherwise on track and no team member has raised concerns about this component.\nWhat should the project manager do first?","exp":"D. Analyze the situation to identify the root cause of the overconsumption before deciding on corrective action.\n\nExplanation: The cause of the overconsumption is unknown. Acting before understanding the cause risks applying the wrong fix. Root cause analysis first ensures that whatever corrective action is taken addresses the actual problem rather than its symptoms.\n\nWhy the other options are incorrect:\n\nRevising the budget baseline accepts the higher cost without understanding whether it is avoidable. If the root cause is a process error or supplier issue, absorption is the wrong response.\n\nReducing scope applies a solution before the cause is understood. The excess consumption may have nothing to do with scope and reducing it may not resolve the underlying issue.\n\nAsking the team is a reasonable step within a broader investigation but is a single channel that may miss systemic or external causes. Root cause analysis may require examining processes, materials, supplier quality, and design specifications beyond what the team can directly explain.","ans":"D","hint":""},{"n":88,"opts":{"A":"Meet separately with each developer to understand their technical reasoning before holding any joint discussion.","B":"Research the merits of each framework and present a recommendation to break the deadlock.","C":"Bring both developers together to work through the trade-offs and reach a mutually acceptable decision.","D":"Add the framework decision to the next sprint retrospective with the full team."},"q":"Two developers on a mobile app project disagree about whether to build using a native or cross-platform framework. The disagreement has delayed sprint planning in each of the last two sprints and is creating tension within the team. No resolution has emerged despite both developers having discussed their positions informally.\nWhat should the project manager do?","exp":"C. Bring both developers together to work through the trade-offs and reach a mutually acceptable decision.\n\nExplanation: The conflict has persisted across two sprints and informal discussion has not resolved it. The confronting/problem-solving approach brings the parties together in a structured setting where both perspectives are heard and a joint decision can be reached. This is more effective than further individual conversations or deferring a decision that is actively blocking sprint planning.\n\nWhy the other options are incorrect:\n\nIndividual meetings help the PM understand each position but do not create the conditions for joint resolution. Both developers already know each other’s views and the conflict remains technical, not personal; what is needed is a facilitated space to work through them together.\n\nThe PM presenting a technical recommendation removes ownership from the people best positioned to make the decision and may produce a solution neither developer is committed to implementing.\n\nAdding the decision to the retrospective sounds agile-appropriate but treats a blocking conflict as a process improvement item. The conflict has already delayed two sprints; scheduling it for future discussion without a structured resolution mechanism is another form of deferral.","ans":"C","hint":""},{"n":89,"opts":{"A":"Evaluate the IT department’s current capacity and expertise against the project’s specific requirements.","B":"Engage an external staffing agency to identify specialists with healthcare data architecture experience.","C":"Create a detailed resource plan listing all technical roles, required skills, and estimated hours.","D":"Propose a hybrid staffing model that combines internal staff with external contractors to satisfy both stakeholders."},"q":"A healthcare network is launching a digital health records initiative requiring specialized data architecture and clinical informatics expertise. The CIO believes the IT department has sufficient talent internally. The HR director recommends hiring external specialists. The project has a sixmonth timeline.\nWhat should the project manager do first?","exp":"A. Evaluate the IT department’s current capacity and expertise against the project’s specific requirements.\n\nExplanation: The disagreement between the CIO and HR director is about resource strategy, but neither position is grounded in a factual assessment of what the project requires versus what the organization already has. That assessment must come first. It determines whether internal resources are sufficient, whether external hiring is necessary, or whether a hybrid approach makes sense.\n\nWhy the other options are incorrect:\n\nEngaging an external agency assumes the conclusion before the assessment. If the IT department has sufficient capacity, external recruitment wastes time and budget on a compressed timeline.\n\nCreating a detailed resource plan before assessing current capacity produces a plan built on assumptions. The plan should reflect what is actually available and what gaps need to be filled.\n\nProposing a hybrid model as a political compromise satisfies both stakeholders superficially but may not reflect what the project actually needs. The staffing decision should follow from the assessment, not from stakeholder preferences.","ans":"A","hint":""},{"n":90,"opts":{"A":"Organize an SME workshop to gather institutional knowledge about data processing architectures and identify potential solutions.","B":"Authorize a timeboxed technical spike to investigate potential architectural solutions and assess their feasibility before committing to a fix.","C":"Submit a change request to extend the sprint and adjust the prototype timeline to accommodate the technical investigation.","D":"Perform a comprehensive feasibility study of all available data processing architectures to identify the optimal solution."},"q":"A development team building a real-time data processing system discovers during a sprint that the existing integration architecture cannot handle the required throughput without significant latency. No existing documentation or prior project records address this specific constraint. The product owner must demonstrate a working prototype to investors in three weeks.\nWhat should the project manager do?","exp":"B. Authorize a timeboxed technical spike to investigate potential architectural solutions and assess their feasibility before committing to a fix.\n\nExplanation: A technical spike is designed precisely for this situation: a technical unknown that blocks progress and cannot be resolved through existing documentation. It produces actionable findings within a defined time window, which preserves schedule pressure while creating the investigation needed to move forward. The team has already exhausted passive knowledge sources; active hands-on investigation is the next step.\n\nWhy the other options are incorrect:\n\nAn SME workshop focused on knowledge capture is appropriate when tacit knowledge needs to be surfaced and shared. Here the need is active technical investigation, not knowledge gathering, and the knowledge repositories have already been reviewed without usable results.\n\nSubmitting a change request to extend the timeline concedes the schedule before any targeted investigation has been attempted. A spike may resolve the constraint without requiring a timeline change.\n\nA comprehensive feasibility study is too heavy for a three-week investor deadline. It over-analyzes when a focused timeboxed experiment is more appropriate.","ans":"B","hint":""},{"n":91,"opts":{"A":"Ensure all team members have access to and training on the collaboration platforms needed to work effectively as a distributed team.","B":"Limit the team to candidates in the same region to reduce the performance risks of geographic dispersion.","C":"Request a budget exception from the sponsor to fund periodic in-person meetings for the distributed team.","D":"Restructure the work packages so each can be completed independently by a single geographic location."},"q":"A project manager is staffing a complex software integration project. The most qualified candidates are located across three continents. The project budget does not accommodate travel or relocation costs and the project sponsor has confirmed the budget is fixed.\nWhat should the project manager do?","exp":"A. Ensure all team members have access to and training on the collaboration platforms needed to work effectively as a distributed team.\n\nExplanation: When colocation is financially unavailable, effective virtual collaboration is the practical solution. Ensuring the team has the right tools and the skills to use them addresses the core challenge of geographic dispersion without compromising on talent or restructuring the project around a constraint.\n\nWhy the other options are incorrect:\n\nRestricting candidates to the same region sacrifices team quality to avoid managing a distributed team. The right response to geographic dispersion is effective virtual collaboration, not limiting the talent pool.\n\nRequesting a budget exception treats a fixed constraint as negotiable. The sponsor has confirmed the budget is fixed, making exception requests an inappropriate next step.\n\nRestructuring work packages to geographic silos may not align with a complex integration project’s dependencies and technical requirements, and may fragment work that needs close coordination.","ans":"A","hint":""},{"n":92,"opts":{"A":"Approve sign-off immediately to secure the milestone payment and schedule a follow-up meeting to address the client’s concerns.","B":"Reject the client’s request since the module was delivered in accordance with the approved specifications.","C":"Facilitate a review of the acceptance criteria with the client and process a change request if the reporting format was not captured in the original scope.","D":"Reassign the development team to rework the reporting module immediately to resolve the client’s concerns."},"q":"A software vendor has delivered the final phase of a customer relationship management system. The client’s operations team rejects the reporting module, stating it does not display regional sales data in their required format. The project sponsor wants immediate sign-off to trigger the milestone payment. The QA team confirms the module meets the originally approved specifications. The account manager warns that client dissatisfaction at this stage could affect contract renewal.\nWhat should the project manager do?","exp":"C. Facilitate a review of the acceptance criteria with the client and process a change request if the reporting format was not captured in the original scope.\n\nExplanation: Whether the client’s requirement was in scope must be determined before any action is taken. A structured acceptance criteria review establishes that basis. The decision should follow from process rather than financial pressure or reflexive rejection.\n\nWhy the other options are incorrect:\n\nSigning off to release payment while deferring the client’s concern secures short-term revenue but leaves a dispute unresolved at close, increasing claims and reputational risk.\n\nRejecting the client’s request based on specification compliance dismisses a legitimate concern without confirming whether the requirement was ever properly documented.\n\nAuthorizing immediate rework bypasses change control, assumes the additional work is justified before any review has been conducted, and puts the team under unnecessary pressure.","ans":"C","hint":""},{"n":93,"opts":{"A":"Transfer all campaign materials, data, and contact lists to the operations team for ongoing use.","B":"Document the effective outreach methods, challenges, and communication channel performance in a lessons learned register.","C":"Present a final campaign report to city council highlighting successes and areas for improvement.","D":"Archive all project documentation in the city’s information management system for compliance purposes."},"q":"A city government is concluding a 12-month community engagement initiative. The team collected extensive data on which outreach methods were most effective, which neighborhoods were hardest to reach, and which communication channels produced the best response rates. The project coordinator wants to ensure this knowledge benefits future community programs.\nWhat should the project team prioritize?","exp":"B. Document the effective outreach methods, challenges, and communication channel performance in a lessons learned register for future programs.\n\nExplanation: The lessons learned register is the artifact designed to capture analytical knowledge about what worked, what did not, and why. It translates project experience into reusable organizational knowledge that future programs can apply. The other activities serve different purposes at closure but do not fulfill this specific need.\n\nWhy the other options are incorrect:\n\nTransferring materials to the operations team supports continuity but does not capture the analytical insights about effectiveness that make future programs better.\n\nA council presentation communicates outcomes to a governance audience but is a reporting activity, not a mechanism for preserving operational knowledge for future project teams.\n\nArchiving documentation preserves records for compliance and reference but does not synthesize the campaign’s insights into a format designed for organizational learning.","ans":"B","hint":""},{"n":94,"opts":{"A":"Develop a vision statement that articulates the product’s objectives and what differentiates it from competing offerings.","B":"Build an early prototype to demonstrate the product concept and generate team alignment around the design direction.","C":"Schedule sessions with the executive team to confirm product strategy before sharing it with the broader team.","D":"Establish a cross-functional working group to give all team members equal input into defining project goals."},"q":"A startup is launching a smart home security product in a saturated market. The project team includes hardware engineers, software developers, marketing specialists, and industrial designers. The project manager needs to ensure all team members understand both the product’s objectives and what distinguishes it from competing offerings.\nWhat should the project manager do?","exp":"A. Develop a vision statement that articulates the product’s objectives and what differentiates it from competing offerings.\n\nExplanation: A vision statement gives all stakeholders a single, clear articulation of what the project is trying to achieve and why the product is positioned differently in the market. With a diverse team spanning hardware, software, marketing, and design, a shared vision statement ensures everyone is working toward the same goal regardless of their functional area.\n\nWhy the other options are incorrect:\n\nA prototype demonstrates a design concept but does not articulate the shared purpose and market differentiation that all team members need to understand from the outset.\n\nExecutive alignment sessions ensure leadership is aligned but do not communicate the vision to the engineers, developers, and designers who need to internalize it to do their work effectively.\n\nA cross-functional working group encourages collaboration, but equal input into goals is not the same as establishing a clear product vision.","ans":"A","hint":""},{"n":95,"opts":{"A":"Research governance standards published by pharmaceutical regulatory bodies.","B":"Review academic literature on governance best practices in regulated industries.","C":"Review governance frameworks, policies, and templates used in previous drug development programs.","D":"Evaluate project management software platforms that can support governance tracking and reporting."},"q":"A project manager at a pharmaceutical company is developing a governance framework for a new drug development program. Before building new governance structures, the project manager wants to leverage whatever existing guidance is available within the organization.\nWhat should the project manager do first?","exp":"C. Review governance frameworks, policies, and templates used in previous drug development programs.\n\nExplanation: Organizational process assets from similar past programs are the most directly applicable starting point. They contain governance structures, policies, and templates the organization has already developed and refined, saving time and ensuring the new framework is grounded in proven internal practice.\n\nWhy the other options are incorrect:\n\nRegulatory body standards are enterprise environmental factors; external inputs. The question specifically asks for “existing guidance available within the organization.”\n\nAcademic literature provides external best practices but is not the existing organizational guidance the project manager is looking to leverage first.\n\nProject management software supports governance execution but is an implementation tool, not a source of governance framework content.","ans":"C","hint":""},{"n":96,"opts":{"A":"Verify that the AI-generated material complies with copyright, licensing, and ownership requirements before using it.","B":"Replace the AI-generated material with information from previous company proposals.","C":"Submit the proposal because AI-generated work is not protected by copyright.","D":"Remove any references indicating AI was used to create the proposal."},"q":"A project team uses an AI application to prepare sections of a proposal for a government contract. Before submission, one team member mentions that some of the AI-generated material appears very similar to content published by another consulting firm.\nWhat should the project manager do?","exp":"A. Verify that the AI-generated material complies with copyright, licensing, and ownership requirements before using it.\n\nExplanation: AI-generated content may create copyright and ownership concerns. The project manager should ensure the material can legally be used before incorporating it into project deliverables.\n\nWhy the other options are incorrect:\n\nPrevious proposals may contain similar intellectual property restrictions.\n\nAI-generated material is not automatically exempt from copyright concerns.\n\nRemoving references does not resolve potential intellectual property violations.","ans":"A","hint":""},{"n":97,"opts":{"A":"Analyze the cost variances to identify the root cause before communicating with the client.","B":"Submit a change request through governance to revise the budget baseline to reflect current spending.","C":"Meet with the client’s operations director to acknowledge the stated concerns.","D":"Update the risk register with the cost overrun and schedule concern as newly identified risks."},"q":"A project manager is overseeing a custom ERP implementation. Midway through the timeline, a financial review shows costs are 18% above the approved baseline. The client’s operations director has sent a message noting delays in deliverable reviews and questioning whether the implementation is on track.\nWhat should the project manager do first?","exp":"C. Meet with the client’s operations director to acknowledge the stated concerns.\n\nExplanation: The first priority is stakeholder engagement and communication because the client has already raised an active concern. A project manager should address stakeholder issues promptly, then investigate the variance, determine corrective action, and update formal records and the stakeholder as needed.\n\nWhy the other options are incorrect:\n\nCompleting cost analysis is necessary, but it follows the initial acknowledgment. Completing a full analysis before even acknowledging the client’s concerns delays a response that is needed immediately.\n\nSubmitting a change request to increase the budget baseline treats the overrun as settled before understanding its cause or involving the client in the conversation.\n\nUpdating the risk register is an internal action that does nothing to address the client relationship or the concerns they have already communicated.","ans":"C","hint":""},{"n":98,"opts":{"A":"Accept the recommendation because meeting the contractual date is the project’s highest priority.","B":"Submit the recommendation to the sponsor for immediate approval.","C":"Review the recommendation to ensure quality and safety requirements continue to be satisfied before changing the schedule.","D":"Ask the quality manager to determine whether the inspections are still necessary."},"q":"A project manager is using an AI scheduling application to evaluate options for recovering a delayed project. One recommendation eliminates several quality inspections and shortens testing activities, allowing the project to meet its contractual completion date.\nWhat should the project manager do?","exp":"C. Review the recommendation to ensure quality and safety requirements continue to be satisfied before changing the schedule.\n\nExplanation: AI should not be used to bypass quality or safety requirements. The project manager must verify that recommendations continue to satisfy project standards before implementation.\n\nWhy the other options are incorrect:\n\nMeeting the schedule does not justify compromising quality or safety.\n\nSponsor approval does not replace technical evaluation of the recommendation.\n\nThe quality manager provides valuable input, but the project manager remains responsible for evaluating AI-supported project decisions.","ans":"C","hint":""},{"n":99,"opts":{"A":"Develop a comprehensive risk assessment framework to evaluate all potential risks and their likelihood.","B":"Interview team members who worked on the previous migration to understand what went wrong.","C":"Create a risk matrix that maps current migration requirements to deliverables to identify potential failure points.","D":"Review records and documentation from the previous migration to identify the patterns and root causes that led to the data integrity issues."},"q":"A regional healthcare network is launching a new patient data migration project. A similar migration two years ago produced significant data integrity issues and patient record errors. Leadership has directed the project manager to ensure these problems do not recur.\nWhat should the project manager do?","exp":"D. Review records and documentation from the previous migration to identify the patterns and root causes that led to the data integrity issues.\n\nExplanation: Historical records from the previous project are the most structured and reliable source for understanding what went wrong and why. Reviewing that documentation surfaces root causes and patterns that directly inform risk planning for the current migration, which is the most targeted approach to preventing recurrence.\n\nWhy the other options are incorrect:\n\nA generic risk assessment framework identifies risks broadly but does not specifically leverage the known failure history that makes the current project’s risk profile distinct.\n\nInterviewing previous team members can surface tacit knowledge but is secondary to documented records. Team members may have moved on, recall events differently, or be unavailable.\n\nA risk matrix mapping requirements to deliverables is a planning tool, not a mechanism for learning from prior project failures. It does not connect the current project to the documented causes of past issues.","ans":"D","hint":""},{"n":100,"opts":{"A":"Document the full list of marketing tool features and acceptance criteria in a formal requirements specification.","B":"Facilitate a workshop with the product owner and development team to build the initial product backlog and define acceptance criteria.","C":"Set up a collaboration portal where the marketing team can submit feature requests as they identify them.","D":"Schedule discovery sessions with the marketing team to identify all mandatory features before development begins."},"q":"A project manager is leading the development of a digital marketing tool for an advertising agency transitioning from waterfall to agile delivery. The marketing team has expressed that they want a flexible, iterative approach to defining the tool’s features rather than a comprehensive upfront requirements document.\nWhat should the project manager do first?","exp":"B. Facilitate a workshop with the product owner and development team to build the initial product backlog and define acceptance criteria.\n\nExplanation: In agile, the first meaningful step is usually to create a shared understanding of value with the product owner and team and turn that into an initial backlog. A collaborative workshop does that immediately. It starts iterative discovery in the format agile actually uses: user stories, backlog items, and acceptance criteria.\n\nWhy the other options are incorrect:\n\nA formal requirements specification is not wrong in real life. A project manager might absolutely review workflows and pain points beforehand. But on the PMP exam, that is usually seen as preparatory analysis, not the first action that actually establishes the agile delivery mechanism.\n\nWhile potentially helpful, a portal for submitting feature requests is a passive collection mechanism. It does not establish the core agile structure for defining and prioritizing work.\n\nIdentifying all mandatory features before development begins is still exhaustive upfront requirements gathering, which reflects a predictive mindset regardless of how informally it is framed.","ans":"B","hint":""},{"n":101,"opts":{"A":"Review the stakeholder engagement matrix to compare current engagement levels against planned targets.","B":"Analyze the risk register and issue log to identify documented stakeholder-related concerns.","C":"Conduct interviews or targeted check-ins with key stakeholders to understand their current commitment and any shifts in their priorities.","D":"Update the stakeholder communications plan to ensure outreach frequency and channels remain appropriate."},"q":"A project manager is leading the rollout of a new enterprise resource planning system across multiple business units. Six months in, several business unit leaders who were actively engaged during planning have become less visible. One has missed two consecutive steering committee meetings. The project sponsor asks the project manager to assess whether stakeholder support remains sufficient to proceed.\nHow should the project manager assess current stakeholder engagement?","exp":"C. Conduct interviews or targeted check-ins with key stakeholders to understand their current commitment and any shifts in their priorities.\n\nExplanation: When engagement may have shifted due to external factors, the most reliable way to assess current levels is to go directly to the source. Interviews and targeted check-ins capture what stakeholders are actually experiencing now, not what was planned or previously documented.\n\nWhy the other options are incorrect:\n\nThe question is not asking for the first step or the formal artifact to consult. It is asking how to assess current stakeholder engagement. The stakeholder engagement matrix shows planned and previously recorded engagement levels, but by itself, it does not tell the project manager what stakeholders’ current commitment actually is.\n\nThe risk register and issue log surface formally documented concerns but do not measure current engagement levels. A stakeholder who is quietly disengaging may not yet appear in either document.\n\nUpdating the communications plan is a corrective action, not an assessment. The sponsor asked for an evaluation of current engagement, which requires gathering fresh information before any plan updates are made.","ans":"C","hint":""},{"n":102,"opts":{"A":"Use cost performance data and forecasting to determine whether the project remains within budget tolerance and initiate a change request if reserves are insufficient.","B":"Review the risk breakdown structure to determine whether a budget overrun qualifies as a formal risk requiring a response.","C":"Conduct a sensitivity analysis to identify which remaining project activities pose the greatest cost uncertainty.","D":"Run a Monte Carlo simulation to model the probability distribution of final project costs and reserve adequacy."},"q":"A project manager is overseeing the renovation of a historic government building. The project is 60% complete. The deputy director has raised concerns that recent contractor invoices suggest the project may be trending toward a cost overrun and has asked the project manager to evaluate the current budget position and the state of the contingency reserve.\nHow should the project manager respond?","exp":"A. Use cost performance data and forecasting to determine whether the project remains within budget tolerance and initiate a change request if reserves are insufficient.\n\nExplanation: Cost performance data and forecasting using metrics such as CPI, EAC, and VAC directly address the deputy director’s question by showing current performance against the baseline and projecting the final cost.\n\nWhy the other options are incorrect:\n\nThe risk breakdown structure categorizes risk types but does not evaluate current budget performance or determine whether contingency reserves can absorb the projected overrun.\n\nSensitivity analysis identifies which future activities carry the most cost uncertainty. It is a forward-looking risk prioritization tool, not a mechanism for evaluating current budget position.\n\nMonte Carlo simulation produces a probability distribution of outcomes and is a valid technique for quantitative risk analysis, but it is more sophisticated than required for a standard budget status evaluation and does not directly answer the question of current reserve adequacy.","ans":"A","hint":""},{"n":103,"opts":{"A":"Set SMART objectives tied to defect reduction targets for each development team.","B":"Embed the plan-do-check-act cycle into the development workflow to systematically diagnose, test, verify, and institutionalize process improvements.","C":"Benchmark the team’s defect rates against industry standards to identify where improvement efforts should be focused.","D":"Apply root cause analysis whenever a defect spike occurs to prevent the same problems from recurring."},"q":"A project manager is overseeing a software quality initiative. The operations director has asked the project manager to use six months of defect data to build a systematic approach to improving development processes. The approach must include diagnosing process gaps, piloting fixes, verifying their effectiveness, and making successful changes permanent.\nWhat should the project manager do?","exp":"B. Embed the plan-do-check-act cycle into the development workflow to systematically diagnose, test, verify, and institutionalize process improvements.\n\nExplanation: The four activities the operations director described map directly onto PDCA: diagnosing gaps (Plan), piloting fixes (Do), verifying effectiveness (Check), and making changes permanent (Act). Embedding this cycle into the workflow creates the systematic, repeatable improvement structure the initiative requires.\n\nWhy the other options are incorrect:\n\nSMART objectives create measurable targets but do not address the activities the operations director specified.\n\nBenchmarking identifies performance gaps relative to external standards but does not create the cycle for testing and institutionalizing fixes.\n\nRoot cause analysis is a reactive tool applied when problems occur. It addresses specific incidents rather than embedding a proactive, ongoing improvement culture into the workflow.","ans":"B","hint":""},{"n":104,"opts":{"A":"Establish a formal change control process to manage how approved risk responses are incorporated into the project plan.","B":"Develop a three-point estimate for the project schedule to account for uncertainty associated with the identified risks.","C":"Create ongoing processes to continuously identify, assess, monitor, and respond to risks throughout the project.","D":"Design a business continuity protocol to ensure project operations can continue if a major risk materializes."},"q":"A construction company has been awarded a complex bridge renovation project. In response to executive direction to strengthen risk oversight, the project manager has completed an initial risk identification workshop and documented all identified risks with assigned owners in the risk register.\nWhat should the project manager do next?","exp":"C. Create ongoing processes to continuously identify, assess, monitor, and respond to risks throughout the project.\n\nExplanation: Preparing a risk register and assigning owners establishes a foundation. The next step is building the ongoing processes that turn that foundation into a functioning risk-aware culture. Risk management is continuous throughout the project lifecycle, not a one-time exercise.\n\nWhy the other options are incorrect:\n\nChange control governs how approved changes are processed and documented. It is a separate governance function and does not constitute the ongoing risk management process the project needs.\n\nThree-point estimating incorporates uncertainty into schedule planning but is a planning technique, not a process for continuously identifying and responding to risks as the project evolves.\n\nBusiness continuity protocols address how operations continue when risks materialize. They are reactive by design and do not replace the proactive identification, monitoring, and response processes that ongoing risk management requires.","ans":"C","hint":""},{"n":105,"opts":{"A":"Analyze the expected benefits of adopting the tool against the potential disruption of introducing a change mid-project.","B":"Develop an integration plan to incorporate the tool into the team’s development workflow.","C":"Instruct the development team to begin using the tool immediately to capture the quality improvements.","D":"Add the tool to the project’s technical requirements to formally include it in delivery."},"q":"A project manager is overseeing a software development project in its third sprint cycle. The IT department announces that a new automated code review tool is now available, with early results from other teams showing reductions in defect rates and improvements in code quality.\nWhat should the project manager do?","exp":"A. Analyze the expected benefits of adopting the tool against the potential disruption of introducing a change mid-project.\n\nExplanation: The tool is available and other teams are seeing results, but the project is currently in active sprint execution. Introducing a new tool mid-project carries disruption risk that must be weighed against the expected benefit before any adoption decision is made.\n\nWhy the other options are incorrect:\n\nDeveloping an integration plan treats the adoption decision as already made. The plan should follow a deliberate analysis, not precede it.\n\nInstructing the team to begin using the tool immediately skips the analysis step. Positive results elsewhere do not automatically mean adoption is appropriate for a team currently in sprint execution.\n\nAdding the tool to technical requirements formalizes it as part of the project scope without first evaluating that decision.","ans":"A","hint":""},{"n":106,"opts":{"A":"The team is consistently completing work faster than planned and is on track to finish the sprint ahead of schedule.","B":"The team is behind schedule and should immediately add additional resources to complete the remaining work.","C":"The team should extend the sprint because the burndown chart shows they will not complete the committed work.","D":"The team should increase the sprint scope because they completed work faster than expected."},"q":"You are the project manager for a software development project using Scrum. The team committed to completing 100 story points during a two-week sprint.\nThe burndown chart below shows the team’s progress throughout the sprint. Based on the burndown chart, what is the most accurate conclusion?","exp":"A. The team is consistently completing work faster than planned and is on track to finish the sprint ahead of schedule.\n\nExplanation: The actual burndown line remains below the ideal burndown line for most of the sprint, meaning fewer story points remain than planned. This indicates the team is completing work faster than expected and is on track to complete the sprint successfully.\n\nWhy the other options are incorrect:\n\nThe burndown chart does not indicate the team is behind schedule. The actual line remains below the ideal burndown line.\n\nScrum sprints are fixed timeboxes, and the chart shows no need to extend the sprint.\n\nCompleting work early is not a reason to add more scope. Sprint scope should remain stable once the sprint begins.","ans":"A","hint":"","image":"data:image/png;base64,"},{"n":107,"opts":{"A":"Involved all relevant stakeholders, including the radiology department, in the requirements gathering and planning process.","B":"Developed a comprehensive change management plan to process any requirements identified after planning.","C":"Sought expert judgment from healthcare IT consultants during the scope design phase.","D":"Established a stakeholder communication plan to keep all departments informed of planning progress."},"q":"A project manager recently completed the planning phase for a new patient scheduling system at a hospital. During execution, the radiology department head notifies the project manager that none of the radiology team’s workflow requirements appear in the project scope documentation, despite radiology being a primary user of the new system.\nWhat should the project manager have done to prevent this?","exp":"A. Involved all relevant stakeholders, including the radiology department, in the requirements gathering and planning process.\n\nExplanation: Requirements are missed when stakeholders who will use or be affected by a deliverable are not included in planning. The radiology department is a primary user of the system, making them a key stakeholder whose input should have been gathered before the scope was baselined.\n\nWhy the other options are incorrect:\n\nA change management plan provides a process for handling requirements that surface after planning but does not prevent them from being missed in the first place.\n\nHealthcare IT consultants can provide technical guidance on system design but cannot supply the radiology department’s specific workflow requirements. Only the radiology team can articulate what their work actually requires.\n\nA communication plan keeps stakeholders informed of progress but does not create a mechanism for capturing their input. Being informed is not the same as being involved.","ans":"A","hint":""},{"n":108,"opts":{"A":"Apply the organization’s standard behavioral guidelines to set expectations for team conduct.","B":"Request that the member with the escalation pattern be replaced before the project begins.","C":"Facilitate a team session to establish shared ground rules that govern how the team will communicate, raise concerns, and make decisions.","D":"Hold a project kickoff meeting covering the project plan, timeline, and team responsibilities."},"q":"A project manager is assembling a cross-functional team to implement a new inventory management system. Most members have worked together previously. One member is known for frequently questioning decisions and escalating minor disagreements to leadership. The project begins next week.\nWhat should the project manager do first?","exp":"C. Facilitate a team session to establish shared ground rules that govern how the team will communicate, raise concerns, and make decisions.\n\nExplanation: Ground rules established collaboratively create shared ownership and set clear expectations for how the team will work together. This directly addresses the alignment concern before the project begins and gives the member with the escalation tendency a legitimate, agreed-upon channel for raising concerns.\n\nWhy the other options are incorrect:\n\nApplying standard organizational guidelines imposes conduct expectations from outside the team. Rules the team did not help create tend to produce less genuine commitment and do not address the specific dynamic present in this group.\n\nRequesting reassignment before the project has even started is disproportionate. The member’s behavior may be entirely manageable within a team that has clear ground rules. Removing someone at this stage is a last resort, not a first step.\n\nA project kickoff meeting covers scope, timeline, and responsibilities but does not address how the team will operate together. That is a separate and equally important conversation.","ans":"C","hint":""},{"n":109,"opts":{"A":"Integrate the lessons learned findings into the planning frameworks and processes used for upcoming infrastructure projects.","B":"Review the project management information system to examine how past infrastructure programs managed similar challenges.","C":"Present the lessons learned findings to senior leadership to demonstrate the value of the completed program.","D":"Schedule interviews with stakeholders from the concluded program to validate the accuracy of the documented findings."},"q":"A project manager has concluded a 14-month infrastructure modernization program. A lessons learned analysis has been completed and the findings are documented. The project manager wants to ensure these findings actually benefit the organization’s future infrastructure projects.\nWhat should the project manager do?","exp":"A. Explanation: Lessons learned produce organizational value when their findings are actively applied to future work. Integrating findings into planning frameworks and processes is the mechanism that connects past experience to future performance improvement.\n\nWhy the other options are incorrect:\n\nReviewing past records in the PMIS is an input step that should inform a lessons learned analysis, not a follow-on action once the analysis is already complete and findings are ready to apply.\n\nPresenting findings to senior leadership communicates what was learned but does not embed those insights into the processes that future project managers will actually follow.\n\nValidating findings with stakeholders confirms the accuracy of the documentation but is a quality step on the lessons learned output, not an application of those lessons to future work.","ans":"A","hint":""},{"n":110,"opts":{"A":"Ask crew leads to adjust to standard business hours during the critical path phase.","B":"Schedule daily coordination meetings during the 1pm to 2pm window when all three crews overlap and require each crew lead to attend.","C":"Implement a digital logbook where each crew documents completed work and flags issues for the next crew.","D":"Hold separate coordination meetings with each crew individually and distribute combined summaries to all three crews."},"q":"A construction project has three crews on staggered shifts. The morning crew works 6am to 2pm, the day crew works 9am to 5pm, and the evening crew works 1pm to 9pm. Daily coordination meetings held at 4pm consistently lack morning crew input, and subsequent crews regularly discover issues with prior work that require rework.\nWhat should the project manager prioritize?","exp":"B. Schedule daily coordination meetings during the 1pm to 2pm window when all three crews overlap and require each crew lead to attend.\n\nExplanation: The rework is caused by decisions being made without input from all crews. The 1pm to 2pm window is the only period when all three crews are on site. Scheduling coordination meetings within that window and requiring attendance ensures that decisions affecting all crews are made with all crews present.\n\nWhy the other options are incorrect:\n\nAsking crew leads to adjust to standard hours disrupts the shift structure that exists to meet construction sequencing and coverage needs. Changing shift hours is not the PM’s decision to impose and does not address the underlying coordination gap.\n\nA digital logbook supports information sharing asynchronously but does not replace real-time coordination for technical decisions. Documentation of completed work after the fact does not prevent the next crew from making decisions without prior crew input.\n\nSeparate meetings for each crew fragments the coordination and requires information to flow through summaries rather than shared discussion. That introduces the same information gap the current structure already produces.","ans":"B","hint":""},{"n":111,"opts":{"A":"Review the existing stakeholder register and related project documents to identify known stakeholders and gaps in stakeholder information.","B":"Meet with the primary sponsor to get their perspective on the most important stakeholder relationships.","C":"Assess the current communication plan to determine whether it adequately reaches all relevant stakeholder groups.","D":"Consult with regional operations managers to understand local priorities and stakeholder dynamics in each country."},"q":"A project manager joins an ongoing supply chain transformation project midway through planning. The project involves procurement teams, regional operations managers, IT vendors, and regulatory representatives across five countries. The project manager quickly realizes there is no clear picture of who the key decision-makers are or what each group expects from the project.\nWhat should the project manager do first?","exp":"A. Review the existing stakeholder register and related project documents to identify known stakeholders and gaps in stakeholder information.\n\nExplanation: Before taking any action, the PM needs to understand what stakeholder information already exists and where the gaps are. Reviewing the register and related documents establishes a clear picture of which stakeholders are documented, what is known about their expectations and influence, and what still needs to be determined.\n\nWhy the other options are incorrect:\n\nMeeting with the sponsor provides one perspective on key relationships but does not reveal the full stakeholder landscape or surface gaps in the existing documentation.\n\nAssessing the communication plan addresses how stakeholders are being reached, but that analysis depends on first knowing who the stakeholders are and what they need.\n\nConsulting regional operations managers provides useful local context but is one input channel among many and does not give the PM a complete picture of all stakeholder groups across five countries.","ans":"A","hint":""},{"n":112,"opts":{"A":"The project scope, timeline, and budget must be formally revised to accommodate the additional features.","B":"The team will need to request additional resources to deliver the new features alongside planned sprint work.","C":"The backlog grows, and the new stories may be prioritized into upcoming sprints.","D":"The contingency reserve should be reviewed to determine whether it covers the cost of the additional features."},"q":"A project team is building a customer-facing mobile app using an agile approach. The team is midway through their third sprint. During backlog refinement, the product owner identifies three new user stories based on recent customer feedback.\nWhat impact does this have on the project?","exp":"C. The backlog grows, and the new stories may be prioritized into upcoming sprints.\n\nExplanation: Since the scenario mentions sprints, we know this is probably an agile project. In agile, new user stories are added to the product backlog. Adding items increases backlog size and those items may be prioritized by the product owner into upcoming sprints.\n\nWhy the other options are incorrect:\n\nFormally revising scope, timeline, and budget applies predictive change control to an agile context. In agile, scope evolves through backlog management rather than formal baseline amendments.\n\nRequesting additional resources is not the automatic response to new user stories. Agile teams manage capacity through sprint planning and backlog refinement.\n\nReviewing contingency reserves is a predictive risk management response. New user stories added during backlog refinement are a normal part of agile delivery, not a cost risk event requiring reserve analysis.","ans":"C","hint":""},{"n":113,"opts":{"A":"Require the third-party vendors to resolve all outstanding issues before the phase transition is approved.","B":"Formally document the outstanding integration risks, assign clear ownership, and ensure a management approach is defined before authorizing the transition.","C":"Document the unresolved integration issues in the risk register and proceed with the transition.","D":"Escalate the unresolved dependencies to the project sponsor before authorizing the transition."},"q":"A software development project is completing its build phase and transitioning to user acceptance testing (UAT). The project includes integrations with three third-party APIs, two of which have pending technical issues that have not been fully resolved. The project manager wants to ensure the transition does not expose the UAT phase to unaddressed risks.\nWhat should the project manager do?","exp":"B. Formally document the outstanding integration risks, assign clear ownership, and ensure a management approach is defined before authorizing the transition.\n\nExplanation: Unresolved external dependencies represent outstanding risks that must be formally addressed before the phase boundary is crossed. Documenting them, assigning ownership, and defining how each will be managed ensures they are not silently carried into UAT without anyone accountable for them.\n\nWhy the other options are incorrect:\n\nRequiring vendors to resolve all issues before transition may not be feasible and does not fulfill the PM’s responsibility to formally manage risk disposition. Vendor resolution and formal risk management are separate obligations.\n\nDocumenting the issues in the risk register without assigning ownership or defining a management approach is incomplete. The risks exist in writing but remain unaddressed because no one is accountable for managing them going forward.\n\nEscalating to the sponsor is premature. Formally documenting risks, assigning ownership, and defining a management approach is within the project manager’s responsibility and does not require sponsor involvement before that work is done.","ans":"B","hint":""},{"n":114,"opts":{"A":"Confirm that all deliverables have been completed and formally accepted against the defined acceptance criteria.","B":"Survey the operations team to confirm they are satisfied with the installed systems and ready to take ownership.","C":"Obtain the project sponsor’s sign-off on the project’s schedule and cost performance before authorizing the handover.","D":"Conduct a final walkthrough of the facility with the distribution center manager to verify the installation."},"q":"A logistics company is completing a warehouse automation project. All physical installation work is on schedule. The operations team is ready to take over and the distribution center manager is eager to begin using the new systems. Before authorizing the handover, the project manager must confirm the project is ready for transition.\nWhat should the project manager do first?","exp":"A. Confirm that all deliverables have been completed and formally accepted against the defined acceptance criteria.\n\nExplanation: Transition readiness is validated through formal acceptance of deliverables against the criteria defined at the start of the project. That process confirms the work meets what was agreed upon, not just that it is complete or that stakeholders are pleased.\n\nWhy the other options are incorrect:\n\nSurveying the operations team gauges satisfaction but satisfaction is not the same as formal acceptance. A team may be satisfied with work that does not fully meet defined criteria, or uncertain about work that does.\n\nObtaining sponsor sign-off on schedule and cost performance confirms the project was delivered efficiently but does not confirm that the deliverables themselves meet the acceptance criteria the project was designed to satisfy.\n\nA visual walkthrough is informal and subjective. It does not produce the documented formal acceptance that authorizes transition and protects both parties if disputes arise later.","ans":"A","hint":""},{"n":115,"opts":{"A":"Request that the sponsor allocate an experienced agile coach to support the team in adopting sprint cycles.","B":"Update the project plan to incorporate sprint cycles and schedule the first sprint planning session.","C":"Assess the team’s current experience with agile methods before deciding whether to introduce sprint cycles.","D":"Introduce sprint cycles and use retrospectives to identify and address capability gaps as they emerge."},"q":"A project manager is leading the design phase of a product development initiative. The organization has successfully used agile sprint cycles on similar projects, and the project manager believes introducing them now could improve team alignment and deliverable quality. The current team was assembled specifically for this project and most members have limited experience with agile methods.\nWhat should the project manager do first?","exp":"C. Assess the team’s current experience with agile methods before deciding whether to introduce sprint cycles.\n\nExplanation: The decision to adopt sprint cycles should be based on the team’s actual capability, not on success in other projects with different teams. Assessing current experience first determines whether adoption is feasible, what support may be needed, and whether the design phase timeline can accommodate the transition. Acting before that assessment risks introducing an approach the team cannot effectively execute.\n\nWhy the other options are incorrect:\n\nRequesting an agile coach assumes the team needs external support before the capability gap has been confirmed or measured. The assessment determines what support, if any, is actually needed.\n\nUpdating the project plan and scheduling sprint planning treats the adoption decision as already made. A plan built around sprint cycles before capability is confirmed may not be executable.\n\nIntroducing sprint cycles and relying on retrospectives to surface gaps turns the team into a trial. Retrospectives are designed to improve a functioning process, not to diagnose whether the team can run one at all.","ans":"C","hint":""},{"n":116,"opts":{"A":"Refer to the project charter to identify stakeholders and affected parties named during project initiation.","B":"Review the stakeholder engagement plan to identify communication channels and potential contacts.","C":"Consult the project sponsor to clarify which business units and individuals should be included.","D":"Review the project scope document to determine which business functions fall within the project’s boundaries."},"q":"A project manager is finalizing the planning phase of an enterprise resource planning implementation. The stakeholder register only lists the core project team. Key business unit representatives, system end users, and compliance reviewers have not been identified. Team members are unsure who from the broader organization should be consulted.\nWhat should the project manager do first?","exp":"A. Refer to the project charter to identify stakeholders and affected parties named during project initiation.\n\nExplanation: The project charter formally identifies key stakeholders as part of project authorization. When the register is incomplete, reviewing the charter is the fastest first step because it is immediately available and may resolve the gaps without requiring additional meetings or consultations.\n\nWhy the other options are incorrect:\n\nThe stakeholder engagement plan is built from the register. If the register is incomplete, the engagement plan likely reflects the same gaps and cannot fill them.\n\nConsulting the sponsor is a valid next step if the charter does not resolve the gaps, but it requires scheduling time. Reviewing available documentation first is more efficient.\n\nThe project scope document describes what the project will deliver and which business functions are affected. This provides indirect context but does not formally identify the stakeholders who need to be consulted.","ans":"A","hint":""},{"n":117,"opts":{"A":"Document the observed disengagement as a stakeholder risk in the risk register.","B":"Schedule individual follow-up meetings with the three stakeholders to confirm their understanding of the project and their responsibilities.","C":"Notify the project sponsor that three key stakeholders showed insufficient engagement during the kickoff.","D":"Ask the project team leads to check in with the disengaged stakeholders during upcoming project activities."},"q":"A project manager has just completed a kickoff meeting covering the project scope, timeline, and stakeholder responsibilities for a new product launch. After the meeting, the project manager notices that three key stakeholders submitted no questions, made no comments, and did not acknowledge their assigned responsibilities during the session.\nWhat should the project manager do?","exp":"B. Schedule individual follow-up meetings with the three stakeholders to confirm their understanding of the project and their responsibilities.\n\nExplanation: The PM observed a specific engagement gap and can address it directly. Individual follow-up meetings confirm whether the stakeholders understood their responsibilities and create an opportunity to resolve any confusion before it affects the project. Direct engagement at the PM’s level is the appropriate first response.\n\nWhy the other options are incorrect:\n\nLogging the disengagement as a risk acknowledges the concern but does not address it. A documented risk without a corresponding action leaves the underlying problem unresolved.\n\nNotifying the sponsor escalates before the PM has attempted direct engagement. The PM can address this stakeholder concern without sponsor involvement at this stage.\n\nAsking team leads to check in delegates a stakeholder engagement responsibility that belongs to the project manager. Team leads are not positioned to confirm stakeholder understanding of project responsibilities.","ans":"B","hint":""},{"n":118,"opts":{"A":"Explain to the sponsor that agile requirements are developed iteratively and collaboratively as the project progresses, rather than defined in full detail at the start.","B":"Invite the sponsor to attend upcoming sprint reviews to observe how requirements develop incrementally.","C":"Switch to a predictive planning approach to address the sponsor’s concern about incomplete requirements.","D":"Ask the scrum master to walk the sponsor through the current sprint backlog to demonstrate planning rigor."},"q":"A company has recently adopted agile and is running its first agile project. The project sponsor expresses frustration, saying the requirements gathering process seems incomplete and is moving too fast.\nWhat should the project manager do?","exp":"A. Explain the agile requirements approach to the sponsor and why it was selected for this project.\n\nExplanation: The sponsor’s frustration comes from expecting requirements to be fully defined upfront. The PM should clarify that in agile, requirements emerge incrementally through collaboration as the team learns more. This directly addresses the sponsor’s concern that the process seems incomplete, which reflects a predictive expectation applied to an adaptive approach.\n\nWhy the other options are incorrect:\n\nInviting the sponsor to sprint reviews gives them exposure to the process but observation without explanation may increase confusion. The sponsor needs to understand the rationale, not just watch the activity.\n\nSwitching to predictive planning responds to the sponsor’s discomfort rather than their misunderstanding. If the agile approach was appropriate for the project, changing it under pressure without addressing the underlying confusion is not a sound decision.\n\nAsking the scrum master to explain the backlog provides a partial answer to one concern but delegates sponsor education to the wrong person. Managing the sponsor’s understanding of the project approach is the project manager’s responsibility.","ans":"A","hint":""},{"n":119,"opts":{"A":"Conduct skills assessments for the new hires","B":"Assign new hires to lower-complexity tasks until they have demonstrated sufficient familiarity with the codebase.","C":"Organize workshops where experienced engineers present the system architecture and codebase to the new hires.","D":"Structure team assignments to pair experienced engineers with new hires so knowledge transfers through shared work."},"q":"A technology startup is scaling its development team ahead of a product launch. The team now includes several experienced engineers alongside four new hires who are capable but unfamiliar with the company’s systems and codebase. The project manager needs the full team contributing effectively as quickly as possible.\nWhat should the project manager do?","exp":"D. Structure team assignments to pair experienced engineers with new hires so knowledge transfers through shared work.\n\nExplanation: Pairing experienced and new team members on shared assignments creates direct, real-time knowledge transfer through work rather than through structured preparation. New hires gain exposure to the systems and codebase they need to learn while contributing to actual deliverables, which is faster than assessments, workshops, or task segregation.\n\nWhy the other options are incorrect:\n\nSkills assessments identify knowledge gaps, but the question already tells you the new hires are capable but unfamiliar with the company’s systems and codebase. That means the gap is known and this step is redundant.\n\nAssigning lower-complexity tasks limits new hires’ exposure to the very systems and codebase they need to learn. Keeping them away from complex work delays full contribution.\n\nWorkshops transfer knowledge in one direction and in a single session. Learning through doing alongside an experienced colleague is faster and more contextual than a presentation of the same material.","ans":"D","hint":""},{"n":120,"opts":{"A":"Conduct a structured impact analysis and present recovery options with cost, schedule, and risk trade-offs for formal approval.","B":"Analyze the critical path to identify tasks that can be fast-tracked or reduced in scope to recover the schedule.","C":"Request authorization from the sponsor to implement overtime immediately given the severity of the schedule variance.","D":"Crash critical path activities using existing budget reserves to recover schedule without exceeding the total budget."},"q":"A project is currently 15% behind schedule. The sponsor believes recovery is possible with overtime. The finance manager warns the budget cannot absorb additional costs. The PMO requires that recovery options be formally analyzed and approved before implementation.\nWhat should the project manager do?","exp":"A. Conduct a structured impact analysis and present recovery options with cost, schedule, and risk trade-offs for formal approval.\n\nExplanation: Three stakeholders have each raised a distinct constraint: urgency, budget limits, and a governance requirement for formal analysis before action. The PM cannot satisfy all three by acting on any single option. A structured analysis that evaluates multiple recovery approaches with their cost, schedule, and risk trade-offs addresses all three constraints and fulfills the PMO requirement before any implementation begins.\n\nWhy the other options are incorrect:\n\nAnalyzing the critical path for fast-tracking or scope reduction opportunities is a valid technique within a broader recovery analysis, but presenting it alone skips the full options evaluation and formal approval the PMO requires.\n\nRequesting sponsor authorization for overtime follows the sponsor’s preferred approach but ignores both the budget concern and the PMO’s governance requirement.\n\nCrashing critical path activities using reserves acts before formal analysis and approval, violating the PMO requirement. It also assumes reserves can absorb the cost without confirmation from the finance manager.","ans":"A","hint":""},{"n":121,"opts":{"A":"Develop contingency plans for each identified risk so the team can respond immediately when any risk materializes.","B":"Use qualitative and quantitative analysis to assess and prioritize the identified risks based on probability and impact.","C":"Assign risk owners to each identified risk and establish response budgets based on estimated cost.","D":"Update the risk register with the full list of identified risks and distribute it to all stakeholders for review."},"q":"A project manager for a clinical software implementation has completed a risk identification workshop with key stakeholders. A comprehensive list of potential risks has been compiled. The project manager now needs to prepare a risk management plan that addresses how these risks will be handled throughout the project lifecycle.\nWhat should the project manager do next?","exp":"B. Use qualitative and quantitative analysis to assess and prioritize the identified risks based on probability and impact.\n\nExplanation: Risk identification produces a list. Analysis determines which risks on that list deserve the most attention by assessing their probability and potential impact. Prioritization based on that analysis is what makes the subsequent planning steps focused and efficient. Acting on responses or assigning budgets before risks are prioritized allocates resources without a basis for knowing where they are most needed.\n\nWhy the other options are incorrect:\n\nDeveloping contingency plans is a response planning activity that follows analysis. Creating responses before understanding which risks are highest priority risks wasting resources on low-severity items.\n\nAssigning owners and establishing response budgets also follow analysis. Without probability and impact data, budget estimates have no analytical foundation and resource assignment is arbitrary.\n\nUpdating the risk register and distributing it documents what was identified, but does not address how these risks will be handled. Documentation of risks does not constitute a risk management plan by itself.","ans":"B","hint":""},{"n":122,"opts":{"A":"Listen carefully to the developer’s concerns and acknowledge the impact the rotation is having on their work.","B":"Explain the business reasons for the support rotation","C":"Propose a modified rotation schedule that reduces the developer’s support hours while maintaining coverage.","D":"Offer to reassign some of the developer’s lower-priority tasks to offset the time lost to support duties."},"q":"A senior developer approaches the project manager, expressing frustration that a mandatory support rotation is interfering with their primary development work. The project manager wants to apply a compromise approach to find a solution that works for both the developer and the project.\nWhat should the project manager do first?","exp":"A. Listen carefully to the developer’s concerns and acknowledge the impact the rotation is having on their work.\n\nExplanation: Compromise requires understanding both sides equally before any middle ground can be found. Listening to and acknowledging the developer’s perspective first ensures the PM fully understands what is driving the frustration before presenting constraints or proposing solutions. Proposing or explaining without listening first is not compromise.\n\nWhy the other options are incorrect:\n\nExplaining the business reasons for the rotation presents the PM’s position before the developer’s concern has been fully heard. This frames the conversation as justification rather than dialogue, which is not how a compromise approach begins.\n\nProposing a modified schedule jumps to a specific solution before the PM has understood the full scope of the developer’s concern. The proposal may not address what is actually causing the frustration.\n\nOffering to reassign tasks is a generous action but is still a proposed solution. Offering before listening skips the step that makes compromise possible.","ans":"A","hint":""},{"n":123,"opts":{"A":"Facilitate a team retrospective to allow members to surface grievances and propose process changes.","B":"Determine whether different work styles are causing friction and establish ground rules to address how the team interacts.","C":"Schedule a group meeting with all team members to openly discuss the sources of tension and agree on a resolution.","D":"Schedule one-on-one meetings with each team member to understand their perspective on the team dynamic."},"q":"Project team members have been in ongoing conflict. The project manager initially attributed it to deadline stress, but the friction continued after the deadline passed.\nWhat should the project manager do first?","exp":"D. Schedule one-on-one meetings with each team member to understand their perspective on the team dynamic.\n\nExplanation: The PM’s initial assumption about the cause was wrong. Before choosing any resolution approach, the PM needs to understand what is actually driving the conflict by gathering direct input from the people involved. One-on-one meetings provide that information privately, without the PM committing to a diagnosis or solution prematurely.\n\nWhy the other options are incorrect:\n\nA retrospective is a structured group format designed for process improvement. It does not give the PM the individual perspectives needed to understand an interpersonal conflict before bringing the group together.\n\nDetermining that work styles are the cause and establishing ground rules assumes a specific diagnosis before it has been confirmed. The PM’s previous assumption about deadline stress was wrong, and applying a solution based on another untested assumption repeats that error.\n\nA group meeting brings conflicting parties together before the PM understands the individual dynamics. In an ongoing conflict, convening the group without that foundation risks escalation rather than resolution.","ans":"D","hint":""},{"n":124,"opts":{"A":"Assign tasks based on each team member’s current strongest skills to maximize the team’s immediate delivery capacity.","B":"Hold regular team workshops where members present their areas of expertise and collaborate on shared challenges.","C":"Organize mentorship pairings that connect less experienced members with seasoned colleagues to build skills and alignment.","D":"Create individual development plans for each team member that map their growth goals to the project’s objectives."},"q":"A project manager is leading a cross-functional product development team made up of engineers, designers, and business analysts with varying levels of experience. The project manager wants every team member developing skills they will carry beyond this project.\nWhat should the project manager do?","exp":"C. Organize mentorship pairings that connect less experienced members with seasoned colleagues to build skills and alignment.\n\nExplanation: Mentorship directly addresses both goals the project manager identified. Less experienced members develop skills through ongoing collaboration with seasoned colleagues, while the relationship naturally builds alignment to how the project works and what it is trying to achieve. This creates growth that is embedded in the work rather than structured separately from it.\n\nWhy the other options are incorrect:\n\nAssigning tasks based on current strengths maximizes what each person can deliver immediately but does not expand their capabilities. It optimizes for output, not development.\n\nTeam workshops create opportunities for knowledge sharing and collaboration but are periodic events. They do not provide the continuous, relationship-based learning that mentorship offers.\n\nIndividual development plans document growth goals and create a structured path, but they are only planning tools. A plan does not by itself develop skills the way active mentorship does.","ans":"C","hint":""},{"n":125,"opts":{"A":"Ensure the team has access to the organization’s existing documentation on packaging design and materials.","B":"Conduct brainstorming sessions with the project team to surface their combined knowledge about sustainable packaging.","C":"Hire team members with established experience in biodegradable materials to reduce the need for external research.","D":"Work with team members to clarify their roles and identify where their current knowledge does not cover the project’s requirements."},"q":"A consumer goods company is launching a new line of biodegradable packaging. The project manager is developing the project management plan. Because this is a new material category for the organization, the PM needs to identify what additional knowledge and expertise will be required beyond what the organization currently has.\nWhat should the project manager do?","exp":"D. Work with team members to clarify their roles and identify where their current knowledge does not cover the project’s requirements.\n\nExplanation: Before the project management plan can list the additional knowledge resources needed, the gaps must be identified. Working with team members to clarify roles and map their current knowledge against the project’s requirements reveals what is missing, which is the information needed to plan for external expertise or other knowledge resources.\n\nWhy the other options are incorrect:\n\nProviding access to existing documentation addresses what the organization already knows. It does not identify what is absent or needs to be sourced externally.\n\nBrainstorming surfaces the team’s collective existing knowledge but does not systematically identify where that knowledge falls short of what the project requires.\n\nHiring specialists is a staffing response to a knowledge gap, but before that decision can be made the gaps need to be identified through the planning process. Hiring without gap identification may address the wrong areas.","ans":"D","hint":""},{"n":126,"opts":{"A":"Establish a regular risk review process with defined escalation points that trigger board evaluation when risk thresholds are approached.","B":"Maintain a detailed risk register and update it after each risk event so the board has current information available on request.","C":"Develop contingency plans for each identified risk category so the team can respond before thresholds are exceeded.","D":"Allocate budget reserves at the start of each phase to provide a financial buffer against risks that could affect investment decisions."},"q":"A regional transit authority is funding an innovative light rail extension project in phases. Each phase requires continued investment approval from the authority’s board. The board wants to evaluate project risks before each investment decision. The project manager must ensure risks remain within the defined thresholds for continued funding.\nWhat should the project manager do?","exp":"A. Establish a regular risk review process with defined escalation points that trigger board evaluation when risk thresholds are approached.\n\nExplanation: The board needs structured opportunities to evaluate risk before each investment decision, and the PM needs a mechanism for surfacing threshold breaches before they become problems. A regular review process with defined escalation points serves both needs by creating predictable evaluation checkpoints and ensuring the board is engaged at the right moments.\n\nWhy the other options are incorrect:\n\nMaintaining an updated risk register gives the board access to information but does not create the structured evaluation process or escalation mechanism the phased investment model requires.\n\nContingency plans prepare the team to respond when risks materialize but do not address the governance structure that determines whether funding continues. Response readiness and investment decision-making are separate concerns.\n\nBudget reserves create a financial buffer against cost uncertainty but do not address the board’s need for regular risk evaluation or the PM’s responsibility to escalate when thresholds are approached.","ans":"A","hint":""},{"n":127,"opts":{"A":"Interview the retiring attorneys to document their expertise and have them review the drafts for accuracy before they leave.","B":"Pair the retiring attorneys with junior staff in a formal mentorship program to transfer knowledge directly.","C":"Collect and organize the attorneys’ case files, personal notes, and correspondence into a centralized archive.","D":"Document lessons learned from the firm’s key engagements and update the organization’s information repositories."},"q":"Several founding attorneys at a regional law firm are approaching retirement. These attorneys hold deep institutional knowledge about client relationships, case strategies, and firm processes built over decades. The firm has engaged a project manager to capture this knowledge before it is lost.\nWhat should the project manager do?","exp":"B. Pair the retiring attorneys with junior staff in a formal mentorship program to transfer knowledge directly.\n\nExplanation: The knowledge described, client relationships, case strategy judgment, and informal firm practice, is largely tacit. Tacit knowledge is built through experience and is difficult to fully articulate. It transfers most effectively through direct interaction, observation, discussion, and coaching over time. A mentorship program creates the conditions for that transfer before the attorneys leave.\n\nWhy the other options are incorrect:\n\nInterviewing retiring attorneys and having them review documentation helps document expertise, but it mainly captures explicit knowledge and may miss nuance, judgment, and unwritten practices.\n\nArchiving case files and correspondence collects existing explicit records but does not address the tacit knowledge that has never been written down and exists only in the attorneys’ experience and judgment.\n\nDocumenting lessons learned captures what happened in past engagements and what was learned from them, but like interviews, it is better suited to explicit knowledge. The relational and experiential dimensions of the attorneys’ institutional knowledge are not well preserved through documentation alone.","ans":"B","hint":""},{"n":128,"opts":{"A":"Work with the engineering manager and sponsor to reassess the schedule based on the team’s realistic capacity.","B":"Accept the reduced team capacity and assign additional QA resources to catch quality issues before launch.","C":"Restore the two engineers to the platform project on the grounds that it was scheduled before the security effort.","D":"Replace the reassigned engineers with external contractors who can maintain the original delivery timeline."},"q":"A project manager is overseeing the development of a new customer analytics platform. Midway through development, two senior data engineers are reassigned to support a critical security remediation effort. The engineering manager insists both efforts can be staffed simultaneously. The project sponsor says the platform launch date cannot move. The development team warns the combined workload will compromise code quality.\nWhat should the project manager do?","exp":"A. Work with the engineering manager and sponsor to reassess the schedule based on the team’s realistic capacity.\n\nExplanation: The team has identified that the combined workload will affect quality. The PM has a clear resource constraint and an explicit quality risk. The right first step is to align decision-makers around realistic capacity and trade-offs.\n\nWhy the other options are incorrect:\n\nAdding QA resources addresses one symptom of reduced capacity but does not resolve the underlying tension between workload and timeline. The quality risk the team identified comes from reduced development capacity, not insufficient testing.\n\nRestoring the engineers based on scheduling sequence is a forcing approach. Forcing a resolution disregards the legitimate needs of the security effort and the perspectives of the other stakeholders. It produces a winner and a loser rather than a solution both parties can accept.\n\nReplacing team members with external contractors is a disproportionate first response that does not address the capacity and timeline reality, and treats the reassignment as permanent before any negotiation with the relevant stakeholders has taken place.","ans":"A","hint":""},{"n":129,"opts":{"A":"Allow each team to develop their own document management system tailored to their workflow.","B":"Require each team member to maintain personal copies of all relevant documents and flag updates to their team lead.","C":"Assign the project sponsor to oversee a shared document repository and approve all version changes.","D":"Establish and oversee a single document registry and change control system that both teams access and use."},"q":"A project manager is overseeing a pharmaceutical product development project. The core research team and a remote regulatory compliance team frequently exchange updated technical documents, and both teams must approve documents before submission. Delayed approvals trigger costly timeline extensions.\nWhich practice would assure the project manager that all documents are current, available, and properly approved?","exp":"D. Establish and oversee a single document registry and change control system that both teams access and use.\n\nExplanation: A single PM-overseen registry creates one source of truth for both teams. All document versions, updates, and approvals flow through the same system, which means the PM can confirm at any point that documents are current and that approvals have been obtained from both teams without delays caused by version mismatches or tracking gaps.\n\nWhy the other options are incorrect:\n\nSeparate systems tailored to each team’s preferences create version inconsistency. When two teams manage documents independently, there is no reliable way to confirm both are working from the same current version.\n\nIndividual copies distributed across team members diverge over time without central oversight. Flagging updates to a team lead does not constitute a controlled system and does not give the PM visibility into approval status.\n\nAssigning document oversight to the project sponsor places a project management responsibility in an inappropriate role. The PM is accountable for document control, not the sponsor.","ans":"D","hint":""},{"n":130,"opts":{"A":"Document the situation as a compliance risk and assess what corrective action may be needed.","B":"Continue working with the vendor since no performance issues have occurred and raise the concern at the next scheduled project review.","C":"Submit a change request to replace the vendor with one from the approved vendor list.","D":"Halt work with the vendor until their approval status is formally resolved through the organization’s vendor onboarding process."},"q":"A project manager is overseeing a commercial building renovation. During a contract document review, the project manager realizes the electrical contractor currently working on the project is not on the organization’s approved vendor list. The contractor has been performing well and no issues have occurred.\nWhat should the project manager do first?","exp":"A. Document the situation as a compliance risk and assess what corrective action may be needed.\n\nExplanation: No performance issue has occurred, but the vendor’s approval status is a compliance requirement independent of performance. Documenting it as a compliance risk and assessing the policy implications first ensures the response is proportionate and informed.\n\nWhy the other options are incorrect:\n\nDelaying because performance has been acceptable treats a governance requirement as optional. A vendor’s approval status is a governance obligation regardless of how well they are performing.\n\nSubmitting a change request to replace the vendor is premature before the situation has been assessed and mitigation options considered. Replacement may not be necessary if other corrective paths are available.\n\nHalting work is disproportionate before the situation has been assessed. The contractual and business impact of a work stoppage needs to be understood before taking action that disrupts the project.","ans":"A","hint":""},{"n":131,"opts":{"A":"Reduce the sprint length so the team commits to less work.","B":"Facilitate a discussion on using historical velocity to guide future commitments.","C":"Ask the product owner to remove low-priority items from the backlog.","D":"Assign additional team members to increase the team’s capacity."},"q":"During the third sprint of an agile project, the project manager notices that the team consistently overcommits during sprint planning and fails to complete all committed work by the sprint review. The team’s morale is beginning to decline.\nWhat should the project manager do?","exp":"B. Facilitate a discussion on using historical velocity to guide future commitments.\n\nExplanation: A servant leader helps the team improve its own estimating rather than imposing a fix. Historical velocity is the team’s demonstrated rate of completed work, so anchoring planning to it lets the team commit to a realistic amount, restoring both predictability and morale while keeping the team self-organizing.\n\nWhy the other options are incorrect:\n\nReducing the sprint length changes the timebox but not the team’s tendency to overcommit; the same overcommitment ratio simply recurs in a shorter cycle.\n\nRemoving low-priority backlog items is the product owner’s prerogative and addresses backlog content, not the team’s flawed estimation behavior, which is the actual cause.\n\nAdding team members increases capacity but does not teach the team to estimate accurately, and new members typically reduce velocity temporarily while they onboard.","ans":"B","hint":""},{"n":132,"opts":{"A":"Submit a change request to the change control board.","B":"Update the risk register to reflect the regulatory change.","C":"Perform an impact analysis on the affected deliverables.","D":"Inform the team that rework will be required."},"q":"A project manager is leading a predictive infrastructure project. Midway through execution, a key regulatory requirement changes, affecting several completed deliverables. The sponsor wants to know the cost and schedule impact immediately.\nWhat should the project manager do first?","exp":"C. Perform an impact analysis on the affected deliverables.\n\nExplanation: An impact analysis quantifies how the regulatory change affects scope, cost, and schedule, producing the data the sponsor is asking for and the evidence needed to support any later change request. The project manager cannot responsibly report impact or propose action without first understanding the magnitude of the change.\n\nWhy the other options are incorrect:\n\nSubmitting a change request before the impact is known means the board would be evaluating an unquantified change, which prevents an informed decision.\n\nUpdating the risk register documents the event but does not produce the cost and schedule figures the sponsor requested, and the change has already occurred, so it is now an issue rather than a risk.\n\nInforming the team that rework is required assumes a solution before analysis confirms what, if any, rework is actually needed.","ans":"C","hint":""},{"n":133,"opts":{"A":"Speak privately with the senior developers about their behavior.","B":"Establish team ground rules collaboratively with all members.","C":"Reassign the junior members to a different project team.","D":"Escalate the conflict to the functional managers involved."},"q":"A newly formed agile team is in its first iteration. Two senior developers frequently dismiss ideas raised by junior members during daily standups, and the junior members have stopped contributing.\nWhat should the project manager do?","exp":"B. Establish team ground rules collaboratively with all members.\n\nExplanation: Ground rules created collaboratively set shared expectations for respectful participation and give the whole team ownership of how it interacts. Because this is a forming team, defining norms now corrects the dynamic at its root and empowers members to hold one another accountable going forward.\n\nWhy the other options are incorrect:\n\nSpeaking privately with the senior developers addresses only one side of the behavior and does not re-engage the silenced junior members or set a team-wide standard.\n\nReassigning the junior members removes valued contributors and rewards the disruptive behavior instead of resolving it.\n\nEscalating to functional managers is premature for a routine team dynamic the project manager is fully capable of facilitating directly.","ans":"B","hint":""},{"n":134,"opts":{"A":"Review the risk register for a related response strategy.","B":"Search the market for an alternate supplier immediately.","C":"Notify the sponsor that the project will likely be delayed.","D":"Submit a claim against the vendor for breach of contract."},"q":"A project is halfway through execution when the project manager learns that a critical vendor has filed for bankruptcy and can no longer deliver a specialized component. No alternate supplier was identified during planning.\nWhat should the project manager do first?","exp":"A. Review the risk register for a related response strategy.\n\nExplanation: The risk register is the first place to look because it may already contain this threat and a pre-planned response, allowing the project manager to act deliberately rather than reactively. Consulting it ensures any next step is consistent with prior risk analysis and agreed contingency or fallback plans.\n\nWhy the other options are incorrect:\n\nSearching the market immediately jumps to executing one possible response before confirming whether a planned strategy or contingency reserve already exists.\n\nNotifying the sponsor of a likely delay communicates an unverified conclusion before the project manager has assessed available responses.\n\nSubmitting a breach claim is a legal action handled later through procurement and legal channels; it does nothing to recover the schedule in the near term.","ans":"A","hint":""},{"n":135,"opts":{"A":"Tell the stakeholders the product will be shown only at project closure.","B":"Ask the team to prepare a separate formal presentation outside of sprints.","C":"Invite the stakeholders to the existing iteration review meeting.","D":"Provide the stakeholders with written status reports instead of a demo."},"q":"An organization uses a hybrid delivery approach. During a release, the business stakeholders request a demonstration of the working product, but the agile team argues that stopping to prepare a formal demo will disrupt their cadence.\nWhat should the project manager do?","exp":"C. Invite the stakeholders to the existing iteration review meeting.\n\nExplanation: The iteration review already exists specifically to demonstrate the working increment and gather feedback, so inviting stakeholders satisfies their request using an event that is part of the team’s normal cadence, avoiding the disruption the team is worried about.\n\nWhy the other options are incorrect:\n\nDeferring the demonstration to project closure eliminates the early and frequent feedback that hybrid and agile approaches are designed to provide.\n\nPreparing a separate formal presentation creates exactly the out-of-cadence overhead the team objected to, when a suitable event already exists.\n\nProviding written status reports substitutes documentation for a live demonstration of working product, which is not what the stakeholders asked for and yields weaker feedback.","ans":"C","hint":""},{"n":136,"opts":{"A":"Create a RACI chart and review it with the team.","B":"Increase the frequency of status meetings to track work.","C":"Ask each team member to document what they are working on.","D":"Escalate the resourcing confusion to the project sponsor."},"q":"A project manager takes over a struggling project and finds that team members are unclear about who is responsible for several key deliverables. Work is being duplicated and some tasks are falling through the cracks.\nWhat should the project manager do?","exp":"A. Create a RACI chart and review it with the team.\n\nExplanation: A RACI chart explicitly maps who is responsible, accountable, consulted, and informed for each deliverable. Reviewing it with the team eliminates the ambiguity that is causing both duplicated work and dropped tasks, because every activity gains a clear, agreed owner.\n\nWhy the other options are incorrect:\n\nIncreasing meeting frequency adds oversight but does not assign ownership, so the same confusion persists between meetings.\n\nHaving members document their current work reveals the overlaps but does not resolve who should own each deliverable going forward.\n\nEscalating to the sponsor treats a problem the project manager is responsible for and equipped to fix directly as someone else’s issue.","ans":"A","hint":""},{"n":137,"opts":{"A":"Call on the team member directly during the next meeting.","B":"Seek to understand the cultural and communication preferences involved.","C":"Ask the team member’s functional manager about their performance.","D":"Assume the team member has nothing to contribute and move on."},"q":"During execution of a global project, a project manager observes that a team member from one region consistently stays silent during virtual meetings, even when their expertise is clearly relevant to the discussion.\nWhat should the project manager do?","exp":"B. Seek to understand the cultural and communication preferences involved.\n\nExplanation: Leading global teams requires cultural awareness. By understanding the team member’s communication style and any cultural factors behind the silence, the project manager can adapt the environment, perhaps through different participation channels, to draw out the person’s expertise inclusively and respectfully.\n\nWhy the other options are incorrect:\n\nCalling on the member abruptly in a meeting may cause discomfort or embarrassment and ignores the underlying reason for the silence.\n\nQuestioning the functional manager about performance is intrusive and assumes a performance problem before the project manager has even understood the cause.\n\nAssuming the member has nothing to offer dismisses relevant expertise and fails the project manager’s responsibility to engage the whole team.","ans":"B","hint":""},{"n":138,"opts":{"A":"Continue with the predictive plan to avoid disrupting the baseline.","B":"Replace the entire team with one experienced in agile delivery.","C":"Tell the sponsor the approach cannot change after planning is complete.","D":"Evaluate transitioning to an iterative approach that delivers value incrementally."},"q":"A project sponsor informs the project manager that, due to a strategic shift, the organization wants to accelerate delivery of business value rather than wait for the full product at the end of the current predictive project.\nWhat should the project manager do?","exp":"D. Evaluate transitioning to an iterative approach that delivers value incrementally.\n\nExplanation: When the goal becomes earlier delivery of business value, an iterative or incremental approach lets the team release usable portions of the product sooner. Evaluating this transition responds directly to the sponsor’s strategic need while still assessing feasibility before committing.\n\nWhy the other options are incorrect:\n\nContinuing with the predictive plan preserves the baseline but ignores the sponsor’s explicit, legitimate request for earlier value.\n\nReplacing the entire team is drastic, destroys existing knowledge, and is unnecessary since teams can adopt iterative practices with support.\n\nTelling the sponsor the approach cannot change is inaccurate; tailoring the delivery approach in response to changing needs is a core project management responsibility.","ans":"D","hint":""},{"n":139,"opts":{"A":"Reinforce the change control process with the stakeholder and the team.","B":"Implement the requested changes to keep the stakeholder satisfied.","C":"Remove the stakeholder from the project communications list.","D":"Ask the developers to ignore any informal requests they receive."},"q":"A project manager is managing a project where a key stakeholder repeatedly bypasses the agreed change control process by requesting changes informally during hallway conversations with developers.\nWhat should the project manager do?","exp":"A. Reinforce the change control process with the stakeholder and the team.\n\nExplanation: Reinforcing the process with both the stakeholder and the developers re-establishes the single approved path for changes, protecting scope, schedule, and cost from uncontrolled creep while keeping the relationship constructive by educating rather than confronting.\n\nWhy the other options are incorrect:\n\nImplementing the informal changes rewards bypassing the process and invites uncontrolled scope creep with no impact analysis or approval.\n\nRemoving the stakeholder from communications damages an important relationship and does not address the behavior; key stakeholders need engagement, not exclusion.\n\nTelling developers to ignore the requests addresses only one side and leaves the stakeholder unguided, likely escalating frustration rather than redirecting them to the proper channel.","ans":"A","hint":""},{"n":140,"opts":{"A":"Have the team document assumptions and proceed without clarification.","B":"Escalate the product owner’s absence to the project sponsor immediately.","C":"Discuss the impact of the product owner’s availability and agree on a solution.","D":"Appoint a team member to act as a proxy product owner permanently."},"q":"An agile team has completed several iterations successfully. The product owner is frequently unavailable to clarify requirements, causing the team to make assumptions that later require rework during the iteration review.\nWhat should the project manager do?","exp":"C. Discuss the impact of the product owner’s availability and agree on a solution.\n\nExplanation: The project manager should surface the problem directly with the product owner, explain the rework it is causing, and collaboratively agree on a workable arrangement, such as scheduled availability or an authorized proxy. This addresses the root cause through dialogue and shared ownership of the fix.\n\nWhy the other options are incorrect:\n\nDocumenting assumptions and proceeding accepts the rework as inevitable rather than removing its cause.\n\nEscalating to the sponsor immediately skips the reasonable first step of discussing it with the product owner, who may simply be unaware of the impact.\n\nPermanently appointing a proxy removes the genuine product owner from the value decisions they are accountable for, and doing so without their agreement oversteps the project manager’s authority.","ans":"C","hint":""},{"n":141,"opts":{"A":"Remove the weather-dependent activities from the critical path.","B":"Assume favorable weather to keep the schedule baseline optimistic.","C":"Schedule the activities during the historically driest month only.","D":"Develop contingency reserves and response plans for the weather risk."},"q":"During the planning of a construction project, the project manager identifies that two activities on the critical path are highly dependent on weather conditions that are unpredictable in the project’s region.\nWhat should the project manager do?","exp":"D. Develop contingency reserves and response plans for the weather risk.\n\nExplanation: Weather is an identified threat to critical-path activities, so the appropriate response is to plan for it: establish schedule contingency reserves and response strategies. This prepares the project to absorb or mitigate weather delays without derailing the overall timeline.\n\nWhy the other options are incorrect:\n\nRemoving the activities from the critical path is not something a project manager can simply declare; the path is determined by dependencies and durations, not preference.\n\nAssuming favorable weather builds an unrealistic baseline that will almost certainly be missed, undermining credibility and control.\n\nRestricting the work to the driest month may be infeasible given dependencies and resource availability, and still leaves the project exposed if that month’s weather varies.","ans":"D","hint":""},{"n":142,"opts":{"A":"Report the declining velocity to senior management for review.","B":"Create a safe environment that encourages open and honest discussion.","C":"Set a higher velocity target to motivate the team to recover.","D":"Replace the retrospective with a one-on-one with each member."},"q":"A project manager notices that team velocity has dropped significantly over the last two iterations. During the retrospective, team members are quiet and reluctant to discuss what might be causing the decline.\nWhat should the project manager do?","exp":"B. Create a safe environment that encourages open and honest discussion.\n\nExplanation: A retrospective only works when team members feel safe to speak candidly. Building psychological safety encourages the team to surface the real causes of the velocity drop, which is the prerequisite to solving it and is central to the project manager’s servant-leadership role.\n\nWhy the other options are incorrect:\n\nReporting the decline to senior management before understanding the cause can feel punitive, deepening the team’s reluctance to be open.\n\nSetting a higher target ignores the unknown root cause and adds pressure that is likely to worsen morale and velocity.\n\nReplacing the retrospective with individual conversations abandons the team’s primary forum for collective improvement and may signal distrust, when the better move is to make that forum feel safe.","ans":"B","hint":""},{"n":143,"opts":{"A":"Insist that all team members voice disagreement during meetings.","B":"Proceed with proposals since no one has objected to them.","C":"Adapt their leadership approach to the local cultural context.","D":"Request that the team adopt the project manager’s home-country norms."},"q":"A project manager is assigned to a project in a country where business customs differ significantly from their own. Early in the project, the local team appears hesitant to raise concerns or disagree openly with the project manager’s proposals.\nWhat should the project manager do?","exp":"C. Adapt their leadership approach to the local cultural context.\n\nExplanation: Cultural competence means meeting the team where they are. By adapting their leadership style to local norms, perhaps using more indirect or private channels for feedback, the project manager creates conditions where the team will genuinely share concerns, improving decisions and trust.\n\nWhy the other options are incorrect:\n\nInsisting on open disagreement forces behavior that conflicts with the team’s cultural comfort and is likely to produce silence or superficial compliance.\n\nProceeding because no one objected mistakes politeness or deference for genuine agreement, risking decisions built on unspoken concerns.\n\nRequiring the team to adopt the project manager’s home norms disregards the local culture and undermines the inclusive environment needed for the team to contribute.","ans":"C","hint":""},{"n":144,"opts":{"A":"Determine the root cause of why the defect was not detected.","B":"Apologize to the customer and offer a discount on the contract.","C":"Quietly rework the deliverable before anyone else notices.","D":"Update the quality management plan to prevent future defects."},"q":"Halfway through a project, the project manager discovers that a deliverable accepted by the customer last month does not meet a documented quality requirement. The defect was missed during quality control.\nWhat should the project manager do first?","exp":"A. Determine the root cause of why the defect was not detected.\n\nExplanation: Understanding why quality control failed to catch the defect is the necessary first step, because the root cause informs both the correct remedy for this deliverable and any process changes needed to stop recurrence. Acting without that understanding risks repeating the same gap.\n\nWhy the other options are incorrect:\n\nApologizing and offering a discount jumps to a commercial concession before the project manager understands the problem or whether that response is even appropriate.\n\nQuietly reworking the deliverable hides a known quality issue from the customer, violating transparency and professional responsibility.\n\nUpdating the quality management plan is a valid later step, but doing it before the root cause is known means the update may not target the actual failure.","ans":"A","hint":""},{"n":145,"opts":{"A":"Add more team members to clear the in-progress work faster.","B":"Switch the team back to their previous predictive approach.","C":"Increase the iteration length to give tasks more time to finish.","D":"Help the team establish work-in-progress limits on the board."},"q":"A project manager leads a team that has just adopted a kanban approach. The team complains that too many tasks are in progress at once, and work items are taking much longer to complete than expected.\nWhat should the project manager do?","exp":"D. Help the team establish work-in-progress limits on the board.\n\nExplanation: Excessive work in progress and long cycle times are exactly what work-in-progress (WIP) limits are designed to fix. By capping how many items can be active in each stage, the team finishes work before starting new work, which reduces multitasking and shortens completion times.\n\nWhy the other options are incorrect:\n\nAdding members increases capacity but does nothing to curb the multitasking that is causing the slowdown, and may even add more concurrent work.\n\nReverting to the previous approach abandons kanban over a problem that kanban has a built-in mechanism to solve.\n\nIncreasing iteration length does not apply cleanly to a flow-based kanban system and would simply allow the bottleneck of too much concurrent work to persist longer.","ans":"D","hint":""},{"n":146,"opts":{"A":"Skip the lessons learned since the project was successful.","B":"Conduct a lessons learned session before formally closing the project.","C":"Ask the sponsor to compile the lessons learned after closure.","D":"Document only the positive outcomes to reflect the project’s success."},"q":"A project manager is preparing for the closeout of a successfully delivered project. While reviewing documentation, the project manager realizes that the lessons learned were never compiled because the team was focused on delivery.\nWhat should the project manager do?","exp":"B. Conduct a lessons learned session before formally closing the project.\n\nExplanation: Capturing lessons learned is part of properly closing a project, and doing it while the team and details are still fresh preserves knowledge for future projects and the organization’s process assets. Holding the session before formal closure ensures this required output is completed.\n\nWhy the other options are incorrect:\n\nSkipping lessons learned because the project succeeded discards valuable insights; successful projects also yield reusable practices and avoidable pitfalls.\n\nAsking the sponsor to compile them after closure shifts a project management responsibility to the wrong party and risks losing detail once the team disperses.\n\nDocumenting only positive outcomes produces a biased record that omits the very challenges future teams would most benefit from understanding.","ans":"B","hint":""},{"n":147,"opts":{"A":"Reassign one of the team members to remove the friction.","B":"Allow the team members to resolve the conflict on their own.","C":"Meet with both members to understand and address the conflict.","D":"Document the conflict in each member’s performance record."},"q":"During execution, a project manager finds that two team members are in an escalating personal conflict that is now affecting their collaboration and the quality of shared deliverables.\nWhat should the project manager do?","exp":"C. Meet with both members to understand and address the conflict.\n\nExplanation: Conflict that is harming deliverables requires the project manager to intervene. Meeting with both members allows the project manager to understand each perspective and facilitate a resolution collaboratively, which preserves the working relationship and restores quality.\n\nWhy the other options are incorrect:\n\nReassigning a member avoids the conflict instead of resolving it, may not be feasible, and can leave underlying issues to resurface elsewhere.\n\nLetting the members resolve it alone is reasonable for minor disagreements, but this conflict has already escalated and is degrading work, so it warrants intervention.\n\nDocumenting the conflict in performance records is punitive and premature, and does nothing to actually resolve the situation harming the project.","ans":"C","hint":""},{"n":148,"opts":{"A":"Verify the regulatory requirement and adjust the approach to comply.","B":"Continue with the efficient approach to maintain the schedule.","C":"Wait until an auditor flags the issue before making changes.","D":"Ask the client whether they are willing to accept the compliance risk."},"q":"A project manager is leading a project for a client in a heavily regulated industry. Partway through execution, the project manager realizes a planned approach, while efficient, may not fully comply with an applicable industry regulation.\nWhat should the project manager do?","exp":"A. Verify the regulatory requirement and adjust the approach to comply.\n\nExplanation: Compliance is non-negotiable in a regulated industry. The project manager must confirm the actual requirement and bring the approach into compliance, protecting the client, the organization, and the project from legal and safety consequences regardless of efficiency gains.\n\nWhy the other options are incorrect:\n\nContinuing with the non-compliant approach to save time knowingly exposes the project to regulatory violation, which is unacceptable and a breach of professional responsibility.\n\nWaiting for an auditor to flag the issue gambles on detection and allows a known violation to persist, increasing risk and potential penalties.\n\nAsking the client to accept the compliance risk inappropriately offers to trade away a legal obligation that is not the client’s to waive.","ans":"A","hint":""},{"n":149,"opts":{"A":"Hold all meetings during the project manager’s own working hours.","B":"Make all decisions without waiting for absent team members.","C":"Record meetings only and stop holding live sessions entirely.","D":"Establish a communication plan that rotates meeting times and uses asynchronous methods."},"q":"A project manager is managing a virtual team spread across four time zones. Team members frequently miss meetings, and decisions are being delayed because not everyone is present when key topics are discussed.\nWhat should the project manager do?","exp":"D. Establish a communication plan that rotates meeting times and uses asynchronous methods.\n\nExplanation: A communication plan that rotates meeting times shares the inconvenience fairly across time zones, and combining it with asynchronous methods lets members contribute to decisions even when they cannot attend live. Together these address both the attendance problem and the decision delays.\n\nWhy the other options are incorrect:\n\nHolding all meetings in the project manager’s hours places the entire burden on other regions, perpetuating the attendance problem.\n\nMaking decisions without absent members may speed things up but excludes input and erodes engagement, risking poorer decisions and resentment.\n\nRecording meetings and dropping live sessions removes valuable real-time interaction and still does not give absent members a way to influence decisions before they are made.","ans":"D","hint":""},{"n":150,"opts":{"A":"Implement the solution immediately to capture the added value.","B":"Evaluate the proposal and discuss it with the customer through the proper process.","C":"Reject the idea because it falls outside the agreed scope.","D":"Ask the team to implement it quietly and reveal it at delivery."},"q":"A project manager is overseeing a project where the team has proposed an innovative technical solution that could deliver significant additional value but was not part of the original scope. The customer is unaware of the idea.\nWhat should the project manager do?","exp":"B. Evaluate the proposal and discuss it with the customer through the proper process.\n\nExplanation: A potentially valuable but out-of-scope idea should be assessed and then raised with the customer through change control, so the customer can make an informed decision about the added value, cost, and schedule implications. This respects both the scope baseline and the customer’s authority over scope.\n\nWhy the other options are incorrect:\n\nImplementing the solution immediately adds unapproved scope without analysis or customer consent, which is uncontrolled scope creep.\n\nRejecting the idea outright discards potential value without giving the customer the chance to consider a genuinely beneficial opportunity.\n\nImplementing it quietly and revealing it at delivery hides a scope change from the customer and removes their right to decide, while exposing the project to cost and schedule impacts they never approved.","ans":"B","hint":""},{"n":151,"opts":{"A":"Apply fast tracking by performing eligible activities in parallel.","B":"Add overtime hours to the team to recover the schedule.","C":"Inform the sponsor that the date cannot be met as planned.","D":"Reduce the scope of remaining deliverables to save time."},"q":"A project manager is leading a project where the schedule baseline shows the project finishing two weeks late. The sponsor insists the original date must be met without adding budget. The project manager identifies that several activities have flexibility in their sequencing.\nWhat should the project manager do?","exp":"A. Apply fast tracking by performing eligible activities in parallel.\n\nExplanation: Fast tracking overlaps activities that would normally run in sequence to compress the schedule without adding cost, which fits the constraint of meeting the date without more budget. The project manager has already identified activities with sequencing flexibility, making this technique directly applicable.\n\nWhy the other options are incorrect:\n\nAdding overtime is crashing, which typically increases cost and contradicts the no-additional-budget constraint, and also risks burnout.\n\nTelling the sponsor the date cannot be met abandons viable compression options before they have been attempted.\n\nReducing scope changes what the customer receives and requires change control; it sacrifices the product rather than optimizing the schedule.","ans":"A","hint":""},{"n":152,"opts":{"A":"Close the identified risks since the project is already underway.","B":"Add the risks to the issue log for immediate resolution.","C":"Analyze the risks and develop appropriate response strategies.","D":"Wait for the risks to occur before deciding how to respond."},"q":"A project manager has recently been assigned to a project already in execution. While reviewing documents, the project manager finds that risks were identified during planning but no responses were ever assigned to them.\nWhat should the project manager do?","exp":"C. Analyze the risks and develop appropriate response strategies.\n\nExplanation: Identified risks without planned responses leave the project exposed. The project manager should analyze them and develop response strategies so the team is prepared to act if they occur, completing the risk management work that was left unfinished.\n\nWhy the other options are incorrect:\n\nClosing the risks ignores genuine threats that still apply during execution.\n\nMoving them to the issue log is premature because risks are uncertain future events, not problems that have already happened.\n\nWaiting for the risks to occur forfeits the chance to prevent or mitigate them and forces purely reactive management.","ans":"C","hint":""},{"n":153,"opts":{"A":"Continue using the chatbot because the information provided is accurate.","B":"Explain how AI supports project communications and when it is being used.","C":"Disable the chatbot until every stakeholder approves its use.","D":"Limit AI responses to internal project team members only."},"q":"A project manager introduces an AI chatbot that answers routine stakeholder questions regarding milestones, deliverables, and project status. During a steering committee meeting, several stakeholders state they did not realize AI was responding to many of their questions and express concern about how project information is being communicated.\nWhat should the project manager do?","exp":"B. Explain how AI supports project communications and when it is being used.\n\nExplanation: Responsible AI use requires transparency. Stakeholders should understand when AI supports project communications so trust and confidence in project information are maintained.\n\nWhy the other options are incorrect:\n\nAccurate information alone does not satisfy transparency requirements.\n\nStakeholder approval is not required before responsibly using AI.\n\nRestricting AI to internal users does not address the communication concern raised by stakeholders.","ans":"B","hint":""},{"n":154,"opts":{"A":"Allow the additions since the product owner sets priorities.","B":"Extend the sprint to accommodate the additional work.","C":"Ask the team to work faster to absorb the new items.","D":"Coach the product owner on protecting the sprint scope."},"q":"An agile team is partway through a release. The product owner keeps adding high-priority items to the current sprint after it has already started, disrupting the team’s ability to finish committed work.\nWhat should the project manager do?","exp":"D. Coach the product owner on protecting the sprint scope.\n\nExplanation: Once a sprint begins, its scope should remain stable so the team can deliver its commitment. As a servant leader, the project manager coaches the product owner to bring new items into future sprints through the backlog, preserving the team’s focus and predictability.\n\nWhy the other options are incorrect:\n\nAllowing mid-sprint additions undermines the team’s commitment and is the very behavior causing the disruption, even though the product owner does own priorities.\n\nExtending the sprint breaks the fixed timebox that gives the cadence its rhythm and predictability.\n\nAsking the team to work faster pressures them to absorb unplanned work and is likely to harm quality and morale.","ans":"D","hint":""},{"n":155,"opts":{"A":"Continue as planned and add the documentation at project closure.","B":"Refuse the additional documentation as it was not in the original scope.","C":"Assess the impact and process the new requirement through change control.","D":"Absorb the extra work quietly to maintain the client relationship."},"q":"A project is being delivered for a government client. During execution, the client introduces a new law that requires additional documentation for every deliverable, increasing the workload significantly.\nWhat should the project manager do?","exp":"C. Assess the impact and process the new requirement through change control.\n\nExplanation: A legally mandated requirement is a change to scope that carries cost and schedule implications. Assessing the impact and routing it through change control ensures the requirement is formally incorporated with adjusted baselines and proper approval.\n\nWhy the other options are incorrect:\n\nDeferring the documentation to closure ignores that the requirement applies to every deliverable as work proceeds, creating compliance gaps.\n\nRefusing the documentation is not an option when it is legally required of the project.\n\nAbsorbing the work quietly hides a real scope and resource impact, distorting the baselines and setting an unsustainable precedent.","ans":"C","hint":""},{"n":156,"opts":{"A":"Establish a communications management plan defining how updates are shared.","B":"Instruct team members to stop communicating with stakeholders entirely.","C":"Send a single status email and consider the matter resolved.","D":"Ask stakeholders to disregard any updates not from the project manager."},"q":"A project manager observes that stakeholders are receiving conflicting information about project status because several team members communicate updates informally and inconsistently.\nWhat should the project manager do?","exp":"A. Establish a communications management plan defining how updates are shared.\n\nExplanation: A communications management plan specifies what information goes to whom, when, through which channel, and by whom, eliminating the inconsistency by giving everyone a single agreed structure for status reporting.\n\nWhy the other options are incorrect:\n\nProhibiting all team-stakeholder communication is impractical and harms collaboration rather than organizing it.\n\nA one-time status email fixes the immediate symptom but not the absence of a repeatable communication structure.\n\nTelling stakeholders to ignore non-PM updates does not stop the conflicting messages from continuing to be sent.","ans":"A","hint":""},{"n":157,"opts":{"A":"Allow the executive to direct the team given their seniority.","B":"Meet with the executive to clarify roles and protect the team.","C":"Tell the team to ignore the executive’s individual instructions.","D":"Escalate the executive’s behavior to the human resources department."},"q":"A project manager is leading a team that has been highly self-organizing and effective. A new senior executive begins directing the team members individually, bypassing the project manager and disrupting the team’s flow.\nWhat should the project manager do?","exp":"B. Meet with the executive to clarify roles and protect the team.\n\nExplanation: Part of servant leadership is shielding the team from disruption. A direct, respectful conversation with the executive to clarify how requests should flow protects the team’s self-organization while preserving the relationship with a senior stakeholder.\n\nWhy the other options are incorrect:\n\nSimply allowing the executive to direct individuals lets the disruption continue and erodes the team’s effective dynamic.\n\nTelling the team to ignore the executive puts members in an awkward position against a senior leader and avoids addressing the source.\n\nEscalating to human resources is disproportionate for what is, at this stage, a coordination issue the project manager can address directly.","ans":"B","hint":""},{"n":158,"opts":{"A":"Request additional budget from the sponsor to cover the overrun.","B":"Reduce the project scope to bring costs back in line.","C":"Replace underperforming team members to improve productivity.","D":"Analyze the variances to determine their underlying causes."},"q":"During execution, a project manager realizes that the cost performance index (CPI) is 0.85 and the schedule performance index (SPI) is 0.90, indicating the project is over budget and behind schedule.\nWhat should the project manager do first?","exp":"D. Analyze the variances to determine their underlying causes.\n\nExplanation: A CPI below one and an SPI below one signal cost and schedule problems, but the right corrective action depends on why they are occurring. Analyzing the variances first identifies root causes so any subsequent response targets the actual problem.\n\nWhy the other options are incorrect:\n\nRequesting more budget addresses a symptom without knowing whether the overrun stems from a fixable cause.\n\nReducing scope is a significant change that should not be chosen before understanding what is driving the variances.\n\nReplacing team members assumes a performance cause that has not been established and may be unfair and disruptive.","ans":"D","hint":""},{"n":159,"opts":{"A":"Select the lower-cost material to maximize the project’s immediate return on investment.","B":"Evaluate both options using long-term environmental, social, and financial impacts before making a recommendation.","C":"Ask the procurement manager to choose whichever material is most readily available.","D":"Delay the decision until construction begins so actual budget performance can be evaluated."},"q":"A project manager is leading the construction of a new manufacturing facility. During procurement, the team identifies two roofing materials. One has a lower upfront cost but a shorter lifespan and higher energy consumption. The other costs more initially but significantly reduces energy use and maintenance over the next 25 years.\nWhat should the project manager do?","exp":"B. Evaluate both options using long-term environmental, social, and financial impacts before making a recommendation.\n\nExplanation: Sustainability requires balancing people, planet, and profit while considering longterm value rather than only short-term cost.\n\nWhy the other options are incorrect:\n\nSelecting the cheapest option focuses only on short-term cost.\n\nDelegating the decision ignores the project manager’s responsibility.\n\nDelaying the decision provides no additional sustainability benefit.","ans":"B","hint":""},{"n":160,"opts":{"A":"Ask the veteran team members to document their domain knowledge in detailed technical guides before development begins.","B":"Use an AI tool to compile the veterans’ past project histories into a searchable knowledge base for the new hires.","C":"Facilitate collaborative working sessions that pair experienced and new team members to surface domain knowledge through discussion and shared problem-solving.","D":"Enroll the new hires in formal training courses to build their foundational knowledge before they join the main team."},"q":"A project manager is assembling a team to develop a new e-commerce platform. The team includes four veterans who have worked on similar platforms for years and three recent hires who are technically capable but have no experience in this specific domain. The project manager needs to ensure the veterans’ domain knowledge becomes accessible to the entire team.\nWhat should the project manager do?","exp":"C. Facilitate collaborative working sessions that pair experienced and new team members to surface domain knowledge through discussion and shared problem-solving.\n\nExplanation: The domain knowledge veterans hold includes judgment, context, and situational awareness that does not surface through documentation or training alone. Collaborative sessions create the conditions for that knowledge to emerge through conversation and shared problem-solving between experienced and new team members.\n\nWhy the other options are incorrect:\n\nTechnical documentation captures explicit knowledge but misses the reasoning and contextual expertise that makes veteran knowledge valuable. What practitioners consider obvious often goes unwritten.\n\nAn AI-compiled knowledge base aggregates existing records but does not create the interpersonal exchange through which tacit knowledge is actually transferred.\n\nFormal training builds general foundational skills but does not transfer the specific domain expertise the veterans hold about this type of platform.","ans":"C","hint":""},{"n":161,"opts":{"A":"A communications management plan defining how project information will be distributed to all affected departments.","B":"A work breakdown structure decomposing the migration activities into manageable components.","C":"A project charter formally authorizing the migration and defining the project manager’s authority.","D":"A project management plan integrating all subsidiary plans and establishing how the project will be executed, monitored, and controlled."},"q":"A project manager is assigned to lead a nationwide IT system migration affecting multiple departments. The project sponsor asks for a document that outlines how scope, schedule, cost, quality, risk, and communications will each be managed throughout delivery.\nWhat should the project manager produce?","exp":"D. A project management plan integrating all subsidiary plans and establishing how the project will be executed, monitored, and controlled.\n\nExplanation: The project management plan is the document that consolidates all subsidiary plans into a single integrated reference for how the project will be delivered. When the sponsor asks how scope, schedule, cost, quality, risk, and communications will each be managed, the plan is the artifact that answers all of those questions in one place.\n\nWhy the other options are incorrect:\n\nA communications management plan addresses one dimension of project management. It is a subsidiary plan that feeds into the project management plan, not a substitute for it.\n\nA work breakdown structure decomposes the project scope into deliverables and work packages. It is a planning tool, not a document that addresses execution, monitoring, or control.\n\nA project charter formally authorizes the project and empowers the project manager. It is produced during initiation and does not describe how the project will be managed once work begins.","ans":"D","hint":""},{"n":162,"opts":{"A":"Convert the entire project to a single predictive approach.","B":"Define and communicate clear progress metrics for each part.","C":"Report progress only for the predictive portion to simplify updates.","D":"Tell stakeholders that hybrid projects cannot be measured uniformly."},"q":"A project manager leads a hybrid project. The predictive portion follows a detailed plan, while the agile portion uses iterations. Stakeholders are confused about how progress is being measured across the two parts.\nWhat should the project manager do?","exp":"B. Define and communicate clear progress metrics for each part.\n\nExplanation: A hybrid project legitimately uses different measures for its predictive and agile components, such as earned value for one and velocity or burndown for the other. Defining and communicating appropriate metrics for each part resolves the confusion while respecting how each portion is run.\n\nWhy the other options are incorrect:\n\nConverting everything to predictive discards the benefits of the agile portion to solve a reporting clarity problem.\n\nReporting only the predictive portion leaves stakeholders blind to a significant part of the work.\n\nClaiming hybrid progress cannot be measured is inaccurate and abandons the project manager’s reporting responsibility.","ans":"B","hint":""},{"n":163,"opts":{"A":"Meet with the stakeholder to understand the source of the resistance.","B":"Exclude the stakeholder from future project meetings.","C":"Proceed with the project and ignore the resistance.","D":"Report the stakeholder’s behavior to the sponsor."},"q":"A project manager notices that a stakeholder who was previously supportive has become resistant after a recent scope change. The stakeholder has started questioning project decisions in meetings.\nWhat should the project manager do?","exp":"A. Meet with the stakeholder to understand the source of the resistance.\n\nExplanation: A shift from support to resistance signals an unmet concern. Meeting with the stakeholder to understand what changed allows the project manager to address the underlying issue and re-engage them, which is central to managing stakeholder engagement.\n\nWhy the other options are incorrect:\n\nExcluding the stakeholder deepens disengagement and removes the chance to recover their support.\n\nIgnoring the resistance lets it grow and potentially influence others against the project.\n\nReporting the behavior to the sponsor escalates prematurely before the project manager has even spoken with the stakeholder directly.","ans":"A","hint":""},{"n":164,"opts":{"A":"Adopt the communication preferences of the largest department.","B":"Let each department communicate however it prefers.","C":"Facilitate agreement on shared communication norms for the team.","D":"Require all communication to occur only through formal reports."},"q":"During a project kickoff, the project manager realizes that team members from different departments have very different expectations about how often and through what channels they will communicate.\nWhat should the project manager do?","exp":"C. Facilitate agreement on shared communication norms for the team.\n\nExplanation: Cross-departmental teams need a common understanding of how they will communicate. Facilitating agreement on shared norms early aligns expectations, prevents miscommunication, and gives every member ownership of the approach.\n\nWhy the other options are incorrect:\n\nDefaulting to the largest department’s preferences alienates the others and ignores their legitimate needs.\n\nLetting each department do its own thing recreates the very inconsistency that causes confusion and missed information.\n\nMandating only formal reports is rigid, slows collaboration, and likely fits no one’s actual working style.","ans":"C","hint":""},{"n":165,"opts":{"A":"Assume the benefits are being realized since the release succeeded.","B":"Wait until the project closes to assess all benefits at once.","C":"Ask the team to estimate the benefits based on their judgment.","D":"Establish measures to track benefits realization against the plan."},"q":"A project manager is overseeing a project where benefits were expected to begin accruing after the first release. Following the release, the project manager has no way to confirm whether the expected benefits are actually being realized.\nWhat should the project manager do?","exp":"D. Establish measures to track benefits realization against the plan.\n\nExplanation: Benefits realization should be measured against the benefits management plan so the organization can confirm the project is delivering intended value. Establishing concrete measures lets the project manager verify whether benefits are accruing and respond if they are not.\n\nWhy the other options are incorrect:\n\nAssuming benefits are realized because the release worked confuses output with outcome; a successful release does not guarantee value is being captured.\n\nWaiting until closure forfeits the chance to correct course while benefits could still be improved.\n\nRelying on team estimates substitutes opinion for actual measurement of realized value.","ans":"D","hint":""},{"n":166,"opts":{"A":"Allow the team to continue since increments are being delivered.","B":"Ensure the team holds regular retrospectives to drive improvement.","C":"Personally document process improvements for the team to follow.","D":"Add a dedicated process-improvement phase at the end of the project."},"q":"An agile team is consistently delivering working increments, but the project manager notices the team rarely reflects on how to improve its own processes between iterations.\nWhat should the project manager do?","exp":"B. Ensure the team holds regular retrospectives to drive improvement.\n\nExplanation: The retrospective is the agile event where the team inspects its own process and commits to improvements. Ensuring it happens regularly enables continuous improvement and keeps the team’s effectiveness growing over time.\n\nWhy the other options are incorrect:\n\nLetting the team continue without reflection forgoes the steady gains that retrospectives produce, even if delivery currently looks fine.\n\nHaving the project manager document improvements removes ownership from the team, which undercuts the self-improving nature of agile teams.\n\nA single improvement phase at the end delays learning that should be applied iteration to iteration.","ans":"B","hint":""},{"n":167,"opts":{"A":"Attempt alternative approaches to re-engage the CCO.","B":"Proceed with the milestone to maintain the project schedule and document the CCO’s nonresponse in the risk register.","C":"Escalate to executive leadership.","D":"Revise the project plan to reduce dependency on the CCO."},"q":"A project manager is leading a regulatory compliance project. The Chief Compliance Officer was actively engaged during planning but has since stopped attending review meetings and is not responding to emails. The project’s next milestone is approaching and the sponsor suggests proceeding, noting that the CCO’s silence could be interpreted as tacit approval.\nWhat should the project manager do?","exp":"A. Attempt alternative approaches to re-engage the CCO.\n\nExplanation: A key stakeholder becoming disengaged does not eliminate their role in the project. In a regulatory compliance context, the CCO’s involvement is not optional. The PM should try different channels, adjust communication formats, or address whatever is causing the disengagement before escalating or proceeding. If re-engagement efforts fail and the milestone still depends on compliance input or approval, the project manager should then escalate through the proper governance path rather than proceed without it.\n\nWhy the other options are incorrect:\n\nLogging the CCO’s non-response in the risk register treats an active engagement gap as an acceptable documented risk rather than an issue to be resolved. It also does not protect the project from the consequences of proceeding without a key compliance stakeholder.\n\nEscalating to executive leadership may be appropriate if re-engagement fails, but it is premature before alternative approaches have been tried.\n\nReducing dependency on the CCO in a regulatory compliance project is not a decision the PM can make unilaterally and may compromise the project’s compliance standing entirely.","ans":"A","hint":""},{"n":168,"opts":{"A":"Analyze options to compress the schedule and evaluate their trade-offs.","B":"Inform the regulator that the deadline will not be met.","C":"Ignore the team’s concern and continue at the current pace.","D":"Immediately reduce the scope to whatever can be finished in time."},"q":"A project manager is leading a project in which a regulatory deadline is fixed and cannot move. Partway through, the team raises concerns that the current pace will not meet the deadline.\nWhat should the project manager do?","exp":"A. Analyze options to compress the schedule and evaluate their trade-offs.\n\nExplanation: With a fixed regulatory deadline at risk, the project manager should examine schedule compression options such as fast tracking or crashing and weigh their cost, quality, and risk trade-offs to find a viable path to the date.\n\nWhy the other options are incorrect:\n\nInforming the regulator of a miss concedes failure before exploring options that could still meet the deadline.\n\nIgnoring the team’s concern disregards a credible early warning and risks a regulatory violation.\n\nReducing scope immediately is a drastic step taken before less disruptive compression options have been evaluated.","ans":"A","hint":""},{"n":169,"opts":{"A":"Side with the more senior stakeholder to resolve it quickly.","B":"Facilitate a discussion to help the stakeholders reach a resolution.","C":"Make the decision unilaterally to avoid further delay.","D":"Escalate the disagreement to the sponsor without further action."},"q":"During execution, two stakeholders disagree strongly about a requirement, and each is lobbying the project manager to side with them. The disagreement is delaying a key decision.\nWhat should the project manager do?","exp":"B. Facilitate a discussion to help the stakeholders reach a resolution.\n\nExplanation: Facilitating a conversation between the two stakeholders surfaces their underlying interests and guides them toward a mutually acceptable resolution, which produces durable buy-in and is the project manager’s role as a neutral facilitator.\n\nWhy the other options are incorrect:\n\nSiding with the more senior stakeholder may resolve it fast but ignores merit and alienates the other party.\n\nDeciding unilaterally on a stakeholder requirement oversteps the project manager’s authority and leaves resentment.\n\nEscalating to the sponsor immediately skips the facilitation the project manager can and should attempt first.","ans":"B","hint":""},{"n":170,"opts":{"A":"Use a firm fixed-price contract.","B":"Avoid contracting until the scope is fully defined.","C":"Use a purchase order to keep the arrangement simple.","D":"Use a cost-reimbursable contract."},"q":"A project manager is managing procurement for a complex deliverable and must choose a contract type. The scope is not yet fully defined and is expected to evolve as work progresses.\nWhat should the project manager do?","exp":"D. Use a cost-reimbursable contract.\n\nExplanation: When scope is uncertain and expected to evolve, a cost-reimbursable contract is appropriate because it accommodates change without forcing the seller to price undefined work, distributing the scope risk in a way that fits the situation.\n\nWhy the other options are incorrect:\n\nA firm fixed-price contract requires well-defined scope; using it here would force inaccurate pricing and frequent change disputes.\n\nWaiting until scope is fully defined is unrealistic when scope is expected to evolve throughout the work.\n\nA purchase order suits simple, well-defined, low-value buys, not a complex deliverable with evolving requirements.","ans":"D","hint":""},{"n":171,"opts":{"A":"Stop responding to risks to preserve the remaining reserve.","B":"Request additional reserve without analyzing current usage.","C":"Review reserve usage and reassess remaining risk exposure.","D":"Transfer all remaining risks to a third party immediately."},"q":"A project manager finds that the project’s risk responses are consuming significant contingency reserve early in the project, raising concern about whether enough reserve will remain for later risks.\nWhat should the project manager do?","exp":"C. Review reserve usage and reassess remaining risk exposure.\n\nExplanation: Reviewing how the contingency reserve is being consumed against the remaining risk exposure tells the project manager whether the reserve is adequate. This reassessment provides the basis for any justified request to replenish reserve or adjust risk responses.\n\nWhy the other options are incorrect:\n\nStopping risk responses to preserve reserve leaves active threats unmanaged, which is more dangerous than the reserve concern.\n\nRequesting more reserve without analysis lacks the justification a sponsor would reasonably require.\n\nTransferring all remaining risks is rarely feasible or cost-effective and is a blanket move made without analysis.","ans":"C","hint":""},{"n":172,"opts":{"A":"Meet privately with the team member to find the cause and solution.","B":"Publicly address the missed deadlines during the next team meeting.","C":"Remove the dependent tasks from this team member entirely.","D":"Tolerate the delays because the team member is highly skilled."},"q":"A project manager leads a team where one member is highly skilled but frequently misses internal deadlines, causing dependent tasks to slip. Other team members are growing frustrated.\nWhat should the project manager do?","exp":"A. Meet privately with the team member to find the cause and solution.\n\nExplanation: A private conversation respects the individual while uncovering why deadlines are being missed, so the project manager and team member can agree on a workable solution. This addresses the root cause without embarrassing a valuable contributor.\n\nWhy the other options are incorrect:\n\nPublicly addressing the issue risks humiliating the member and damaging trust within the team.\n\nRemoving dependent tasks may waste the member’s valuable skills and does not resolve the underlying behavior.\n\nTolerating the delays sacrifices the schedule and lets the other members’ frustration continue to build.","ans":"A","hint":""},{"n":173,"opts":{"A":"Plan structured team integration activities before the phase begins to help the expanded team establish working norms.","B":"Conduct technical onboarding sessions focused on the codebase and tools so the new developers can contribute immediately.","C":"Schedule a kickoff meeting to introduce the new developers and align the full team on phase objectives.","D":"Ask a senior team member to coordinate the new developers’ integration informally during the first sprint."},"q":"A software development team has been working together for eight months and is about to begin a critical delivery phase. Four senior developers with extensive industry experience are being added to support the increased workload. The phase begins in one week.\nWhat should the project manager do?","exp":"A. Plan structured team integration activities before the phase begins to help the expanded team establish working norms.\n\nExplanation: Team dynamics reset when membership changes significantly, regardless of how experienced the new members are or how well the existing team has performed. Structured integration activities address the working norms, communication patterns, and trust-building that a newly expanded team needs to re-establish before performing effectively.\n\nWhy the other options are incorrect:\n\nTechnical onboarding addresses knowledge transfer but not team dynamics. Experienced developers may need little ramp-up on tools and process, but they still need to establish working relationships with a team that has eight months of shared history.\n\nA kickoff meeting creates alignment on objectives but is a single event, not a sustained response to the team development need that significant membership changes introduce.\n\nInformal coordination by a senior team member delegates integration responsibility without structured support. Ad hoc approaches to team development tend to produce inconsistent results when the composition change is as significant as four simultaneous additions.","ans":"A","hint":""},{"n":174,"opts":{"A":"End the daily standup since it is no longer productive.","B":"Refocus the standup on team coordination rather than reporting to the PM.","C":"Replace the standup with written status updates submitted to the PM.","D":"Extend the standup so all status details can be fully covered."},"q":"A project manager observes that the daily standup has turned into a lengthy status report to the project manager, with team members no longer coordinating with one another.\nWhat should the project manager do?","exp":"B. Refocus the standup on team coordination rather than reporting to the PM.\n\nExplanation: The daily standup exists for the team to synchronize and plan their day together, not to report to a manager. Refocusing it on peer coordination restores its purpose and keeps it short and valuable.\n\nWhy the other options are incorrect:\n\nEnding the standup removes an important coordination event instead of fixing how it is used.\n\nReplacing it with written updates to the project manager reinforces the very status-reporting dynamic that broke its purpose.\n\nExtending the standup makes an already misused meeting longer rather than redirecting it.","ans":"B","hint":""},{"n":175,"opts":{},"q":"Match each scenario with the most appropriate negative risk response strategy.","matching":{"choices":["Avoid","Mitigate","Transfer","Accept"],"scenarios":{"A":"A construction project is scheduled during hurricane season. The project manager changes the schedule so all outdoor work is completed before hurricane season begins.","B":"A software project has a small chance of minor reporting defects after deployment. The team decides to monitor the risk because the impact is minimal and no cost-effective response is available.","C":"A company is building a new office tower. The project manager purchases builder’s risk insurance to reduce the organization’s financial exposure if severe weather damages the site.","D":"A project team identifies a moderate risk that a critical supplier may deliver materials late. The project manager adds an alternate supplier and increases delivery inspections to reduce the likelihood and impact of delays."}},"exp":"Scenario A is Avoid because the project manager changes the project schedule so the outdoor work is completed before hurricane season begins, eliminating exposure to the risk.\n\nScenario B is Accept because the team decides to monitor the risk without taking additional action since the probability and impact are low and no practical response is available.\n\nScenario C is Transfer because purchasing builder’s risk insurance shifts the financial consequences of severe weather damage to the insurance provider rather than the organization. The risk itself still exists, but the financial responsibility is transferred to another party.\n\nScenario D is Mitigate because adding an alternate supplier and increasing delivery inspections reduces both the likelihood of late deliveries and their potential impact on the project. Rather than eliminating or transferring the risk, the project manager takes proactive steps to lessen its effect.","ans":{"A":"Avoid","B":"Accept","C":"Transfer","D":"Mitigate"},"hint":""},{"n":176,"opts":{"A":"Allow the shortcut to stand since the deliverable appears to function.","B":"Quietly correct the deliverable without involving anyone else.","C":"Address the safety issue transparently and ensure it is corrected.","D":"Reprimand the team member and consider the matter closed."},"q":"A project manager is informed by a team member that a small but deliberate shortcut was taken on a safety-related deliverable to save time, and it was not reported.\nWhat should the project manager do?","exp":"C. Address the safety issue transparently and ensure it is corrected.\n\nExplanation: Safety and integrity are non-negotiable professional responsibilities. The project manager must address the issue openly, ensure the deliverable is brought to standard, and document it appropriately, regardless of the time pressure that prompted the shortcut.\n\nWhy the other options are incorrect:\n\nAllowing the shortcut to stand accepts a deliberate compromise of safety, which is unacceptable.\n\nQuietly correcting it hides a safety issue that should be transparently handled and may need to be disclosed.\n\nReprimanding the member and closing the matter punishes the person but does not confirm the safety deliverable has actually been corrected.","ans":"C","hint":""},{"n":177,"opts":{"A":"Resource leveling","B":"Resource smoothing","C":"Crashing","D":"Fast-tracking"},"q":"A project manager reviewing the resource plan discovers that a senior engineer is assigned to two parallel activities during the same two-week period, creating an overallocation. One activity is on the critical path. The other has four days of total float. The non-critical activity can be delayed within its available float. The project deadline cannot be moved.\nWhich technique should the project manager apply?","exp":"B. Resource smoothing\n\nExplanation: Resource smoothing adjusts activities within their available float to resolve overallocation without affecting the project end date. The non-critical activity has four days of float, which provides exactly the flexibility needed to eliminate the overlap. Since the deadline is fixed, a technique that preserves the schedule is preferable to one that may extend it.\n\nWhy the other options are incorrect:\n\nResource leveling resolves overallocation by adjusting activity dates based on resource constraints, but it may extend the project schedule. With float available, extending the schedule is unnecessary.\n\nCrashing adds resources to critical path activities to shorten duration. The problem here is overallocation, not schedule compression, so crashing addresses the wrong constraint.\n\nFast-tracking overlaps sequential activities to compress the schedule. Like crashing, it is a schedule compression technique and does not address resource overallocation.","ans":"B","hint":""},{"n":178,"opts":{"A":"Close the project since the customer is already using the deliverable.","B":"Obtain formal acceptance of the deliverable before closing the project.","C":"Remove the deliverable from the project records to simplify closure.","D":"Ask the team to re-deliver the item to trigger a new acceptance."},"q":"A project manager is closing out a project and finds that one minor deliverable was never formally accepted by the customer, although the customer has been using it for weeks.\nWhat should the project manager do?","exp":"B. Obtain formal acceptance of the deliverable before closing the project.\n\nExplanation: Formal acceptance of all deliverables is required to properly close a project, providing a clear record that the customer has approved the work. The project manager should secure that acceptance before completing closure, even though the customer is already using the item.\n\nWhy the other options are incorrect:\n\nClosing without formal acceptance leaves an incomplete record and potential disputes about whether the deliverable met requirements.\n\nRemoving the deliverable from the records falsifies project documentation and ignores work that was actually delivered.\n\nRe-delivering an item the customer already uses is unnecessary and wastes effort when a simple acceptance step suffices.","ans":"B","hint":""},{"n":179,"opts":{"A":"Approve shipping the feature since passing functional tests demonstrates the feature works as intended and Agile aims to deliver value as soon as possible.","B":"Extend the sprint by two days to give the team enough time to complete the required quality steps.","C":"Advise the team to carry the feature into the next sprint rather than ship it without completing the required quality steps.","D":"Ask the product owner whether the feature’s business priority justifies shipping it without the quality steps."},"q":"Two days before a sprint ends, the team realizes they will not have enough time to complete the unit testing and security scanning required for a feature they have been building. A team member suggests shipping the feature now and handling the remaining quality steps in the next sprint, since it has passed all functional tests and can provide value to the customer right now.\nWhat should the project manager do?","exp":"C. Advise the team to carry the feature into the next sprint rather than ship it without completing the required quality steps.\n\nExplanation: Delivering value early is a legitimate agile goal, but it does not override the team’s agreed-upon completion standard. Agile values completed, usable increments that meet the team’s Definition of Done. If required testing and security validation are incomplete, the feature is not done. Skipping unit testing and security scanning defers risk rather than delivering value, particularly when security gaps may affect the customer directly.\n\nWhy the other options are incorrect:\n\nAgile encourages early delivery, but only for work that satisfies the agreed completion and quality standards. Passing functional tests alone does not make the feature done.\n\nSprints are fixed timeboxes. Incomplete work should be replanned, not accommodated by extending the sprint.\n\nThe product owner prioritizes backlog items but does not override the team’s required quality criteria. Work that has not met the Definition of Done should not be released as complete.","ans":"C","hint":""},{"n":180,"opts":{},"q":"Match each team scenario to the correct stage of Tuckman’s Ladder.","matching":{"choices":["Norming","Forming","Performing","Storming"],"scenarios":{"A":"Team members have just joined the project. They are polite, asking questions about their responsibilities, and looking to the project manager for direction.","B":"The team has established working agreements, openly shares knowledge, and resolves disagreements constructively while building trust.","C":"Team members disagree about priorities, challenge each other’s ideas during meetings, and conflict has started affecting collaboration.","D":"The team consistently meets sprint goals with minimal supervision. Members proactively solve problems, collaborate effectively, and focus on delivering value."}},"exp":"Scenario A is Forming because the team is new, members are learning their roles, and they rely on the project manager for guidance.\n\nScenario B is Norming because the team has established working agreements, built trust, and works together effectively while resolving disagreements constructively.\n\nScenario C is Storming because team members disagree about priorities, challenge each other’s ideas, and conflict is affecting collaboration. This stage is characterized by tension as the team works through differences and competing viewpoints.\n\nScenario D is Performing because the team consistently delivers results with minimal supervision, collaborates effectively, proactively solves problems, and remains focused on achieving project objectives and delivering value.","ans":{"A":"Forming","B":"Norming","C":"Storming","D":"Performing"},"hint":""}];
QDATA.pmpsims=PMP_MOCK_RAW;

function inferBookExamDomain(q){
  const t=((q.q||'')+' '+(q.caseTitle||'')+' '+(q.caseText||'')+' '+Object.values(q.opts||{}).join(' ')).toLowerCase();
  if(/stakeholder|team member|team conflict|leadership|servant leader|coach|mentor|resource manager|communication|collaborat|psychological safety|product owner|scrum master/.test(t))return 'People';
  if(/business value|business case|strategy|strategic|governance|compliance|regulat|sustainab|artificial intelligence|ai|ethic|privacy|environmental|organizational change/.test(t))return 'Business';
  return 'Process';
}
function inferBookExamApproach(q){
  const t=((q.q||'')+' '+(q.caseText||'')+' '+Object.values(q.opts||{}).join(' ')).toLowerCase();
  if(/hybrid/.test(t))return 'Hybrid';
  if(/agile|scrum|sprint|product backlog|product owner|iteration|kanban|velocity|retrospective|standup/.test(t))return 'Agile';
  return 'Predictive';
}
function normalizeBookMockQuestion(q,i){
  const base={
    bankId:'book-mock-'+(i+1),
    source:'PMP Exam Prep Simplified (2026) - Full Length Mock',
    n:q.n,
    domain:inferBookExamDomain(q),
    approach:inferBookExamApproach(q),
    q:(q.caseText?((q.caseTitle?q.caseTitle+'\n\n':'')+q.caseText+'\n\n'):'')+(q.q||''),
    exp:q.exp||'',
    image:q.image||null
  };
  if(q.multi){
    return Object.assign(base,{type:'multi',pick:q.pick||((q.ans||[]).length),opts:q.opts||{},ans:q.ans||[]});
  }
  if(q.matching){
    const choices=q.matching.choices||[];
    const right={};choices.forEach((v,idx)=>right[String(idx+1)]=v);
    const ans={};Object.keys(q.matching.scenarios||{}).forEach(k=>{
      const idx=choices.indexOf(q.ans&&q.ans[k]);ans[k]=String(idx+1);
    });
    return Object.assign(base,{type:'matching',left:q.matching.scenarios||{},right,ans});
  }
  return Object.assign(base,{opts:q.opts||{},ans:q.ans});
}

const BOOK_MOCK_BANK=(QDATA.pmpsims||[]).map(normalizeBookMockQuestion);
const EXAM_FULL_BANK=[
  ...EXAM_BANK_RAW.map((q,i)=>Object.assign({bankId:'core-'+(i+1),source:'ExamPro Core Bank'},q)),
  ...BOOK_REVIEW_BANK.map((q,i)=>Object.assign({bankId:q.id||('book-review-'+(i+1))},q)),
  ...BOOK_MOCK_BANK
];
const EXAM_BANK_STATS={
  total:EXAM_FULL_BANK.length,
  bookTotal:BOOK_REVIEW_BANK.length+BOOK_MOCK_BANK.length,
  chapterReview:BOOK_REVIEW_BANK.length,
  fullMock:BOOK_MOCK_BANK.length
};
;
